  ('9f6ac290-11fb-5e4a-add4-40458606ab8d', '4b709bad-a55e-5110-ac67-14ccc996c2c1', '5fa07c85-4625-549f-a45a-fcd119810213', 20, 20, 'ዘመኑ ለክፉዎች አይሆንምና'),
