  ('527d9c00-04d7-5c5e-a840-d8a14b1f29a5', '4b709bad-a55e-5110-ac67-14ccc996c2c1', '5fa07c85-4625-549f-a45a-fcd119810213', 24, 24, 'ከንጉሥ አንደበት ምንም ሐሰት ይነገራል አይባልም፥'),
