  ('9b3b4dfb-51a5-54e1-ab36-f187c87430e2', '82302d0e-c53a-5c71-aa38-384490986ff3', 'c8b3645b-7809-5f1f-a71b-7cf48e4a893d', 15, 15, 'የበፍታ ቀሚስ እየሠራች ትሸጣለች።'),
  ('fe4a769a-58e2-58a7-a88b-cb7f4e1c46e7', '82302d0e-c53a-5c71-aa38-384490986ff3', 'c8b3645b-7809-5f1f-a71b-7cf48e4a893d', 16, 16, 'ብርታትንና ውበትን ትለብሳለች፤'),
  ('1c78ee7a-bda9-536e-a555-6415b78b5ba9', '82302d0e-c53a-5c71-aa38-384490986ff3', 'c8b3645b-7809-5f1f-a71b-7cf48e4a893d', 17, 17, 'ወደ ቤትዋ የሚገባ ብዙ ነው፥'),
  ('290e1a45-6608-53d8-a2fe-74f82eec8a87', '82302d0e-c53a-5c71-aa38-384490986ff3', 'c8b3645b-7809-5f1f-a71b-7cf48e4a893d', 18, 18, 'ሕግና ምጽዋት በአፍዋ አለ፥'),
  ('ca4f6a06-28f2-5948-a61f-daef46d343cb', '82302d0e-c53a-5c71-aa38-384490986ff3', 'c8b3645b-7809-5f1f-a71b-7cf48e4a893d', 19, 19, 'ምጽዋቷ ልጆችዋን ያሳድጋል፥ ያበለጥጋልም፤'),
  ('b43371a3-a00b-5e9a-a163-59ce1096eef5', '82302d0e-c53a-5c71-aa38-384490986ff3', 'c8b3645b-7809-5f1f-a71b-7cf48e4a893d', 20, 20, '“ብዙ ሴቶች ልጆች ሀብትን ሰበሰቡ፤'),
  ('9dfaccb2-dcbc-5cd0-ae14-e44e0587ee86', '82302d0e-c53a-5c71-aa38-384490986ff3', 'c8b3645b-7809-5f1f-a71b-7cf48e4a893d', 21, 21, 'ውበት ሐሰት ነው፥ ደምግባትም ከንቱ ነው፤'),
  ('7e6397ef-4e86-54c5-afa4-14c246a7d152', '82302d0e-c53a-5c71-aa38-384490986ff3', 'c8b3645b-7809-5f1f-a71b-7cf48e4a893d', 22, 22, 'ከከንፈሯ ፍሬ ስጡአት፥'),
  ('05d0fde4-5d33-5aec-a04a-383d14513952', 'b53d0335-d32f-51ab-abf9-ed94b50469cc', 'f1077803-c7fd-5600-a336-92f7c53a0c44', 1, 1, 'የምድር ገዥዎች ሆይ፥ ጽድቅን ውደዷት፥ የእግዚአብሔርንም ኀይል በበጎ ዕውቀት አስቡት፥ በቅን ልቡናም ፈልጉት።'),
  ('8e00f76d-8053-5f20-a068-972583dc1958', 'b53d0335-d32f-51ab-abf9-ed94b50469cc', 'f1077803-c7fd-5600-a336-92f7c53a0c44', 2, 2, 'በማይፈታተኑት ሰዎች ዘንድ እርሱ ይገኛልና። በማይክዱት ሰዎችም ዘንድ ይገለጣልና።'),
  ('c60ddb2a-ad45-5392-a7e8-a0472df64598', 'b53d0335-d32f-51ab-abf9-ed94b50469cc', 'f1077803-c7fd-5600-a336-92f7c53a0c44', 3, 3, 'ጠማማ አሳብ ከእግዚአብሔር ያርቃል፤ የተፈተነችም ኀይል አላዋቂዎችን ትዘልፋቸዋለች።'),
  ('602c5194-4903-5ddb-ac38-cab53f65ce81', 'b53d0335-d32f-51ab-abf9-ed94b50469cc', 'f1077803-c7fd-5600-a336-92f7c53a0c44', 4, 4, 'በተተነኰለች ሰውነት ጥበብ አትገባምና፤ ለኀጢአት በተገዛ ሰውነትም አታድርምና።'),
  ('9ebc62d8-c3a5-5119-a448-48d9c25435ae', 'b53d0335-d32f-51ab-abf9-ed94b50469cc', 'f1077803-c7fd-5600-a336-92f7c53a0c44', 5, 5, 'ተግሣጽን የሚገልጽ መንፈስ ቅዱስ ክፉውን ትምህርት ያርቃልና፥ ከሰነፎችም ልቡና ድል ነሥቶ ይሄዳልና በሚመጣም ጊዜ ክፉውን ይዘልፈዋል።'),
  ('5ccc1191-2718-5555-a70a-d11141a39682', 'b53d0335-d32f-51ab-abf9-ed94b50469cc', 'f1077803-c7fd-5600-a336-92f7c53a0c44', 6, 6, 'ጥበብን የሚገልጽ መንፈስ ሰው ወዳጅ ነውና፥ በከንፈሩ የሚሳደበውንም አያነጻውም። እግዚአብሔር በኵላሊቶቹ ምስክር ነውና፥ ነዋሪ ጕበኛም ልቡናውን ይመረምረዋል፤ አንደበቱንም ይሰማዋል።'),
  ('0ca8832c-ef27-58e1-a082-a1d756a35006', 'b53d0335-d32f-51ab-abf9-ed94b50469cc', 'f1077803-c7fd-5600-a336-92f7c53a0c44', 7, 7, 'የእግዚአብሔር መንፈስ ዓለሙን መልትዋልና። ዓለምንም ሁሉ የያዘው እርሱ ነገራቸውን ፈጽሞ ያውቃልና።'),
  ('3a8a092f-0450-5528-ad22-6b63352cf9b2', 'b53d0335-d32f-51ab-abf9-ed94b50469cc', 'f1077803-c7fd-5600-a336-92f7c53a0c44', 8, 8, 'ስለዚህ ከሚነገር ከዐመፃ ነገራቸው ምንም ከእርሱ አይሰወርም። ሥራውን በመግለጥ ፍርዱ አይተላለፈውምና።'),
  ('2cb77e11-8d43-5738-ab8c-6a0a0006f403', 'b53d0335-d32f-51ab-abf9-ed94b50469cc', 'f1077803-c7fd-5600-a336-92f7c53a0c44', 9, 9, 'ክፉዎችን በልቡናቸው ምክር ይመረምራቸዋልና፥ የነገራቸውም ድምፅ ለበደላቸው ዘለፋ ሊሆንባቸው ወደ እግዚአብሔር ይደርሳልና።'),
  ('4e899416-54ee-5ecb-a9f2-aeb31c682442', 'b53d0335-d32f-51ab-abf9-ed94b50469cc', 'f1077803-c7fd-5600-a336-92f7c53a0c44', 10, 10, 'ስለ ቅንአት ሥራውን ሁሉ የሚሰማ አይደለምና፥ የነጐርጓርም ድምፅ ከእርሱ አይሰወርም።'),
  ('ce6ead05-b4f5-51c8-a89b-f9563bf678a1', 'b53d0335-d32f-51ab-abf9-ed94b50469cc', 'f1077803-c7fd-5600-a336-92f7c53a0c44', 11, 11, 'ከማይረባ ነጐርጓር ተጠበቁ፤ ከሐሜትም አንደበታችሁን ከልክሉ፤ በስውር የሚሆን ነገር በከንቱ አይወጣምና፥ የሚወጋና የሚዋሽ አፍ ሰውን ይገድላልና።'),
  ('74f0a457-b499-537e-a832-641e747d2e2d', 'b53d0335-d32f-51ab-abf9-ed94b50469cc', '6465a7c6-573d-5f7c-ab01-30e6770f6682', 1, 12, 'በሕይወታችሁ ስሕተት ለሞት አትቅኑ፤ በእጃችሁም ሥራ ጥፋትን አታምጡ።'),
  ('c1d014a5-cc6e-5bbb-a602-c5577230ebac', 'b53d0335-d32f-51ab-abf9-ed94b50469cc', '6465a7c6-573d-5f7c-ab01-30e6770f6682', 2, 13, 'እግዚአብሔር ሞትን አልፈጠረምና፤ የሕያዋንም ጥፋት ደስ አያሰኘውምና።'),
  ('bd8b1066-3967-530a-a48f-1b324ea8c94f', 'b53d0335-d32f-51ab-abf9-ed94b50469cc', '6465a7c6-573d-5f7c-ab01-30e6770f6682', 3, 14, 'ነዋሪ ይሆን ዘንድ ፍጥረቱን ፈጥሮአልና፥ የዓለም መፈጠርም ለድኅነት ነውና፥ በእነርሱም ዘንድ የጥፋት መርዝ አልነበረምና፥ ለሲኦልም በምድር ላይ ግዛት አልነበረውምና።'),
  ('8c1e7311-1f97-5de5-a96d-2e9306a48241', 'b53d0335-d32f-51ab-abf9-ed94b50469cc', '6465a7c6-573d-5f7c-ab01-30e6770f6682', 4, 15, 'ጽድቅ አትሞትምና።'),
  ('a238af76-bd6e-5442-ad07-ecd0855e0a16', 'b53d0335-d32f-51ab-abf9-ed94b50469cc', '6465a7c6-573d-5f7c-ab01-30e6770f6682', 5, 16, 'ክፉዎች ግን በእጃቸውና በቃላቸው ጠሩት፥ ባልንጀራም አስመሰሉት። በእርሱም ጠፉ።'),
  ('ee45d5e6-3d91-5c18-adc3-48a8bcb2aa0a', 'b53d0335-d32f-51ab-abf9-ed94b50469cc', '6465a7c6-573d-5f7c-ab01-30e6770f6682', 6, 17, 'የእርሱ ወገን መሆን ይገባቸዋልና ከእርሱ ጋር ቃል ኪዳን አደረጉ።'),
  ('8bb79081-c28b-5d80-a3af-97d1405a8bd5', 'bf813a67-6ef3-5f77-a9ce-0498c7b8c3ba', '3065d27f-747e-5c89-a8cd-8d582a1c5f12', 1, 1, 'የቀና ነገርን ሳያስቡ ራሳቸው እንዲህ አሉ፥ ሕይወታችን ጥቂት ነው፥ የሚያሳዝንም ነው-። ለሰውም ሞት መድኀኒት የለውም፥ ከመቃብርም የተመለሰ የታወቀ የለምና።'),
  ('b100806b-57ba-53bd-a3b9-af6299fc6bea', 'bf813a67-6ef3-5f77-a9ce-0498c7b8c3ba', '3065d27f-747e-5c89-a8cd-8d582a1c5f12', 2, 2, 'እኛ በከንቱ ተፈጥረናልና ከዚህም በኋላ እንዳልተፈጠርን እንሆናለን፤ በአፍንጫችን ያለ ትንፋሻችን እንደ ጢስ ነውና። በልቡናችንም እንቅስቃሴ የብልጭልጭታ ቃል አለና።'),
  ('d4d51640-ac5e-5b9f-a044-409d417a1ece', 'bf813a67-6ef3-5f77-a9ce-0498c7b8c3ba', '3065d27f-747e-5c89-a8cd-8d582a1c5f12', 3, 3, 'ከሞተ በኋላ ሥጋችን ትቢያ ይሆናል፤ መንፈሳችንም እንደ ጉም ተን ይበተናልና።'),
  ('38b2a36a-6806-5078-acbd-21e593dd0b79', 'bf813a67-6ef3-5f77-a9ce-0498c7b8c3ba', '3065d27f-747e-5c89-a8cd-8d582a1c5f12', 4, 4, 'ስማችንም በጊዜ ይዘነጋል፤ ሥራችንንም የሚያስበው ማንም የለም፤ ሕይወታችንም እንደ ደመና ፍለጋ ያልፋል፤ እንደ ጉምም ይበተናል፤ በፀሐይ ጨረር እንደ ተበተነ፥ በሙቀቱም እንደ ቀለጠ ውርጭ ይሆናል።'),
  ('b03d7791-960f-5ac4-ac2c-becf972bea13', 'bf813a67-6ef3-5f77-a9ce-0498c7b8c3ba', '3065d27f-747e-5c89-a8cd-8d582a1c5f12', 5, 5, 'ሕይወታችንም እንደ ጥላ ያልፋልና፥ ይህ የተወሰነ ነገር ስለሆነ ለሞታችን መከልከል የለውም፤ ማንም አይመልሰውምና።'),
  ('6dfb1d8e-705e-5c06-a83d-85d127bc5596', 'bf813a67-6ef3-5f77-a9ce-0498c7b8c3ba', '3065d27f-747e-5c89-a8cd-8d582a1c5f12', 6, 6, 'ኑ ባለው መልካም ነገር ደስታን እናድርግ፤ በጐልማሳነታችንም ወራት ሳለን በመትጋት በሰውነታችን ደስ የሚያሰኘውን እናድርግ።'),
  ('0af3f228-cb31-5f3a-a8fc-80336e966bcb', 'bf813a67-6ef3-5f77-a9ce-0498c7b8c3ba', '3065d27f-747e-5c89-a8cd-8d582a1c5f12', 7, 7, 'ዋጋው ብዙ የሆነ ወይን እንጠጣ፤ የሚሸት ሽቱንም እንቀባ፤ የመፀው አበባም አይለፈን።'),
  ('c1cc36ec-e296-510f-a0e6-eda963acd0b6', 'bf813a67-6ef3-5f77-a9ce-0498c7b8c3ba', '3065d27f-747e-5c89-a8cd-8d582a1c5f12', 8, 8, 'ቡቃያችን ሳይጠወልግ ጽጌረዳን እንቀዳጅ፤ ከትዕቢታችን አበባ የማይሳተፍ ማንም አይኑር።'),
  ('45e59b90-bd2a-5f37-a202-905acfb6aea0', 'bf813a67-6ef3-5f77-a9ce-0498c7b8c3ba', '3065d27f-747e-5c89-a8cd-8d582a1c5f12', 9, 9, 'ከእኛ መካከል ደስታችን የማይገባው ሰው አይኑር፤ እርሱ ዕድላችን፥ ርስታችንም ነውና በየቦታው ለደስታችን ምልክት እንተው።'),
  ('a4e17d45-2cb5-56e6-ad9f-c7c7f86b1898', 'bf813a67-6ef3-5f77-a9ce-0498c7b8c3ba', '3065d27f-747e-5c89-a8cd-8d582a1c5f12', 10, 10, 'ጻድቁን ድሃ እንቀማ፤ ለባልቴቲቱም አንራራ፤ ዕድሜው ብዙ ከሆነ ከሽማግሌም ሽበት የተነሣ አንፈር።'),
  ('a36d82f8-8351-5c3b-a101-483e395cbff0', 'bf813a67-6ef3-5f77-a9ce-0498c7b8c3ba', '3065d27f-747e-5c89-a8cd-8d582a1c5f12', 11, 11, 'ኀይላችን የጽድቅ ሕግ ይሁነን፤ ደካማ ሕሊና የተናቀ ይባላልና።'),
  ('6e726932-32fb-5248-abc8-e35519e770df', 'bf813a67-6ef3-5f77-a9ce-0498c7b8c3ba', '3065d27f-747e-5c89-a8cd-8d582a1c5f12', 12, 12, 'ኑ፤ ጻድቁን እንግደለው፤ በእኛ ጭንቅና ጽኑዕ ሆኖብናልና፥ ሥራችንንም ይቃወማልና፤ ሕግ በማጣታችንም ያሽሟጥጠናልና፥ የትምህርታችንንም በደል ይሰብካልና።'),
  ('00a11a32-8266-5fbb-a5b8-1d87e4314a7f', 'bf813a67-6ef3-5f77-a9ce-0498c7b8c3ba', '3065d27f-747e-5c89-a8cd-8d582a1c5f12', 13, 13, '“እግዚአብሔርንም ማወቅ በእኔ አለ” ይላል፤ ራሱንም የእግዚአብሔር ልጅ ያደርጋል።'),
  ('3038d58e-95b9-5081-acb2-74ba36463163', 'bf813a67-6ef3-5f77-a9ce-0498c7b8c3ba', '3065d27f-747e-5c89-a8cd-8d582a1c5f12', 14, 14, 'ሕሊናችንንም የሚዘልፍ ሆኖብናል።'),
  ('9b626d4d-e951-5799-a56b-c8e0a26c293e', 'bf813a67-6ef3-5f77-a9ce-0498c7b8c3ba', '3065d27f-747e-5c89-a8cd-8d582a1c5f12', 15, 15, 'በመልኩም በእኛ ጭንቅ ሆኖብናል፤ አኗኗሩም ከሌላ ጋር አይመሳሰልም፤ መንገዱም ልዩ ነው።'),
  ('6531396c-fa5e-56e8-af87-bee8e5fbff4c', 'bf813a67-6ef3-5f77-a9ce-0498c7b8c3ba', '3065d27f-747e-5c89-a8cd-8d582a1c5f12', 16, 16, 'በእርሱ ዘንድም የተናቅን ሆነናል፤ ከርኵሰትም እንደሚርቅ ከመንገዳችን ይርቃል። የጻድቃንን መጨረሻ ያመሰግናል፤ እግዚአብሔርም አባቱ እንደ ሆነ ይመካል።'),
  ('e8ba8ef6-1398-5156-af6a-7b82f8868349', 'bf813a67-6ef3-5f77-a9ce-0498c7b8c3ba', '3065d27f-747e-5c89-a8cd-8d582a1c5f12', 17, 17, 'ነገሩም ቀዋሚ እንደ ሆነ እንይ፥ ከመልኩም የተነሣ የሚሆነውን እንመርምር።'),
  ('205828cc-a49b-5da7-a29a-cc6654bfee53', 'bf813a67-6ef3-5f77-a9ce-0498c7b8c3ba', '3065d27f-747e-5c89-a8cd-8d582a1c5f12', 18, 18, 'የእግዚአብሔርስ እውነተኛ ልጅ ከሆነ ያድነው፤ ከሚቃወሙትም እጅ ይታደገው።'),
  ('4201475e-3759-5aa3-aac6-8891da892b49', 'bf813a67-6ef3-5f77-a9ce-0498c7b8c3ba', '3065d27f-747e-5c89-a8cd-8d582a1c5f12', 19, 19, 'ቅንነቱንም እናውቅ ዘንድ በስድብና በመከራ እንመርምረው። ትዕግሥቱንም በክፉ እንፈትነው።'),
  ('8ca32079-87d8-5208-a46a-b9742bd705be', 'bf813a67-6ef3-5f77-a9ce-0498c7b8c3ba', '3065d27f-747e-5c89-a8cd-8d582a1c5f12', 20, 20, 'እንደ ቃሉ ረዳት ይሆነው እንደ ሆነ የከፋና የተዋረደ ሞትን እንፍረድበት።'),
  ('7599564f-0c4b-550d-a975-e6367683e4aa', 'bf813a67-6ef3-5f77-a9ce-0498c7b8c3ba', '289245a9-ac72-5d3d-a4f4-58cc57572948', 1, 21, 'ይህን ነገር አሰቡ፤ በዚህም ሳቱ፤ ክፋታቸው የልብ ዕውሮች አድርጋቸዋለችና።'),
  ('400ad95a-fa30-5555-a04c-35d83c9d5755', 'bf813a67-6ef3-5f77-a9ce-0498c7b8c3ba', '289245a9-ac72-5d3d-a4f4-58cc57572948', 2, 22, 'የእግዚአብሔርን ምሥጢር አላወቁም፤ የጻድቁንም ዋጋ ተስፋ አላደረጉም፤ ነውር የሌለባቸውን የንጹሐት ነፍሳትንም ብዙ ክብር አላወቁም።'),
  ('45d5a409-8a97-55cf-aed2-49306622e088', 'bf813a67-6ef3-5f77-a9ce-0498c7b8c3ba', '289245a9-ac72-5d3d-a4f4-58cc57572948', 3, 23, 'እግዚአብሔር ሰውን ያለ ሞት ፈጥሮታልና፥ በራሱም አምሳል ፈጥሮታልና።'),
  ('5b22696f-fb6c-5223-acc9-b53f47b5f088', 'bf813a67-6ef3-5f77-a9ce-0498c7b8c3ba', '289245a9-ac72-5d3d-a4f4-58cc57572948', 4, 24, 'ነገር ግን በዲያብሎስ ቅንዐት ሞት መጣ፥ ወደዚህ ዓለምም ገባ።'),
  ('2276dac0-cd9e-5515-a9f9-cb6c6121f2e9', 'bf813a67-6ef3-5f77-a9ce-0498c7b8c3ba', '289245a9-ac72-5d3d-a4f4-58cc57572948', 5, 25, 'ከእርሱም ድርሻ የሆኑት ሞትን ሞከሩት።'),
  ('183dbf52-c570-542b-a788-2b860392dd33', 'e40b23b1-104f-5525-afb9-52215010fd5c', '4685415a-a22d-53d3-ad3f-047ce70ebd78', 1, 1, 'የጻድቃን ነፍስ ግን በእግዚአብሔር እጅ ናት፤ መከራም አያገኛቸውም።'),
  ('0bfed3aa-f469-5374-a5f0-01b4c652151a', 'e40b23b1-104f-5525-afb9-52215010fd5c', '4685415a-a22d-53d3-ad3f-047ce70ebd78', 2, 2, 'በሰነፎች ዓይኖች ግን የሞቱ መሰሉ፤ በሞትም ከዚህ ዓለም መውጣታቸው ክፋት እንዳለባቸው ተቈጠረ።'),
  ('28406fca-1d14-546f-a70a-3a225373cca9', 'e40b23b1-104f-5525-afb9-52215010fd5c', '4685415a-a22d-53d3-ad3f-047ce70ebd78', 3, 3, 'ሞታቸውም ጥፋት መሰለ፤ እነርሱ ግን በሰላም አሉ።'),
  ('0c873591-014a-508c-af07-9f4612cfe2db', 'e40b23b1-104f-5525-afb9-52215010fd5c', '4685415a-a22d-53d3-ad3f-047ce70ebd78', 4, 4, 'በሰው ፊትም ቢፈረድባቸው ተስፋቸው በእግዚአብሔር ዘንድ ሞት የሌለባት ፍጽምት ሕይወት ናት።'),
  ('8777b437-3a50-5da6-ac56-f13609e039fa', 'e40b23b1-104f-5525-afb9-52215010fd5c', '4685415a-a22d-53d3-ad3f-047ce70ebd78', 5, 5, 'ጥቂት መከራ ተቀብለው ብዙ ክብር ያገኛሉ። እግዚአብሔር ፈትኗቸው ለእርሱ የተገቡ ሆነው አግኝትዋቸዋልና።'),
  ('6623662b-1940-5eb8-af3b-51c6e6e64db5', 'e40b23b1-104f-5525-afb9-52215010fd5c', '4685415a-a22d-53d3-ad3f-047ce70ebd78', 6, 6, 'ወርቅ በከውር እንዲፈተን ፈተናቸው፤ እንደሚቃጠል መሥዋዕትም ተቀበላቸው።'),
  ('29f43df4-06f8-5d87-a97a-35155c546b14', 'e40b23b1-104f-5525-afb9-52215010fd5c', '4685415a-a22d-53d3-ad3f-047ce70ebd78', 7, 7, 'በሚጐበኙበትም ወራት እንደ ፀሐይ ያበራሉ፤ በብርዕ ላይ የወደቀ የእሳት ፍንጣሪ እንዲሰፋ በክብር እየሰፉ ይሄዳሉ።'),
  ('8ca114f5-8d4a-5278-a47e-f4f499db61bc', 'e40b23b1-104f-5525-afb9-52215010fd5c', '4685415a-a22d-53d3-ad3f-047ce70ebd78', 8, 8, 'አሕዛብን ይገዛሉ፤ በሕዝብም ላይ ይሠለጥናሉ፤ እግዚአብሔርም ለዘለዓለም ይነግሥላቸዋል።'),
  ('0ba097c5-aed4-5924-a301-b6cf26c35a6a', 'e40b23b1-104f-5525-afb9-52215010fd5c', '4685415a-a22d-53d3-ad3f-047ce70ebd78', 9, 9, 'በእርሱ የሚያምኑ ሰዎች እውነትን ያውቃሉ፤ ጸጋና ምሕረት ለመረጣቸው ነውና፥ የተገለጠ ጕብኝቱም ለጻድቃኑ ነውና ምእመናን በእርሱ ፍቅር ጸንተው ይኖራሉ።'),
  ('a040e3f6-8b0f-5073-ac1e-34d208f8018e', 'e40b23b1-104f-5525-afb9-52215010fd5c', 'eef441bd-5643-5c00-a3cc-858129b74598', 1, 10, 'ክፉዎች ሰዎች ግን እንዳሰቡ ክፉ ፍርድን ያገኛሉ፥ እውነትንም ያቀለሉ ሰዎች ከእግዚአብሔር ራቁ።'),
  ('671291a8-b7c5-5e51-a72f-6c6740f221de', 'e40b23b1-104f-5525-afb9-52215010fd5c', 'eef441bd-5643-5c00-a3cc-858129b74598', 2, 11, 'ጥበብንና ተግሣጽን የሚንቁ ሰዎች ጐስቋሎች ናቸው፤ አለኝታቸው ከንቱ ነው፤ ድካማቸውም፥ መከራቸውም ጥቅም የሌለው ነው፤ ሥራቸውም ከንቱ ነው፤'),
  ('2f68b0cd-acb1-5755-a8c9-7780521173c1', 'e40b23b1-104f-5525-afb9-52215010fd5c', 'eef441bd-5643-5c00-a3cc-858129b74598', 3, 12, 'ሚስቶቻቸውም ሰነፎች ናቸው፤ ልጆቻቸውም ጠማሞች ናቸው፤ ትውልዳቸውም የተረገመ ነው።'),
  ('582f5e3c-0b08-5a9b-a510-dfab0f6c0697', 'e40b23b1-104f-5525-afb9-52215010fd5c', '0673558d-4dc9-50e9-a91d-1468c108f2a7', 1, 13, 'ነውር የሌለባት፥ የኀጢአት ምንጣፍ የማታውቅ መካን ሴት ብፅዕት ናት፥ ከኀጢአትም የነጻች ናት፥ ይህች እንዲህ ያለችው ሴት ነፍሳት በሚጐበኙበት ጊዜ ፍሬ ታገኛለች።'),
  ('75a046b6-8235-54f5-a736-5d4257fa700c', 'e40b23b1-104f-5525-afb9-52215010fd5c', '0673558d-4dc9-50e9-a91d-1468c108f2a7', 2, 14, 'የተመረጠች የሃይማኖት ዋጋ ትሰጠዋለችና፥ በሚወደድ በእግዚአብሔርም ቤት ዕድሉ ይሰጠዋልና በእጁ በደልን ያልሠራ፥ በእግአብሔርም ላይ ክፉ ነገርን ያላሰበ ጃንደረባም ብፁዕ ነው።'),
  ('4329c8e7-4353-581d-adc9-45557f014824', 'e40b23b1-104f-5525-afb9-52215010fd5c', '0673558d-4dc9-50e9-a91d-1468c108f2a7', 3, 15, 'የደግ ሰው የድካሙ ፍሬ ክብርና ጌጥ ነው፤ ለዕውቀቱም ሥር ውድቀት የለበትም።'),
  ('a79db1a6-3589-53d2-afc6-1c10c6477ec4', 'e40b23b1-104f-5525-afb9-52215010fd5c', '0673558d-4dc9-50e9-a91d-1468c108f2a7', 4, 16, 'ያመንዝራዎች ልጆች ግን ከቍጥር የጐደሉ ይሆናሉ። ከሕግ ተላላፊ መኝታ የተወለደ ልጅም ይጠፋል።'),
  ('5caaadb9-d5fe-5ab7-a75d-884065c78f8a', 'e40b23b1-104f-5525-afb9-52215010fd5c', '0673558d-4dc9-50e9-a91d-1468c108f2a7', 5, 17, 'ኑሮአቸውም በምድር ላይ ቢበዛ ምንም አይቈጠርም፤ ሽምግልናቸውም በፍጻሜያቸው የጐሰቈለ ይሆናል።'),
  ('0369d923-b8ca-5aad-aaca-42756e45a505', 'e40b23b1-104f-5525-afb9-52215010fd5c', '0673558d-4dc9-50e9-a91d-1468c108f2a7', 6, 18, 'ፈጥነውም ቢሞቱ በፍርድ ቀን ተስፋና መጽናናት አይኖራቸውም።'),
  ('0f58f5d9-648e-597f-a66f-616b30024879', 'e40b23b1-104f-5525-afb9-52215010fd5c', '0673558d-4dc9-50e9-a91d-1468c108f2a7', 7, 19, 'ለዐመፀኛ ትውልድ ፍጻሜዋ ክፉ ነውና።'),
  ('d427c22c-87f9-5b1c-a625-c93ebcaa2ef5', 'c4010cb6-3ce4-59fb-a106-1535ae5fd3a1', 'fab77aef-c1ef-5def-ad14-c29703f59fe0', 1, 1, 'ከበጎነት ጋር አለመውለድ ፍጹም ሥራ ነው፤ በእግአብሔር ዘንድ፥ በሰውም ዘንድ የታወቀች ስለ ሆነች ስም አጠራሯ ሕይወት ነውና።'),
  ('d46fe2e2-18de-52ed-ad7a-8b28e448825e', 'c4010cb6-3ce4-59fb-a106-1535ae5fd3a1', 'fab77aef-c1ef-5def-ad14-c29703f59fe0', 2, 2, 'በዚህ ዓለም ሳለችም ያከብሯታል፤ ካለፈችም በኋላ ፈጽመው ይወድዷታል፤ በዚህም ዓለም የገድል ድልን እግኝታ፥ የማያልፍ አክሊልንም ተቀዳጅታ ትኖራለች።'),
  ('05e33844-cc50-5872-a4f1-33f2a325426e', 'c4010cb6-3ce4-59fb-a106-1535ae5fd3a1', 'fab77aef-c1ef-5def-ad14-c29703f59fe0', 3, 3, 'የክፉዎች ሰዎች ልጆች ብዛት አይረባም፤ የከንቱ ተክልም ሥሯ አይታወቅም፤ ጽኑ አኗኗርም አታደርግም።'),
  ('07f13224-4edc-5395-a258-6fa6c8952e2f', 'c4010cb6-3ce4-59fb-a106-1535ae5fd3a1', 'fab77aef-c1ef-5def-ad14-c29703f59fe0', 4, 4, 'ለጊዜውም በቅርንጫፎችዋ ላይ ቅጠል ቢወጣ ሳያድግ ነፋስ ያነዋውጠዋል፤ በነፋሱም ኀይል ይነቀላል።'),
  ('20d13b9a-8ea0-5bda-a037-21bc69d111ac', 'c4010cb6-3ce4-59fb-a106-1535ae5fd3a1', 'fab77aef-c1ef-5def-ad14-c29703f59fe0', 5, 5, 'ቅርንጫፎችዋም ሳያድጉ ይሰበራሉ፥ ፍሬያቸውም ለመብል የማይሆን ከንቱ ጨርቋ ነው፤ ጊዜው አይደለምና፥ ለመብላትም አይገባምና።'),
  ('d7db211a-434c-59e5-a516-26150603ca84', 'c4010cb6-3ce4-59fb-a106-1535ae5fd3a1', 'fab77aef-c1ef-5def-ad14-c29703f59fe0', 6, 6, 'ከክፉዎች ሰዎች መኝታ የሚወለዱ ልጆችም በተመረመሩ ጊዜ ለእናትና አባታቸው ክፋት ምስክሮች ናቸው።'),
  ('732213c8-59fd-56aa-afae-d08996474814', 'c4010cb6-3ce4-59fb-a106-1535ae5fd3a1', 'fab77aef-c1ef-5def-ad14-c29703f59fe0', 7, 7, 'ጻድቅ ሰው ግን ለመሞት በደረሰ ጊዜ በዕረፍት ይኖራል።'),
  ('0691fdf8-b5bc-574c-aa02-fcd8b29f203e', 'c4010cb6-3ce4-59fb-a106-1535ae5fd3a1', 'fab77aef-c1ef-5def-ad14-c29703f59fe0', 8, 8, 'የሽምግልና ክብር በዕድሜ ብዛት አይደለም፤ በዓመታትም ቍጥር የሚቈጠር አይደለም።'),
  ('e81855c5-43ce-5b3c-a9bc-7710e6ce1635', 'c4010cb6-3ce4-59fb-a106-1535ae5fd3a1', 'fab77aef-c1ef-5def-ad14-c29703f59fe0', 9, 9, 'ሽበትስ የሰው ዕውቀቱ ነው፤ የሽምግልናም አክሊሏ ያለ ነውር መኖር ነው።'),
  ('f70cc269-eb82-568e-aafc-89de875c5e47', 'c4010cb6-3ce4-59fb-a106-1535ae5fd3a1', 'fab77aef-c1ef-5def-ad14-c29703f59fe0', 10, 10, 'እግዚአብሔርን ደስ የሚያሰኝ ሰው በእርሱ ዘንድ የሚወደድ ይሆናል፤ በኀጢአተኞችም መካከል ሲኖር ይለያል።'),
  ('2d2d5178-943d-57bf-a92e-58468128a553', 'c4010cb6-3ce4-59fb-a106-1535ae5fd3a1', 'fab77aef-c1ef-5def-ad14-c29703f59fe0', 11, 11, 'ክፋትም ዕውቀቱን ሳትለውጥበት፥ ይህም ባይሆን ሐሰት ሰውነቱን ሳታስትበት ተነጥቆ ይሄዳል።'),
  ('3cc8d2be-fd3c-5241-a687-5b4044ec8358', 'c4010cb6-3ce4-59fb-a106-1535ae5fd3a1', 'fab77aef-c1ef-5def-ad14-c29703f59fe0', 12, 12, 'የክፋት ቅንዐት በጎ ሥራዎችን ያጠፋልና፥ የፈቃድ ነዘህላልነትም የዋህ ልቡናን ይለውጣልና።'),
  ('80255673-d528-591c-a0d0-3d99d7c1a838', 'c4010cb6-3ce4-59fb-a106-1535ae5fd3a1', 'fab77aef-c1ef-5def-ad14-c29703f59fe0', 13, 13, 'በጥቂት ዘመንም ቢሞት ረዥም ዓመታትን ጨርሷል።'),
  ('7b091410-1a0f-5e0f-a123-485b0166444d', 'c4010cb6-3ce4-59fb-a106-1535ae5fd3a1', 'fab77aef-c1ef-5def-ad14-c29703f59fe0', 14, 14, 'ነፍሱ እግዚአብሔርን ደስ አሰኝታዋለችና፤ ስለዚህም ከክፉዎች መካከል ተለይቶ በችኮላ ሄደ።'),
  ('55719687-75dc-5d13-af07-433da5013869', 'c4010cb6-3ce4-59fb-a106-1535ae5fd3a1', 'fab77aef-c1ef-5def-ad14-c29703f59fe0', 15, 15, 'ልዩ የሆኑ ሰዎች ግን ይህን አይተው ልብ አላደረጉትም፤ የዚህንም ትርጓሜ በልባቸው አላሳደሩትም። የእግዚአብሔር ጸጋው ለጻድቃኑ ነውና የይቅርታው ጕብኝትም ለመረጣቸው ሰዎች ነውና።'),
  ('f37a6899-fef3-5a91-a9ec-731d1617c21a', 'c4010cb6-3ce4-59fb-a106-1535ae5fd3a1', 'f57a3012-1dec-523d-a090-a9b41e7cf4ef', 1, 16, 'ጻድቅ ሰው ከሞተ በኋላ በሕይወት ባሉ ክፉዎች ላይ ይፈርዳል። ጐልማሳ ሰውም ፈጥኖ በሚሞትበት ጊዜ የዐመፃ ሽምግልና ዕድሜአቸው በበዛ በክፉዎች ሰዎች ላይ ይፈርዳል።'),
  ('e3d9bb3e-02cc-5f62-a940-65e3c6e3442c', 'c4010cb6-3ce4-59fb-a106-1535ae5fd3a1', 'f57a3012-1dec-523d-a090-a9b41e7cf4ef', 2, 17, 'ጠቢብ የሆነ የጻድቁን ሞት አይተው እግዚአብሔር ስለ እርሱ ምን እንደ መከረ፥ ወደ እርሱም ለምን እንደ ሰበሰበው አያስተውሉምና።'),
  ('b91fbaaa-1d99-5198-a078-6a834ce0ccd1', 'c4010cb6-3ce4-59fb-a106-1535ae5fd3a1', 'f57a3012-1dec-523d-a090-a9b41e7cf4ef', 3, 18, 'እርሱንም አይተው በእርሱ ይጠቃቀሳሉ፤ እግዚአብሔር ግን በእነርሱ ይሥቃል።'),
  ('2172628b-238d-5f45-ab22-bf9cf99afd05', 'c4010cb6-3ce4-59fb-a106-1535ae5fd3a1', 'f57a3012-1dec-523d-a090-a9b41e7cf4ef', 4, 19, 'ከዚህም በኋላ ለጐስቋላ ሞት ይሆናሉ፤ ለዘለዓለምም ሙታን ለሚሰደቡበት ስድብ ይሆናሉ። ይቈርጣቸዋልና፥ ይሰነጥቃቸዋልምና፥ ቃልም ሳይኖራቸው በፊታቸው የወደቁ ሆነው ይገኛሉ። ከመሠረታቸውም ያነዋውጣቸዋል፤ ለዘለዓለሙ እንደ ተፈታች ምድር ይሆናሉ፥ የተጨነቁም ይሆናሉ፤ መታሰቢያቸውም ይጠፋል።'),
  ('e9ed1565-4da8-5118-ab36-e5850afbb983', 'c4010cb6-3ce4-59fb-a106-1535ae5fd3a1', 'f57a3012-1dec-523d-a090-a9b41e7cf4ef', 5, 20, 'በፍርሃትም ሆነው በኀጢኣታቸው ለመወቀስ ይቀርባሉ፤ ኀጢኣታቸውም በፊታቸው ተገልጦ ይዘልፋቸዋል።'),
  ('a597490b-7bf4-5a24-a75d-59a2a9b80d79', '62c503b0-2b03-52f4-ac8e-db9fe8525b80', 'baec2ee9-de61-545c-ac46-0ec182c31524', 1, 1, 'ያንጊዜ ጻድቁ፦ መከራ ባጸኑበትና ድካሙን በካዱ፥ ነገሩንም በናቁ ሰዎች ፊት በብዙ መገለጥ ይቆማል።'),
  ('14d6d41a-f642-5efd-a6e3-bf1d72ca2c75', '62c503b0-2b03-52f4-ac8e-db9fe8525b80', 'baec2ee9-de61-545c-ac46-0ec182c31524', 2, 2, 'በግርማና በክፉ ማስፈራራት ሆኖ ባዩት ጊዜ ይታወካሉ፤ ድንቅ ስለሚሆን ደኅንነቱም ይደነቃሉ።'),
  ('b75e2003-d7c5-52ae-aae3-20ed34297baf', '62c503b0-2b03-52f4-ac8e-db9fe8525b80', 'baec2ee9-de61-545c-ac46-0ec182c31524', 3, 3, 'እየተጸጸቱና በተጨነቀ መንፈስ እየጮኹ እርስ በርሳቸው ይናገራሉ፦ እንዲህም ይላሉ፥ “ቀድሞ በኛ በሰነፎች ዘንድ መሣቂያና ማሽሟጠጫ የሆነው፥'),
  ('3d401ca3-176d-5651-a312-61bd128b14fd', '62c503b0-2b03-52f4-ac8e-db9fe8525b80', 'baec2ee9-de61-545c-ac46-0ec182c31524', 4, 4, 'ሥራውን ስንፍና፥ ሞቱንም የተናቀ ያደረግንበት ይህ ነውን?'),
  ('c7fdc099-11b5-56c1-a4c7-2be6e9bff577', '62c503b0-2b03-52f4-ac8e-db9fe8525b80', 'baec2ee9-de61-545c-ac46-0ec182c31524', 5, 5, 'እንዴት የእግዚአብሔር ልጅ ሆነ? ርስቱስ እንዴት ለቅዱሳን ሆነች?'),
  ('b0fbc6bf-5340-5fad-a565-85e58d814ec7', '62c503b0-2b03-52f4-ac8e-db9fe8525b80', 'baec2ee9-de61-545c-ac46-0ec182c31524', 6, 6, 'ስለዚህ ከቀና መንገድ ወጥተን ስተናል፥ የጽድቅ ብርሃንም አልተገለጠልንም፥ ፀሐይም አልወጣልንም።'),
  ('1170ec0f-0ab6-5157-a96e-8ee0b5143032', '62c503b0-2b03-52f4-ac8e-db9fe8525b80', 'baec2ee9-de61-545c-ac46-0ec182c31524', 7, 7, 'በደልንና ጥፋትን በመንገዳችን ሞላን፤ በምድረ በዳም ሄድን፤ የእግዚአብሔርንም መንገድ አላወቅንም።'),
  ('7726ad8b-6c0d-5f31-a537-a326c0025a2f', '62c503b0-2b03-52f4-ac8e-db9fe8525b80', 'baec2ee9-de61-545c-ac46-0ec182c31524', 8, 8, '“ትዕቢት ምን ጠቀመን? ከትዕቢት ጋር ያለ ባለጠግነትስ ምን አመጣልን?'),
  ('2e64fb2d-5a01-511a-a0fd-14751c299a41', '62c503b0-2b03-52f4-ac8e-db9fe8525b80', 'baec2ee9-de61-545c-ac46-0ec182c31524', 9, 9, 'ይህ ሁሉ እንደ ጥላ ኀላፊ ነው፤ ፈጥኖም እንደሚሄድ ወሬ ነው።'),
  ('d68fa28c-bc2d-50eb-a1c6-1bf7667d28b0', '62c503b0-2b03-52f4-ac8e-db9fe8525b80', 'baec2ee9-de61-545c-ac46-0ec182c31524', 10, 10, 'በባሕር ላይ እንደሚሄድ፥ ውኃም በማዕበሉ እንደሚነጥቀው፥ ያለፈበት ፍለጋው እንደማይገኝ፥ በማዕበሉም መካከል አካሉ የሄደበት መንገድ እንደማይታወቅ መርከብ፥'),
  ('a1029fea-0995-5d8c-a951-a4901b6d5541', '62c503b0-2b03-52f4-ac8e-db9fe8525b80', 'baec2ee9-de61-545c-ac46-0ec182c31524', 11, 11, 'በአየር ላይ የሚበርር ዎፍ የሄደበት ፍለጋው እንደማይገኝ፥ በበረረ ጊዜ ቀላሉን አየር እየከፈለ ፈጥኖ ይሄዳልና፥ ክንፉንም እያርገበገበ፥ ፈጥኖ ይበርራልና ከሄደም በኋላ በነፋሱ ውስጥ ያለፈበት ምልክቱ እንደማይገኝ፥'),
  ('4fcd2845-a2f0-5934-ae83-f5fd82772cfb', '62c503b0-2b03-52f4-ac8e-db9fe8525b80', 'baec2ee9-de61-545c-ac46-0ec182c31524', 12, 12, 'ይህም ባይሆን የተወረወረ ፍላፃ ሰንጥቆት ያለፈው አየር ተመልሶ እንደሚገጥም፥ በአየር ውስጥ የሄደበትም እንደማይታወቅ፥'),
  ('a4ec2724-1efd-596f-abfa-8555e15e13a8', '62c503b0-2b03-52f4-ac8e-db9fe8525b80', 'baec2ee9-de61-545c-ac46-0ec182c31524', 13, 13, 'እኛም እንዲሁ ነን፤ በተወለድን ጊዜ ጠፋን። በክፋታችን ጠፋን እንጂ በጎ ምልክትን እናሳይ ዘንድ አልተገባንም።”'),
  ('a4361234-de1c-5d03-a46c-e9c5911c101e', '62c503b0-2b03-52f4-ac8e-db9fe8525b80', 'baec2ee9-de61-545c-ac46-0ec182c31524', 14, 14, 'የክፉዎች ሰዎች ተስፋቸው ነፋስ እንደሚበትነው ትቢያ፥ በነፋስ ቀልጦ እንደሚጠፋ ረቂቅ ውርጭ፥ በነፋስም ተበትኖ እንደሚጠፋ ጢስ፥ አንድ ቀንም አድሮ እንደሚሄድ መጻተኛ ስም አጠራር ነው።'),
  ('a9ad32ae-feed-5f0d-a9d4-ed5adbc4a826', '62c503b0-2b03-52f4-ac8e-db9fe8525b80', 'e23d4c96-8bb6-5122-aadb-530fd5bdd49d', 1, 15, 'ጻድቃን ግን ለዘለዓለም ይኖራሉ፤ ዋጋቸውም በእግዚአብሔር ዘንድ የጸና ነው፤ ጥበቃቸውም በልዑል ዘንድ ነው።'),
  ('f95e7c06-d0f3-5f75-acf1-38ef7a14f56f', '62c503b0-2b03-52f4-ac8e-db9fe8525b80', 'e23d4c96-8bb6-5122-aadb-530fd5bdd49d', 2, 16, 'ስለዚህም የክብር መንግሥትንና ጌጥ ያለው አክሊልን ከእግዚአብሔር እጅ ይቀበላሉ፤ በቀኙ ይሰውራቸዋልና፥ በክንዱም ይረዳቸዋልና።'),
  ('e0bdaf98-ea24-5c62-a9b3-d36b84cb0c0b', '62c503b0-2b03-52f4-ac8e-db9fe8525b80', 'e23d4c96-8bb6-5122-aadb-530fd5bdd49d', 3, 17, 'ፍጹም የሆነ የቅንዐቱን ጦር መሣሪያ ይይዛል፤ ጠላቶቹንም ለመበቀል ፍጥረቱን የጦር መሣሪያ ያደርጋታል።'),
  ('6cdbd554-c02e-5d42-a341-2015f24b7382', '62c503b0-2b03-52f4-ac8e-db9fe8525b80', 'e23d4c96-8bb6-5122-aadb-530fd5bdd49d', 4, 18, 'የጽድቅ ጥሩርንም ይለብሳል፥ ማድላት የሌለበት የፍርድ ራስ ቍርንም ይቀዳጃል።'),
  ('6c7ab4dc-b6aa-5c4f-a024-5798d9f280b2', '62c503b0-2b03-52f4-ac8e-db9fe8525b80', 'e23d4c96-8bb6-5122-aadb-530fd5bdd49d', 5, 19, 'የማይሸነፍ የእውነት ጋሻንም ይይዛል።'),
  ('0f3b07e5-d94f-5077-acb0-5611ae3eaa08', '62c503b0-2b03-52f4-ac8e-db9fe8525b80', 'e23d4c96-8bb6-5122-aadb-530fd5bdd49d', 6, 20, 'መዓቱንም እንደሚቈርጥ ሰይፍ ይስላል፤ ዓለምም ከእርሱ ጋር ሆኖ አላዋቂዎችን ይዋጋል።'),
  ('b315ccc2-860f-55fe-abea-85054d532fb4', '62c503b0-2b03-52f4-ac8e-db9fe8525b80', 'e23d4c96-8bb6-5122-aadb-530fd5bdd49d', 7, 21, 'ፈጥኖ ያገኛቸው ዘንድ በአሳቾች ሰዎች ላይ የመብረቆቹ ድል ነጎድ በቀጥታ ይሄድባቸዋል። መልካም ሆኖ ከተገተረ ቀስት እንደሚወረወር ፍላጻ ከደመናዎች ውስጥ ወደ ዓላማቸው ይወረወራሉ ።'),
  ('287db678-b31e-5376-ac0f-5c136214c33e', '62c503b0-2b03-52f4-ac8e-db9fe8525b80', 'e23d4c96-8bb6-5122-aadb-530fd5bdd49d', 8, 22, 'ከመዓቱ ድል ነጎድ ደንጊያም ፈጥኖ በረዶን ያወርዳል፤ የባሕሩም ውኃ በእነርሱ ላይ ይበሳጭባቸዋል፤ ፈሳሾችም ይነዋወጣሉ፤ ፈጥነውም ይከቧቸዋል።'),
  ('baa30570-9647-5870-ac98-95a15dc02946', '62c503b0-2b03-52f4-ac8e-db9fe8525b80', 'e23d4c96-8bb6-5122-aadb-530fd5bdd49d', 9, 23, 'ኀይል ያለው ነፋስም ይቃወማቸዋል፤ እንደ ነፋስም ያደርቃቸዋል፤ ኀጢአት ምድሩን ሁሉ ታጠፋለችና፥ ክፉም መሥራት የኀያላኑን ዙፋን ይገለብጣልና ይበትናቸዋል።'),
  ('8772f919-1b84-5937-abc9-f4a6efff71c5', '72f4660c-56f8-5a48-a8ed-16ecd21f0e3a', '00f6685d-cbd3-5c13-a21b-b98ccca86b1f', 1, 1, 'ነገሥታት ሆይ፥ ስሙ፤ አስተውሉም፤ የምድር ዳርቻንም የምትገዙ መኳንንት ሆይ፥ ዕወቁ።'),
  ('e98845d9-10b2-5e4b-a024-0b1e2c9e73fe', '72f4660c-56f8-5a48-a8ed-16ecd21f0e3a', '00f6685d-cbd3-5c13-a21b-b98ccca86b1f', 2, 2, 'ብዙ ምድርን የምትገዙ፥ በሠራዊትም ብዛት የምትታበዩ ስሙ።'),
  ('6c48de30-1bdd-528a-a522-5fa21fa7c809', '72f4660c-56f8-5a48-a8ed-16ecd21f0e3a', '00f6685d-cbd3-5c13-a21b-b98ccca86b1f', 3, 3, 'እግዚአብሔር ኀይልን ሰጥትዋችኋልና፤ ግዛታችሁም ከልዑል ዘንድ ነው፤ ምግባራችሁንም የሚመረምር እርሱ ነው፤ ምክራችሁንም ይመረምራል።'),
  ('189e0300-022c-52cc-aaa8-2dbac8b2d5f1', '72f4660c-56f8-5a48-a8ed-16ecd21f0e3a', '00f6685d-cbd3-5c13-a21b-b98ccca86b1f', 4, 4, 'እናንተ የመንግሥቱ መልእክተኞች ስትሆኑ የቀና ፍርድን እንዴት አትፈርዱም? ሕጉንስ እንዴት አልጠበቃችሁም? በእግዚአብሔርስ መንገድ እንዴት አልሄዳችሁም?'),
  ('a23cecaf-5711-59b3-abb7-a8a97f332200', '72f4660c-56f8-5a48-a8ed-16ecd21f0e3a', '00f6685d-cbd3-5c13-a21b-b98ccca86b1f', 5, 5, 'ፈጥኖ የሚቃወማችሁ ድንጋፄን በላያችሁ ያመጣል፥ ቍርጥ ፍርድ በመኳንንት ላይ ይሆናልና።'),
  ('1a97ed73-e162-517b-ac2c-646a4d76c0b7', '72f4660c-56f8-5a48-a8ed-16ecd21f0e3a', '00f6685d-cbd3-5c13-a21b-b98ccca86b1f', 6, 6, 'ለተዋረደው ድሃ ግን ከቸርነት ሥራ የተነሣ ይቀልለታል፤ ኀይለኞች ሰዎች ግን በጽኑዕ ምርመራ ይመረመራሉ።'),
  ('684b4c74-d5c9-5e11-aba0-eb7d8fce719d', '72f4660c-56f8-5a48-a8ed-16ecd21f0e3a', '00f6685d-cbd3-5c13-a21b-b98ccca86b1f', 7, 7, 'እግዚአብሔር ፊት አይቶ አያዳላምና፤ የታላቁንም መከበር አያፍርምና፤ እንደዚሁም ታናሹንና ታላቁን ስለ ፈጠረ ለገዡና ለተገዡ ሁሉ ያስባል፤ ይወስንላቸዋልም።'),
  ('a5298833-7084-5581-af4d-77314123e936', '72f4660c-56f8-5a48-a8ed-16ecd21f0e3a', '00f6685d-cbd3-5c13-a21b-b98ccca86b1f', 8, 8, 'በኀያላን ግን ጽኑዕ ምርመራ ይደርስባቸዋል።'),
  ('b9ff2de5-20a7-59a7-a013-b1a981d83fa4', '72f4660c-56f8-5a48-a8ed-16ecd21f0e3a', '00f6685d-cbd3-5c13-a21b-b98ccca86b1f', 9, 9, 'ክፉዎችና ግፈኞች መኳንንት ሆይ፥ ጥበብን እንድታውቁና እንዳትሰነካከሉ ነገሬ ለእናንተ ነው።'),
  ('d87ca21f-b5df-5fb6-a886-ebfee006b723', '72f4660c-56f8-5a48-a8ed-16ecd21f0e3a', '00f6685d-cbd3-5c13-a21b-b98ccca86b1f', 10, 10, 'እውነተኛ ትእዛዙን ዐውቀው የሚጠብቁ በእውነት ይከብራሉና የተማሯትም ሰዎች ምሕረትን ያገኛሉና።'),
  ('185429e5-8796-5b9a-a71f-b1168c84e89d', '72f4660c-56f8-5a48-a8ed-16ecd21f0e3a', '00f6685d-cbd3-5c13-a21b-b98ccca86b1f', 11, 11, 'እንግዲህ ወዲህ ነገሬን ተመኝዋት፥ ውደዷትም፤ ይቅርታንና ቸርነትንም ታገኙ ዘንድ ተመከሩ።'),
  ('0c9ae134-6a54-5b6d-a0a9-0ecb65fe18b6', '72f4660c-56f8-5a48-a8ed-16ecd21f0e3a', 'f6f062dd-00db-5c34-a0f8-a342ac904bc9', 1, 12, 'ጥበብ ፈጽማ የጐላች ናት፤ ውበቷም አይጠወልግም፤ የሚወድዷትም ሰዎች ፈጥነው ያዩአታል፥ የሚፈልጉአትም ያገኙአታል።'),
  ('78daa4fe-5658-54af-a8fd-49ffa86c1e77', '72f4660c-56f8-5a48-a8ed-16ecd21f0e3a', 'f6f062dd-00db-5c34-a0f8-a342ac904bc9', 2, 13, 'ለሚወዷትም ትደርስላቸዋለች፤ አስቀድማም ትገለጥላቸዋለች።'),
  ('b2111b9f-2832-5cd3-a584-8199f1588ffb', '72f4660c-56f8-5a48-a8ed-16ecd21f0e3a', 'f6f062dd-00db-5c34-a0f8-a342ac904bc9', 3, 14, 'በደጃፉ ስትጠብቀው ሁል ጊዜ እርሱ ያገኛታልና ወደርስዋ የሚገሠግሥ ሰው አይደክምም።'),
  ('06b7f49b-7d2c-57b3-a0c8-65ab16dd4f96', '72f4660c-56f8-5a48-a8ed-16ecd21f0e3a', 'f6f062dd-00db-5c34-a0f8-a342ac904bc9', 4, 15, 'እርስዋን ማሰብ የዕውቀት ፍጻሜ ነውና፥ ፈጥኖ ስለ እርስዋ የሚተጋ ሰው ያለ ኀዘን ይኖራል።'),
  ('14bfbc8e-856d-5836-a03b-3bb0e9163500', '72f4660c-56f8-5a48-a8ed-16ecd21f0e3a', 'f6f062dd-00db-5c34-a0f8-a342ac904bc9', 5, 16, 'ለእርስዋ የሚገቧትን ሰዎች ፈልጋ ትመጣለችና፥ በመንገድም ድንገት እንደ ሥዕል አምራ ትታያቸዋለች፤ በአሳብም ሁሉ ትገናኛቸዋለች።'),
  ('20be2367-24bf-532e-a5d0-5fb0a223400c', '72f4660c-56f8-5a48-a8ed-16ecd21f0e3a', 'f6f062dd-00db-5c34-a0f8-a342ac904bc9', 6, 17, 'የጥበብ መጀመሪያ ተግሣጽን መውደድ ነው፤ ተግሣጽንም ማሰብ እርሷን መውደድ ነው።'),
  ('7dbdab6f-37e2-5758-abdb-6e0a8c5dc96b', '72f4660c-56f8-5a48-a8ed-16ecd21f0e3a', 'f6f062dd-00db-5c34-a0f8-a342ac904bc9', 7, 18, 'እርሷንም መውደድ ሕጓን መጠበቅ ነው፤ ሕጓንም መስማት ሕይወትን መረዳት ነው።'),
  ('b38d5d88-40e9-5441-a077-71f278aaf93d', '72f4660c-56f8-5a48-a8ed-16ecd21f0e3a', 'f6f062dd-00db-5c34-a0f8-a342ac904bc9', 8, 19, 'ሕይወትም ሰውን ወደ እግዚአብሔር የቀረበ ታደርጋለች።'),
  ('4e6a0778-ae36-5363-a06f-a0371563b4eb', '72f4660c-56f8-5a48-a8ed-16ecd21f0e3a', 'f6f062dd-00db-5c34-a0f8-a342ac904bc9', 9, 20, 'ጥበብን መውደድ ወደ መንግሥት ታደርሳለችና።'),
  ('05dba363-a69c-5425-aff0-45eaa7b2b8be', '72f4660c-56f8-5a48-a8ed-16ecd21f0e3a', 'f6f062dd-00db-5c34-a0f8-a342ac904bc9', 10, 21, 'የአሕዛብ ነገሥታት ሆይ፥ ዙፋንንና በትረ መንግሥትን ከወደዳችሁ ለዘለዓለም ትነግሡ ዘንድ ጥበብን አክብሯት።'),
  ('d8404d4c-e315-5640-a315-93aa29f79a01', '72f4660c-56f8-5a48-a8ed-16ecd21f0e3a', 'f6f062dd-00db-5c34-a0f8-a342ac904bc9', 11, 22, 'ጥበብ ምንድን ናት? እንደ ምንስ ነበረች? እኔ እነግራችኋለሁ፤ የተሰወረ ምሥጢሯንም ከእናንተ አልሰውርም። ነገር ግን ከጥንት ጀምሮ አኳኋኗን እመረምራለሁ፤ እርሷን ማወቅንም የተገለጠ አደርጋለሁ፤ እውነትንም አልተላለፍም።'),
  ('1c81b299-332d-5e0c-a342-61ad92ebd480', '72f4660c-56f8-5a48-a8ed-16ecd21f0e3a', 'f6f062dd-00db-5c34-a0f8-a342ac904bc9', 12, 23, 'በምቀኛ ቅንአት አልኖርም፤ እንዲህ ያለ ሰው ከጥበብ ጋራ አንድ አይሆንምና።'),
  ('2cc3d7c1-60ab-50ea-afb9-ede88e6663ed', '72f4660c-56f8-5a48-a8ed-16ecd21f0e3a', 'f6f062dd-00db-5c34-a0f8-a342ac904bc9', 13, 24, 'የጠቢባን ብዛት የዓለም መድኀኒት ነውና።'),
  ('d2b17df8-4986-57b7-aa79-8b1904fcf590', '72f4660c-56f8-5a48-a8ed-16ecd21f0e3a', 'f6f062dd-00db-5c34-a0f8-a342ac904bc9', 14, 25, 'አስተዋይ ንጉሥም ለሕዝቡ ጠበቃ ነው፤ በቃሌም ተመከሩ፤ ትጠቀማላችሁም።'),
  ('df446f99-2db9-54f8-a5dc-03c64184378a', '1498079d-b534-5f04-aaef-2f74a5fac48e', '70a2824a-7990-5c3e-a0a3-aa2a2fa28b23', 1, 1, 'እኔም እንደ ሁሉ እኩል መዋቲ ሰው ነኝ፤ አስቀድሞ የተፈጠረ የምድራዊ አዳም ልጅም ነኝ፥ በእናቴ ማኅፀንም ሥጋ ሆኜ ተቀርጫለሁ።'),
  ('324822a2-fe3f-5e80-a88f-a959aee18fd4', '1498079d-b534-5f04-aaef-2f74a5fac48e', '70a2824a-7990-5c3e-a0a3-aa2a2fa28b23', 2, 2, 'በመገናኘት ጊዜ ከአባት ዘርና ከመኝታ ፈቃድ ተገኝቼ፥ ዐሥር ወር በደምነት ረግቼ ኖርሁ።'),
  ('f4a702c4-2752-5c83-a50a-b12830900531', '1498079d-b534-5f04-aaef-2f74a5fac48e', '70a2824a-7990-5c3e-a0a3-aa2a2fa28b23', 3, 3, 'በተፈጠርሁም ጊዜ እንደ ሰው ሁሉ ነፍስን ነሣሁ፥ በመከራዬም ምሳሌ ወደ ምድር ወረድሁ፤ የቃልም መጀመርያ እንደ ሁሉ ልቅሶን አለቀስሁ።'),
  ('a0111656-e355-5204-a230-8673971cf81b', '1498079d-b534-5f04-aaef-2f74a5fac48e', '70a2824a-7990-5c3e-a0a3-aa2a2fa28b23', 4, 4, 'በጨርቅ ተጠቅልዬ በጥንቃቄ አደግሁ።'),
  ('97d3c24d-500d-5c8f-a2dc-9c12e7844bab', '1498079d-b534-5f04-aaef-2f74a5fac48e', '70a2824a-7990-5c3e-a0a3-aa2a2fa28b23', 5, 5, 'ከነገሥታት ወገን የልደቱ መጀመሪያ ልዩ የሆነ የለምና።'),
  ('a7a617b2-6e43-5c82-a084-3e968c5db5a7', '1498079d-b534-5f04-aaef-2f74a5fac48e', '70a2824a-7990-5c3e-a0a3-aa2a2fa28b23', 6, 6, 'የሁሉም ወደዚህ ዓለም አመጣጡ አንዲት ናት፥ የሁሉም መውጣቱ እኩል ነው።'),
  ('b08f837d-659e-5734-ab35-2af1ca37eeaa', '1498079d-b534-5f04-aaef-2f74a5fac48e', 'f7e6fddf-e201-5368-aa9c-7ab90c2fa3f7', 1, 7, 'ስለዚህ ነገር ጸለይሁ፤ ዕውቀትም ተሰጠኝ፤ ለመንሁ፤ የጥበብም መንፈስ ወደ እኔ መጣ።'),
  ('dbfc5825-9fa8-5c03-aeaf-fa5140c8e49b', '1498079d-b534-5f04-aaef-2f74a5fac48e', 'f7e6fddf-e201-5368-aa9c-7ab90c2fa3f7', 2, 8, 'ከበትረ መንግሥትና ከዙፋንም ይልቅ አከበርኋት፤ ብዕልንም ከእርስዋ ጋር ሳመዛዝን እንደ ኢምንት አደረግኋት።'),
  ('7aa0f389-fbd1-5e89-ab6f-f757937d8168', '1498079d-b534-5f04-aaef-2f74a5fac48e', 'f7e6fddf-e201-5368-aa9c-7ab90c2fa3f7', 3, 9, 'ወርቅ ሁሉ በእርሷ ዘንድ እንደ ጥቂት አሸዋ ነውና፤ ብሩም በእርስዋ ዘንድ እንደ ጭቃ ነውና፥ ዋጋ በሌለው ዕንቍ አልመሰልኋትም።'),
  ('17cd32ce-e2e4-5d38-ad34-e946efcb82b1', '1498079d-b534-5f04-aaef-2f74a5fac48e', 'f7e6fddf-e201-5368-aa9c-7ab90c2fa3f7', 4, 10, 'ከሕይወትና ከውበትም ፈጽሜ ወደድኋት፤ ከእርሷ የሚወጣ የብርሃን ነጸብራቅ አይወሰንምና፥ ደግሞም አይጠፋምና ስለ ብርሃን ፋንታ ትሆነኝ ዘንድ መረጥኋት።'),
  ('6809f401-d2fa-5e56-ab3d-30312394efaa', '1498079d-b534-5f04-aaef-2f74a5fac48e', 'f7e6fddf-e201-5368-aa9c-7ab90c2fa3f7', 5, 11, 'ከእርሷ ጋር በአንድነት በጎ ነገር ሁሉ መጣልኝ፤ ቍጥር የሌለው ባለጠግነትም በእጆችዋ አለ።'),
  ('f285cd3f-5e9a-5bf1-a41a-d7d2b5ada726', '1498079d-b534-5f04-aaef-2f74a5fac48e', 'f7e6fddf-e201-5368-aa9c-7ab90c2fa3f7', 6, 12, 'ጥበብ የእነዚህ ሁሉ አበጋዛቸው ናትና በሁሉ ደስ አለኝ፤ ጥበብ የእነዚህ ሁሉ አስገኛቸው እንደ ሆነች አላወቅሁም ነበር።'),
  ('7983dbb9-def3-57b8-a235-affe67072996', '1498079d-b534-5f04-aaef-2f74a5fac48e', 'f7e6fddf-e201-5368-aa9c-7ab90c2fa3f7', 7, 13, 'ይህን ባወቅሁ ጊዜ ያለ ክፋትና ያለ ቅንአት እርሷን እሰጣለሁ፤ ብልጽግናዋንም አልሰውርም።'),
  ('802bcdf0-f1fc-5661-a750-1c610d338e1d', '1498079d-b534-5f04-aaef-2f74a5fac48e', 'f7e6fddf-e201-5368-aa9c-7ab90c2fa3f7', 8, 14, 'ለሰውም የማያልቅ መዝገብ ናት፤ ገንዘብ ያደረጓትም ሁሉ ወደ እግዚአብሔር ደረሱ፤ ሀብትን የምትገልጽ የምክር ሥራ ስለ ሆነችም ተወዳጇት።'),
  ('322ee78a-a2c0-5fef-a744-00ae767a75dc', '1498079d-b534-5f04-aaef-2f74a5fac48e', 'f7e6fddf-e201-5368-aa9c-7ab90c2fa3f7', 9, 15, 'ለእኔም እግዚአብሔር የሚወደደውን ነገር እናገር ዘንድ፥ ለሚሰጠውም ሰው የሚገባውን አስብ ዘንድ ጥበብን ሰጠኝ። ወደ ጥበብ የሚመራ፥ ጠቢባንንም ቅን የሚያደርግ እርሱ ነውና።'),
  ('729c7f74-07e5-53c7-a332-4873807871f8', '1498079d-b534-5f04-aaef-2f74a5fac48e', 'f7e6fddf-e201-5368-aa9c-7ab90c2fa3f7', 10, 16, 'እኛ ሁላችን በእጁ ነንና፤ ነገራችንም ሁሉ ሥራችንንም ማወቅና መረዳት በእጁ ነውና።'),
  ('c4419c9d-cd30-5362-a5f8-772bad640a7b', '1498079d-b534-5f04-aaef-2f74a5fac48e', 'f7e6fddf-e201-5368-aa9c-7ab90c2fa3f7', 11, 17, 'ያለ ሐሰት ነዋሪ የሚሆን የዕውቀት ነገርን ሰጠኝ፤ ዓለም ጸንቶ የሚኖርበትንም ሥርዐት፥ የፀሐይን፥ የጨረቃንና የከዋክብትንም ሥራ አውቅ ዘንድ፤'),
  ('a62297c7-c602-5631-a40c-3e75f6621a7d', '1498079d-b534-5f04-aaef-2f74a5fac48e', 'f7e6fddf-e201-5368-aa9c-7ab90c2fa3f7', 12, 18, 'የዘመኑን መጀመሪያውንና መጨረሻውን፥ መካከሉንም፥ የቀኑን መመላለስ፥ የጊዜውንም መለዋወጥ፥'),
  ('ca1b5933-0565-5a1d-af2c-1faabce9edfe', '1498079d-b534-5f04-aaef-2f74a5fac48e', 'f7e6fddf-e201-5368-aa9c-7ab90c2fa3f7', 13, 19, 'የዘመናትን ዑደት፥ የከዋክብትንም አኗኗር፥'),
  ('d25edebe-043e-5688-a75e-586abfc2ecf8', '1498079d-b534-5f04-aaef-2f74a5fac48e', 'f7e6fddf-e201-5368-aa9c-7ab90c2fa3f7', 14, 20, 'የእንስሳንም ጠባይ፥ የአራዊትንም ቍጣ፥ የነፋሳትንም ኀይል፥ የሰውንም አሳብ፥ ዛፎችንም ለይቶ ማወቅ፥ የሥሮችንም ተግባር ኀይል አውቅ ዘንድ ሰጠኝ።'),
  ('ffc21f09-1541-51ea-abcd-eee663911ba3', '1498079d-b534-5f04-aaef-2f74a5fac48e', 'f7e6fddf-e201-5368-aa9c-7ab90c2fa3f7', 15, 21, 'የሥራው ሁሉ አስገኝ እርሱ ጥበብን አስተምሮኛልና የተገለጸውንና የተሰወረውን ሁሉ ዐወቅሁ።'),
  ('9e3be899-e786-5bae-ab0c-4fea8e6759f5', '1498079d-b534-5f04-aaef-2f74a5fac48e', 'e4caef55-e7bb-5a62-ae3d-aa874ed8e42a', 1, 22, 'በእርስዋ የማስተዋል መንፈስ አለና፤ እርሱም ቅዱስ፥ በልደት ብቸኛ የሆነ፥ አንድ ሲሆን ሀብቱ ብዙ የሆነ፥ ረቂቅ፥ እንቅስቃሴውም የፈጠነ፥ ቃሉ የሚያምር፥ ጠቢብ፥ ዕድፈትም የሌለበት፥ የማይደክም፥ ጥንት የሌለው፥ ነዋሪ፥ ቸርነትን የሚወድ፥ ፈጣን፥ በጎ ነገርን ለማድረግ የሚከለክለው የሌለ፥'),
  ('a54de38d-ba62-5390-a060-d30bfb8638f4', '1498079d-b534-5f04-aaef-2f74a5fac48e', 'e4caef55-e7bb-5a62-ae3d-aa874ed8e42a', 2, 23, 'ሰው ወዳጅ፥ የጥበብ ወዳጅዋ፥ ዐዋቂ፥ እውነተኛ፥ ግዳጅ የሌለበት፥ ትዕግሥተኛ፥ ሁሉን የሚችል፥ ሁሉንም የሚጐበኝ፥ ንጹሓትና አስተዋዮች፥ ረቂቃትም በሆኑ ነፍሳት የሚያድር ነው።'),
  ('6eafe534-8bc4-5405-a72c-51698f32ae27', '1498079d-b534-5f04-aaef-2f74a5fac48e', 'e4caef55-e7bb-5a62-ae3d-aa874ed8e42a', 3, 24, 'የጥበብ እንቅስቃሴዋ ከእንቅስቃሴ ሁሉ ይፈጥናልና። በሁሉም ዘንድ በስፋት ትመላለሳለች፤ ስለ ንጽሕናዋም ጽርየት በሁሉ ትሄዳለች።'),
  ('6137d9d7-3137-5f1c-a3fb-f012712de219', '1498079d-b534-5f04-aaef-2f74a5fac48e', 'e4caef55-e7bb-5a62-ae3d-aa874ed8e42a', 4, 25, 'የእግዚአብሔር የኀይሉ እስትንፋስ ናትና፥ አርአያው የታወቀ፥ ክቡርና ንጹሕ የሆነ የኀያል አምላክ የክብሩ መገለጫ ናት። ስለዚህ የሚያገኛት ምንም ርኵሰት የለም።'),
  ('88e2b5ee-d375-5d30-a7f3-60c238303598', '1498079d-b534-5f04-aaef-2f74a5fac48e', 'e4caef55-e7bb-5a62-ae3d-aa874ed8e42a', 5, 26, 'የቀዳማዊ ብርሃን ነጸብራቅ ናትና፥ የማትጨልም የእግዚአብሔር የሥራው መስታዋትም ናትና፥ የቸርነቱም አርኣያ ናትና።'),
  ('05e4a144-79a7-5c3c-ab10-0d8b725e3a33', '1498079d-b534-5f04-aaef-2f74a5fac48e', 'e4caef55-e7bb-5a62-ae3d-aa874ed8e42a', 6, 27, 'አንዲት ስትሆን ሁሉን ማድረግ ትችላለች፤ ራስዋም እየኖረች ሁሉን ታድሳለች፥ በየትውልዱም በጻድቃን ሰውነት ትተላለፋለች፤ የእግዚአብሔርም ወዳጆችና ነቢያቱ ታደርጋቸዋለች።'),
  ('6418c19e-cd60-5956-a3a1-e82e7bcc8c89', '1498079d-b534-5f04-aaef-2f74a5fac48e', 'e4caef55-e7bb-5a62-ae3d-aa874ed8e42a', 7, 28, 'እግዚአብሔር ከጥበብ ጋር ከሚኖር ሰው በቀር የሚወድደው የለምና።'),
  ('fa1e5b2e-760f-53aa-a30b-fed452d4a7dd', '1498079d-b534-5f04-aaef-2f74a5fac48e', 'e4caef55-e7bb-5a62-ae3d-aa874ed8e42a', 8, 29, 'እርስዋ ከፀሐይ ይልቅ በመልክ ታምራለችና፥ ከከዋክብትም ሥርዐት ሁሉ ትበልጣለች፤ ከብርሃን ጋርም በምትመዘንበት ጊዜ በልጣ በፊቱ ትገኛለች።'),
  ('fbac689e-df63-5c8d-a093-31b76a6824ac', '1498079d-b534-5f04-aaef-2f74a5fac48e', 'e4caef55-e7bb-5a62-ae3d-aa874ed8e42a', 9, 30, 'ብርሃኑን ሌሊት ይለውጠዋልና፥ ጥበብን ግን ምንም ክፉ ነገር አይበረታታባትም።'),
  ('f883d301-b991-53aa-aa2d-f698ae83f60e', '146b5232-d7ce-5a8a-a149-236982c83832', '1f209143-9e9e-5d30-a6a1-80dc1740fa5c', 1, 1, 'ጥበብ ከዳርቻ እስከ ዳርቻ ድረስ ደኅና ሆና ትደርሳለች፤ በቸርነትዋም ሁሉን ትሠራለች።'),
  ('10998503-f2a6-513d-ac3e-d423232710d1', '146b5232-d7ce-5a8a-a149-236982c83832', '1f209143-9e9e-5d30-a6a1-80dc1740fa5c', 2, 2, 'እኔም ከጐልማሳነቴ ጀምሮ ወደድኋት፤ ፈለግኋትም። ለእኔም ሙሽራ አድርጌ እወስዳት ዘንድ ወደድሁ። ደም ግባትዋንም ወደድሁ።'),
  ('ce5496c8-ad0f-51e5-a05e-259738509222', '146b5232-d7ce-5a8a-a149-236982c83832', '1f209143-9e9e-5d30-a6a1-80dc1740fa5c', 3, 3, 'የዝምድናዋም ቸርነት ወደ እግዚአብሔር ያቀርባልና ሁሉን የሚገዛ እርሱ ወደዳት።'),
  ('40ca0503-4c1b-5dc2-a292-cb927db7fadf', '146b5232-d7ce-5a8a-a149-236982c83832', '1f209143-9e9e-5d30-a6a1-80dc1740fa5c', 4, 4, 'የእግዚአብሔርን ምሥጢር ለማወቅ መካር ናትና፥ የሥራውም ወዳጅ ናትና።'),
  ('e068c169-f5ee-5708-ad68-c96d2816e719', '146b5232-d7ce-5a8a-a149-236982c83832', '1f209143-9e9e-5d30-a6a1-80dc1740fa5c', 5, 5, 'እርሷም ባለችበት ዘንድ ብልጽግና አለ፤ በዚህ ዓለም ገንዘብ ላደረጓት ሰዎች ከሁሉ ትመረጣለች፤ ሁሉን የምታደርግ ጥበብን የሚበልጣት ምንድን ነው?'),
  ('7a543558-41f0-5e4e-a980-d76cc7d6fea6', '146b5232-d7ce-5a8a-a149-236982c83832', '1f209143-9e9e-5d30-a6a1-80dc1740fa5c', 6, 6, 'ዕውቀትም ቢደረግ በእርሷ ነው፤ ካሉትም ሁሉ ከእርሷ የሚበልጥ ብልህ ማን ነው?'),
  ('a2ccf66a-8f8e-51f6-acbb-1c19525e5ed1', '146b5232-d7ce-5a8a-a149-236982c83832', '1f209143-9e9e-5d30-a6a1-80dc1740fa5c', 7, 7, 'እውነትን የወደደ ሰውም ቢኖር በእርሷ ነው፤ ድካሟ ያማረ ነውና፥ ንጽሕናንና ጥበብን፥ እውነትንና ብርታትን፥ ትሩፋትንና ደግነትንም ታስተምራለች። በዓለሙ ውስጥም በሰው ሕይወት ከእርሷ የሚሻልና የሚጠቅም ምንም የለም።'),
  ('01f88c0f-07fd-54cf-a5aa-71a5f85f79a1', '146b5232-d7ce-5a8a-a149-236982c83832', '1f209143-9e9e-5d30-a6a1-80dc1740fa5c', 8, 8, 'ብዙ ዕውቀትንና ደግነትን ያወቀ ሰው ቢኖር በእርሷ ነው፤ የቀደመውንና የሚመጣውንም ሥራ ያወቀ ሰው ቢኖር በእርሷ ነው፤ የነገር መልስንና ፈጥኖ መተርጐምን ቢያውቅም በእርሷ ነው፤ ተአምራትንና ድንቆችን፥ የጊዜያትንና የዓመታትንም መለዋወጥ አስቀድሞ ቢያውቅ በእርስዋ ነው።'),
  ('6933b809-9fad-502a-ad2a-9c853eb382a9', '146b5232-d7ce-5a8a-a149-236982c83832', '1f209143-9e9e-5d30-a6a1-80dc1740fa5c', 9, 9, 'እኔም፦ ለበጎ ነገር የምትመክርና የምትገሥጽ ኀዘንንና ትካዝን የምታስተው እንደምትሆን ዐውቄ ከእኔ ጋራ እንድትኖር እይዛት ዘንድ ወደድሁ።'),
  ('a435edde-6cfe-56b0-a6ee-a9f630432e69', '146b5232-d7ce-5a8a-a149-236982c83832', '1f209143-9e9e-5d30-a6a1-80dc1740fa5c', 10, 10, 'በእርስዋም ምክንያት እኔ ጐልማሳው በብዙዎች ዘንድ ምስጋናን፥ በሽማግሌዎችም ዘንድ ክብርን አገኘሁ።'),
  ('bc7acc27-c6c5-5cdb-a019-e3ecf2bcefba', '146b5232-d7ce-5a8a-a149-236982c83832', '1f209143-9e9e-5d30-a6a1-80dc1740fa5c', 11, 11, 'ለመፍረድ አሳበ ፈጣን ሆንሁ፤ በኀያላኑም ፊት ተደነቅሁ።'),
  ('3277311a-033e-5c25-a1dd-afe328fb222f', '146b5232-d7ce-5a8a-a149-236982c83832', '1f209143-9e9e-5d30-a6a1-80dc1740fa5c', 12, 12, 'ዝም ስልም ታግሠው ይጠብቁኝ ነበር፤ ስናገርም ያዳምጡኝ ነበር፤ መናገርም ባበዛ አፋቸውን በእጃቸው ይይዙ ነበር።'),
  ('5bbce141-c17c-5026-addb-9bc2a1c29c42', '146b5232-d7ce-5a8a-a149-236982c83832', '1f209143-9e9e-5d30-a6a1-80dc1740fa5c', 13, 13, 'በእርስዋም ምክንያት አለመሞትን አገኘሁ፤ ከእኔም በኋላ ለሚመጡ ሰዎች ለዘለዓለም መታሰቢያን ተውሁ።'),
  ('7dbb0fb3-439e-5d47-ade9-3cc6b84b295d', '146b5232-d7ce-5a8a-a149-236982c83832', '1f209143-9e9e-5d30-a6a1-80dc1740fa5c', 14, 14, 'ሕዝቡን እሠራራ ነበር፤ አሕዛብም ይገዙልኝ ነበር።'),
  ('571d43a5-da09-5979-a9d3-03b97c5e68d1', '146b5232-d7ce-5a8a-a149-236982c83832', '1f209143-9e9e-5d30-a6a1-80dc1740fa5c', 15, 15, 'የሚያስደነግጡ የምድር መኳንንትም ሰምተው ይፈሩኝ ነበር፤ በሸንጎ ደግ ሆኜ፥ በጠብም ጊዜ ብርቱ ሆኜ እታይ ነበር።'),
  ('ebfce438-4724-5cc2-af21-10bc8531189a', '146b5232-d7ce-5a8a-a149-236982c83832', '1f209143-9e9e-5d30-a6a1-80dc1740fa5c', 16, 16, 'ከእርሷ ጋር መኖር መራራነት የለበትምና፥ ከደስታና ከሐሤትም በቀር ድካምና ኀዘን አይቀርብምና ወደ ቤቴ በገባሁ ጊዜ በእርሷ ዐርፋለሁ።'),
  ('f04d7d87-d34d-507d-a670-b39a42d008d4', '146b5232-d7ce-5a8a-a149-236982c83832', '1f209143-9e9e-5d30-a6a1-80dc1740fa5c', 17, 17, 'ይህንም በራሴ ሳስብ ኖርሁ፤ ከኀጢአትም መንጻት እንደማይቻለኝ ዐውቄ በልቡናዬ በእርስዋ እተጋለሁ፤ የጥበብ ዝምድናዋ ሕያውነት ነውና።'),
  ('18708341-9206-5e62-ac90-b749dbcb62ca', '146b5232-d7ce-5a8a-a149-236982c83832', '1f209143-9e9e-5d30-a6a1-80dc1740fa5c', 18, 18, 'በፍቅሯም መልካም ደስታ አለ፤ በእጅዋ ሥራም የማያልቅ ብልጽግና አለ፤ በነገሯም ውስጥ የዕውቀት ትምህርት አለ፤ ከእርሷም ጋር አንድ በመሆን የሚያስመካ ነገር አለ፤ ለራሴም እወስዳት ዘንድ እየፈለግኋት ሀገሩን ዞርሁ።'),
  ('5dfd8d80-1e1a-56cc-a7c0-9f37ba61a813', '146b5232-d7ce-5a8a-a149-236982c83832', '1f209143-9e9e-5d30-a6a1-80dc1740fa5c', 19, 19, 'እኔ ዐዋቂ ልጅ ነኝ፤ ሰውነቴም በጎ ሆነችልኝ።'),
  ('65906978-1099-55a1-aa00-0e02e5a22f17', '146b5232-d7ce-5a8a-a149-236982c83832', '1f209143-9e9e-5d30-a6a1-80dc1740fa5c', 20, 20, 'ደግ ነኝና ወደ ንጹሕ ሥጋዋ ገባሁ።'),
  ('47c508b5-966b-587c-a251-478925bc9f7b', '146b5232-d7ce-5a8a-a149-236982c83832', '1f209143-9e9e-5d30-a6a1-80dc1740fa5c', 21, 21, 'እግዚአብሔር እርሷን ካልሰጠኝ በቀር እንደማላገኛት በዐወቅሁ ጊዜ ይህ ምክር ከጥበብ ሆነ፤ የማን ስጦታም እንደ ሆነች ዐውቅ ዘንድ ወደ እግዚአብሔር ጸለይሁ፥ ለመንሁትም።'),
  ('4c1c2ae1-269e-5019-ad20-1a3472995fa5', '292dc297-c54d-5db7-afb0-56246b5fcd3d', 'ae5a41e1-4ebc-5813-ad83-cd10c9fe683a', 1, 1, 'በፍጹም ልቤም እንዲህ አልሁ፥ “የአባቶች አምላክ፥ የምሕረት ጌታ፥ በቃልህ ዓለሙን ሁሉ የፈጠርኽ፤'),
  ('2b019cc5-3e2a-5793-aaff-20b1b4d3219c', '292dc297-c54d-5db7-afb0-56246b5fcd3d', 'ae5a41e1-4ebc-5813-ad83-cd10c9fe683a', 2, 2, 'በጥበብህም ሰውን በአንተ የተፈጠረውን ፍጥረት እንዲገዛ፥'),
  ('d90f13a2-c1e2-5978-a797-ba98f34ed841', '292dc297-c54d-5db7-afb0-56246b5fcd3d', 'ae5a41e1-4ebc-5813-ad83-cd10c9fe683a', 3, 3, 'ዓለሙንም በቸርነትና በጽድቅ እንዲሠራራ፥ በቅን ልቡናም እንዲፈርድ ያደረግኸው፥'),
  ('71f58f95-3ea8-5bdb-a473-fe3b0ebe17cb', '292dc297-c54d-5db7-afb0-56246b5fcd3d', 'ae5a41e1-4ebc-5813-ad83-cd10c9fe683a', 4, 4, 'በዙፋንህ የምትቀመጥ ጥበብን ስጠኝ፥ ከባሮችህም ለይተህ አትናቀኝ።'),
  ('7f230880-8201-5ced-a3d9-f464e661d849', '292dc297-c54d-5db7-afb0-56246b5fcd3d', 'ae5a41e1-4ebc-5813-ad83-cd10c9fe683a', 5, 5, 'እኔ ባሪያህና የሴት ባሪያህ ልጅ፥ ኀይሌ የደከመ ሰው፥ ዘመኔም ያነሰ፥ ሕግንና ፍርድንም ለማወቅ አነስተኛ ነኝና።'),
  ('b0cf3a9c-c92c-55c6-a93e-ee77e846a4fe', '292dc297-c54d-5db7-afb0-56246b5fcd3d', 'ae5a41e1-4ebc-5813-ad83-cd10c9fe683a', 6, 6, '“ከሰው ልጆችም ፍጹም የሆነ ሰው ቢኖር፥ በአንተ ዘንድም የምትገኝ ጥበብ ከእርሱ ብትርቅ እርሱ እንደ ኢምንት በሆነ ነበር።'),
  ('280d1941-ff2c-563a-a221-2c29b35a6f7c', '292dc297-c54d-5db7-afb0-56246b5fcd3d', 'ae5a41e1-4ebc-5813-ad83-cd10c9fe683a', 7, 7, 'አንተ ለሕዝብህ ንጉሥ፥ ለወንዶች ልጆችህና ለሴቶች ልጆችህም ገዢ አድርገህ መረጥኸኝ።'),
  ('255cf03c-9426-5889-a611-74c5e061acda', '292dc297-c54d-5db7-afb0-56246b5fcd3d', 'ae5a41e1-4ebc-5813-ad83-cd10c9fe683a', 8, 8, 'በቅዱስ ተራራህ ላይ ቤተ መቅደስ፥ በማረፊያህም ሀገር ከጥንት ጀምሮ ባዘጋጀኸው በቅድስናህ ማደሪያ አምሳል መሠዊያ እንዲሠራ አዘዝኽ።'),
  ('96d67871-0a99-5a55-a81b-7e4123318518', '292dc297-c54d-5db7-afb0-56246b5fcd3d', 'ae5a41e1-4ebc-5813-ad83-cd10c9fe683a', 9, 9, 'ሥራህንም የምታውቅ ጥበብ ከአንተ ጋር ነበረች፤ ዓለምንም በፈጠርኽ ጊዜ ነበረች፤ በፊትህ ደስ የሚያሰኝህም ምን እንደ ሆነ፥ ለትእዛዝህም የቀናው ምን እንደ ሆነ ትረዳ ነበር።'),
  ('ef333d64-f291-523c-a9d8-4aed631e154b', '292dc297-c54d-5db7-afb0-56246b5fcd3d', 'ae5a41e1-4ebc-5813-ad83-cd10c9fe683a', 10, 10, 'ተነሥታ ትመጣ ዘንድ ከከበሩ ሰማዮች ከጌትነትህ ዙፋን ወደኔ ላካት፤ ከእኔም ጋራ ትኖርና ትደክም ዘንድ ደስ የሚያሰኝህም ምን እንደ ሆነ ዐውቅ ዘንድ ላካት።'),
  ('baf0d24c-25c9-5def-ab1d-d4929f538102', '292dc297-c54d-5db7-afb0-56246b5fcd3d', 'ae5a41e1-4ebc-5813-ad83-cd10c9fe683a', 11, 11, 'አንተ የምታውቀውን ሥራ ሁሉ ታውቃለችና ንጹሕ አድርጋ ወደ ሥራዎች ሁሉ ትምራኝ፤ በኀይሏም ትጠብቀኝ።'),
  ('067ca503-df73-534f-a534-63d93358e9dd', '292dc297-c54d-5db7-afb0-56246b5fcd3d', 'ae5a41e1-4ebc-5813-ad83-cd10c9fe683a', 12, 12, 'ሥራዬ ሁሉ የተወደደ ይሁን፤ ወገኖችህንም በእውነት ልግዛ፤ ለአባቶች ዙፋኖችም የተዘጋጀሁ ልሁን።'),
  ('2e955675-4956-5e6e-aad9-bcd33dfa1362', '292dc297-c54d-5db7-afb0-56246b5fcd3d', 'ae5a41e1-4ebc-5813-ad83-cd10c9fe683a', 13, 13, '“የእግዚአብሔርን ምክር የሚያውቅ ሰው ማን ነው? እግዚአብሔር የሚወድደውንስ ዐስቦ የሚያውቅ ማን ነው?'),
  ('2fbfcfb5-65e6-5203-acd0-02d65167cc6c', '292dc297-c54d-5db7-afb0-56246b5fcd3d', 'ae5a41e1-4ebc-5813-ad83-cd10c9fe683a', 14, 14, 'የሟቾች ዐሳባቸው ፈራሽ ነውና፥ የእኛም ዐሳብ ጐፃጕፅ ነውና።'),
  ('5b3af87e-0c35-5782-ad06-015d0a9a6d1f', '292dc297-c54d-5db7-afb0-56246b5fcd3d', 'ae5a41e1-4ebc-5813-ad83-cd10c9fe683a', 15, 15, 'የሚፈርስ ሥጋ ነፍስን ያሸንፋታልና፥ ይከብዳታልምና፥ ምድራዊ ማደሪያም ልብን ይሸፍናልና።'),
  ('c040898a-5501-52b8-a17e-cbdf784cc188', '292dc297-c54d-5db7-afb0-56246b5fcd3d', 'ae5a41e1-4ebc-5813-ad83-cd10c9fe683a', 16, 16, 'በብዙ ትጋትና ግዳጅ፥ በጭንቅም ብንመረምር በምድር የሚሠራውን ሥራ እናገኛለን፤ በእጃችን የምንዳስሰውንም ሥራ በድካም እናገኛለን። በሰማይ ያለውን ግን ማን መረመረው?'),
  ('80ffbc0e-9892-524f-a0bd-30f16f6831f3', '292dc297-c54d-5db7-afb0-56246b5fcd3d', 'ae5a41e1-4ebc-5813-ad83-cd10c9fe683a', 17, 17, 'አንተ ጥበብን የሰጠኸው፥ ቅዱስ መንፈስህንም ወደ እርሱ ከላይ የላክህለት ሰው ካልሆነ በቀር ምክርህን ማን ዐወቀ?'),
  ('2deb764a-99ca-5c40-ab5f-703042bd007d', '292dc297-c54d-5db7-afb0-56246b5fcd3d', 'ae5a41e1-4ebc-5813-ad83-cd10c9fe683a', 18, 18, 'ስለዚህ በዚህ ዓለም ያሉ ሰዎች መንገዳቸው ቀናላቸው፥ ደስ የሚያሰኝህንም ነገር ሰዎች ዐወቁ፥ በጥበብም ዳኑ።”'),
  ('e3d6ba26-3e0f-5cba-a806-ef08c0eb28bd', 'a78ed7b6-f6ae-58b1-a19c-1cadb468ddaa', '52978bf3-6dcd-5447-a400-689b6271ca5c', 1, 1, 'ይህቺ አስቀድሞ የተፈጠረ የዓለምን አባት ጠበቀች፥ ብቻውንም ከተፈጠረ በኋላ እንደ አደራ ጠበቀችው፥ ከራሱ በደልም አዳነችው።'),
  ('fbf68b44-39cd-5f7c-a88f-0212658a148b', 'a78ed7b6-f6ae-58b1-a19c-1cadb468ddaa', '52978bf3-6dcd-5447-a400-689b6271ca5c', 2, 2, 'ሁሉንም ይገዛና ይይዝ ዘንድ ኀይልን ሰጠችው ።'),
  ('83a99601-b8f1-5447-ad1f-e0621be3230c', 'a78ed7b6-f6ae-58b1-a19c-1cadb468ddaa', '52978bf3-6dcd-5447-a400-689b6271ca5c', 3, 3, 'በደለኛና ግፈኛ ሰውም በቍጣው ከእርሷ በራቀ ጊዜ፥ ወንድሞቻቸውን ከሚገድሉ ሰዎች ጋር በመዓት ጠፋ።'),
  ('17ed9499-48c4-54fe-a180-9adcba6c360a', 'a78ed7b6-f6ae-58b1-a19c-1cadb468ddaa', '52978bf3-6dcd-5447-a400-689b6271ca5c', 4, 4, 'ዳግመኛም ምድር በማየ አይኅ በጠፋች ጊዜ ጥበብ ጻድቁን አዳነችው፥ በተናቀ እንጨት ዕቃም አሻገረችው።'),
  ('ee7bbf3d-86da-59f7-a564-cf597d548797', 'a78ed7b6-f6ae-58b1-a19c-1cadb468ddaa', '52978bf3-6dcd-5447-a400-689b6271ca5c', 5, 5, 'አሕዛብ ወደ ተለያየ ክፋትና ጥመት ተጨልጠው በሄዱ ጊዜ ጻድቁን አመለከተችው፤ ያለ በደልና ያለ ነውር ለእግዚአብሔር ጠበቀችው፤ በቸርነትም የጸና ልጁን ጠበቀች።'),
  ('956c7ae7-1432-5e80-a244-4a66c1a6dd88', 'a78ed7b6-f6ae-58b1-a19c-1cadb468ddaa', '52978bf3-6dcd-5447-a400-689b6271ca5c', 6, 6, 'ይህቺ ከሚጠፉ ዝንጉዎች ሰዎች ለይታ ጻድቁን ልጅ አዳነች፥ በአምስቱ ከተሞችም ላይ እሳት በወረደች ጊዜ በመሸሽ አዳነችው።'),
  ('92c74663-5745-55e4-ae4b-2669bc9423ab', 'a78ed7b6-f6ae-58b1-a19c-1cadb468ddaa', '52978bf3-6dcd-5447-a400-689b6271ca5c', 7, 7, 'ለክፋታቸው ምስክር ልትሆን እስከ ዛሬ ድረስ ምድረ በዳ ሆና እየጤሰች አለች፥ ተክሎችዋም በጊዜዋ ቢያፈሩ ፍጹማን ያልሆኑ ናቸው፤ ያላመነች ሰውነትም መታሰቢያ ሆኖ የሚታይ የጨው ድንጋይ ሆና ቆማለች።'),
  ('38a35776-4d82-5382-af17-f8d728a04908', 'a78ed7b6-f6ae-58b1-a19c-1cadb468ddaa', '52978bf3-6dcd-5447-a400-689b6271ca5c', 8, 8, 'እነዚህ ጥበብን የተላለፉ ናቸውና ደግ ነገርን ባለማወቅ የደረሰባቸውን መዓት በማወቅ እንደ እነዚያ የጠፉ ብቻ አይደለም። ነገር ግን የበደሉትን በደል መሰወር እንዳልተቻላቸው መጠን ለስንፍናቸው መታሰቢያን በዚህ ዓለም ተዉ።'),
  ('e2e405f2-8031-52bd-a0d2-298b416c4241', 'a78ed7b6-f6ae-58b1-a19c-1cadb468ddaa', '52978bf3-6dcd-5447-a400-689b6271ca5c', 9, 9, 'ጥበብስ የሚያገለግሏትን ሰዎች ከድካምና ከመከራ አዳነች።'),
  ('3b25bbc8-b8af-547f-abc0-9f903f1d6ceb', 'a78ed7b6-f6ae-58b1-a19c-1cadb468ddaa', '52978bf3-6dcd-5447-a400-689b6271ca5c', 10, 10, 'ይህች ከወንድሙ ቍጣ የተነሣ የሸሸውን ጻድቅ ሰው ወደ ቀና መንገድ መራችው። የእግዚአብሔርንም መንግሥት አሳየችው፤ የተቀደሱትንም ማወቅን ሰጠችው፥ ከድካሙ የተነሣም አበለጸገችው፥ ጥሪቱንም አበዛችለት።'),
  ('b580a530-5f61-5886-a063-fb27184bb1d6', 'a78ed7b6-f6ae-58b1-a19c-1cadb468ddaa', '52978bf3-6dcd-5447-a400-689b6271ca5c', 11, 11, 'ከሚቀሙትና ከሚበረታቱበትም ሰዎች የተነሣ ጠበቃ ሆና ቆመችለት፤ ረዳችውም።'),
  ('44678440-ce13-55fc-a229-2ebe158291b9', 'a78ed7b6-f6ae-58b1-a19c-1cadb468ddaa', '52978bf3-6dcd-5447-a400-689b6271ca5c', 12, 12, 'ከጠላቶቹም እንደ አደራ ዕቃ ጠበቀችው፥ ከከበቡትም ሰዎች አዳነችው። ለእግዚአብሔርም በበጎ መገዛት ከሁሉ እንደሚጸና ያውቅ ዘንድ በጽኑ ገድል ጊዜ ድልን ሰጠችው።'),
  ('7381a712-a81d-5a99-a30c-a09eafa5ec31', 'a78ed7b6-f6ae-58b1-a19c-1cadb468ddaa', '52978bf3-6dcd-5447-a400-689b6271ca5c', 13, 13, 'ይሀቺ ጥበብ በተሸጠ ጊዜ ጻድቁን ሰው አልተለየችውም፤ ነገር ግን ወደ ጕድጓድ ከእርሱ ጋር ወረደች፥ ከኀጢአትም አዳነችው።'),
  ('6b26507c-54d7-50a4-a201-c0f22bf9c033', 'a78ed7b6-f6ae-58b1-a19c-1cadb468ddaa', '52978bf3-6dcd-5447-a400-689b6271ca5c', 14, 14, 'በተበረታቱበትም ሰዎች ላይ ግዛትንና የመንግሥትን ሹመት እስከምታመጣለት ድረስ በታሠረበት አልተለየችውም። የናቁትንና ያነወሩትንም ሐሰታቸውን ገለጠችባቸው። የዘለዓለምንም ክብር ሰጠችው።'),
  ('f1fabd11-cc8e-5335-a0f4-d12dff6df0a0', 'a78ed7b6-f6ae-58b1-a19c-1cadb468ddaa', '8684a68a-af9a-5ff2-aff2-8901a20b9513', 1, 15, 'ይህቺም ጥበብ ጻድቅ ሕዝብን፥ ነቀፋ የሌለበት ዘርንም ከሚያስጨንቋቸው አሕዛብ አዳነች።'),
  ('3601f8e7-6449-55c1-af37-376a51521a4f', 'a78ed7b6-f6ae-58b1-a19c-1cadb468ddaa', '8684a68a-af9a-5ff2-aff2-8901a20b9513', 2, 16, 'በእግዚአብሔር ባሪያ ሰውነትም አደረች፤ በተአምራትና በድንቅ ሥራዎችም የሚያስደነግጡ ነገሥታትን ተቃወመች።'),
  ('e6b82481-42f2-5224-a63d-6c4ca790c66c', 'a78ed7b6-f6ae-58b1-a19c-1cadb468ddaa', '8684a68a-af9a-5ff2-aff2-8901a20b9513', 3, 17, 'ለቅዱሳንም የድካማቸውን ዋጋ ሰጠቻቸው፥ የተደነቀ መንገድንም መራቻቸው፥ በቀንም ጥላ ሆነቻቸው፥ በሌሊትም ስለ ከዋክብት ብርሃን ፈንታ ብርሃን ሆና አበራችላቸው።'),
  ('c7f23599-3b2b-5643-a8e3-86bb0aacca13', 'a78ed7b6-f6ae-58b1-a19c-1cadb468ddaa', '8684a68a-af9a-5ff2-aff2-8901a20b9513', 4, 18, 'የሚያስፈራ የኤርትራ ባሕርንም አሻገረቻቸው፥ በብዙ ውኃ መካከልም አሳለፈቻቸው።'),
  ('e609c994-feed-5b5c-aae9-ce3fcb9f2218', 'a78ed7b6-f6ae-58b1-a19c-1cadb468ddaa', '8684a68a-af9a-5ff2-aff2-8901a20b9513', 5, 19, 'ጠላቶቻቸውን ግን አሰጠመች፥ እነርሱንም ከጥልቅ ባሕር አወጣቻቸው።'),
  ('19203318-061e-5efa-ae83-9d92c3c9198a', 'a78ed7b6-f6ae-58b1-a19c-1cadb468ddaa', '8684a68a-af9a-5ff2-aff2-8901a20b9513', 6, 20, 'ስለዚህም ነገር ጻድቃን ክፉዎችን ማረኩ። አቤቱ ቅዱስ ስምህንም አመሰገኑ። ተዋጊና አሸናፊ እጅህንም በአንድነት አከበሩ።'),
  ('307c20d1-0cf8-5686-a439-5c40a19facd2', 'a78ed7b6-f6ae-58b1-a19c-1cadb468ddaa', '8684a68a-af9a-5ff2-aff2-8901a20b9513', 7, 21, 'ጥበብ የዲዳዎችን አፍ ከፍታለችና፥ የሕፃናትንም አንደበት ቀንቶ የሚናገር አድርጋለችና።'),
  ('b97b640a-3c8a-54ee-afc8-26df03ca6838', 'c9ae20f1-6849-504f-ae77-4c3ff567ead9', '39d01bc2-eede-571f-a10d-83a2cc23454e', 1, 1, 'እርስዋ በቅዱሱ ነቢይ እጅ ሥራቸውን አቃናች፤'),
  ('5091f87d-a939-545d-ae89-01306b34935d', 'c9ae20f1-6849-504f-ae77-4c3ff567ead9', '39d01bc2-eede-571f-a10d-83a2cc23454e', 2, 2, 'ማንም ወዳልኖረበት ምድረ በዳም ሄደው ኖሩ። ባልተረገጠች ቦታም የድንኳኖቻቸውን ካስማ ተከሉ።'),
  ('5a30d686-5421-5c2d-a637-9c59257fcb3e', 'c9ae20f1-6849-504f-ae77-4c3ff567ead9', '39d01bc2-eede-571f-a10d-83a2cc23454e', 3, 3, 'ተዋጊዎችንም ተቋቋሟቸው፤ ጠላቶችንም ተበቀሏቸው።'),
  ('8140af80-648b-5f4f-a37f-f9487a62afdb', 'c9ae20f1-6849-504f-ae77-4c3ff567ead9', '39d01bc2-eede-571f-a10d-83a2cc23454e', 4, 4, 'በተጠሙ ጊዜም ጠሩህ፥ ከዐለት ድንጋይም ውኃ ተሰጣቸው። ከጽኑ ድንጋይም ለጥማቸው ፈውስ ተሰጣቸው።'),
  ('44a91297-b17b-5747-a825-7ed39efcf512', 'c9ae20f1-6849-504f-ae77-4c3ff567ead9', '39d01bc2-eede-571f-a10d-83a2cc23454e', 5, 5, 'ጠላቶቻቸውም በዚህ ሥራ ተፈርዶባቸው ጠፉ።'),
  ('68f3eeb5-6217-598f-a757-1a921171c247', 'c9ae20f1-6849-504f-ae77-4c3ff567ead9', '39d01bc2-eede-571f-a10d-83a2cc23454e', 6, 6, 'በዚህም ተቸግረው በተጨነቁ ጊዜ በጎ ነገርን አደረግህላቸው።'),
  ('2596ea14-05c6-5682-a3d8-1d71d881042e', 'c9ae20f1-6849-504f-ae77-4c3ff567ead9', '39d01bc2-eede-571f-a10d-83a2cc23454e', 7, 7, 'በተገደሉት ሰዎች ደም እነዚያ ባደፈረሱት በማይጐድለው ወንዝ ምንጭ ፋንታ፥'),
  ('2688a4aa-c762-50da-aa27-b84fb33486a9', 'c9ae20f1-6849-504f-ae77-4c3ff567ead9', '39d01bc2-eede-571f-a10d-83a2cc23454e', 8, 8, 'ሕፃናት በዐዋጅ መገደላቸውን ለመዝለፍ በተስፋ ሳታስጠብቅ ፈጥነህ ያመነጨኸውን ብዙ ውኃ ሰጠኻቸው።'),
  ('fd396c28-21a3-5db4-a26a-12d31c19761f', 'c9ae20f1-6849-504f-ae77-4c3ff567ead9', '39d01bc2-eede-571f-a10d-83a2cc23454e', 9, 9, 'እንደዚሁም በተጠሙ ጊዜ ስለተፈታተኑህ ተቃዋሚዎችን ፈረድህባቸው።'),
  ('9ea5b872-3f3f-5753-ab16-097aba68f6bf', 'c9ae20f1-6849-504f-ae77-4c3ff567ead9', '39d01bc2-eede-571f-a10d-83a2cc23454e', 10, 10, 'እነርሱ ግን በምሕረትህ ተገሠጹ፥ ክፉዎችም በመዓት በተፈረደባቸው ጊዜ እንዴት እንደ ተቀጡ ዐወቁ።')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('2cf34403-8f51-5960-ac83-21cb680b8c84', 'c9ae20f1-6849-504f-ae77-4c3ff567ead9', '39d01bc2-eede-571f-a10d-83a2cc23454e', 11, 11, 'እነዚህንም እንደሚቀጣ አባት ገሠጽኻቸው። እነዚያን ግን ርኅራኄ እንደሌለው ንጉሥ ተከትለህ ቀጣኻቸው።'),
  ('b5444a89-2568-593e-a191-d0064f5397ae', 'c9ae20f1-6849-504f-ae77-4c3ff567ead9', '39d01bc2-eede-571f-a10d-83a2cc23454e', 12, 12, 'በዚህም አምሳል ገረፍኻቸው። ሳሉም፥ ሳይኖሩም አሳዘንኻቸው።'),
  ('51dbd2b3-c746-5d3e-a301-7ef77572936d', 'c9ae20f1-6849-504f-ae77-4c3ff567ead9', '39d01bc2-eede-571f-a10d-83a2cc23454e', 13, 13, 'እጥፍ ኀዘን አግኝቶአቸዋልና፥ ያለፈውንም ክፉ ነገር የማሰብ ጩኸት አግኝትዋቸዋልና።'),
  ('37001ee2-f7d1-5a6c-a420-8d11414d8876', 'c9ae20f1-6849-504f-ae77-4c3ff567ead9', '39d01bc2-eede-571f-a10d-83a2cc23454e', 14, 14, 'በመከራቸውም በጎ ነገር እንዳደረገላቸው በሰሙ ጊዜ እነርሱ ከእግዚአብሔር የተገኘ ደስታ አደረጉት።'),
  ('8fe38d53-2674-598d-ab18-649d9c61aa1f', 'c9ae20f1-6849-504f-ae77-4c3ff567ead9', 'a7ef3787-f651-5152-ac51-ac706191f9ba', 1, 15, 'ዳግመኛም በክፋት ቀድሞ የጣሉትን አጡት፤ ከዚህም በኋላ በመዘባበት ከእርሱ ሸሹ፤ ከትእዛዙ መውጣት ፍጻሜ የተነሣም አደነቁ፥ ጻድቃንም እንደ ተጠሙ እነርሱ የተጠሙ አይደሉም።'),
  ('72c70206-68dc-5666-aea8-1d6ca8145278', 'c9ae20f1-6849-504f-ae77-4c3ff567ead9', 'a7ef3787-f651-5152-ac51-ac706191f9ba', 2, 16, 'አእምሮ በሌላት በልቡናቸው ክፋት በሳቱባት ጊዜ፥ የማይናገር፥ የተናቀና ከንቱ ሀብት እንስሳን አምልከዋልና፥'),
  ('4c9cbe41-a751-5d9a-a5c7-4a9cfa49f90b', 'c9ae20f1-6849-504f-ae77-4c3ff567ead9', 'a7ef3787-f651-5152-ac51-ac706191f9ba', 3, 17, 'ሰው በበደለበት ሥራ እንዲፈረድበት ያውቁ ዘንድ ለመበቀል የማይናገር ብዙ እንስሳን ላክህባቸው።'),
  ('4fa30ed2-42ef-50b3-a8a2-ae83e8dd07de', 'c9ae20f1-6849-504f-ae77-4c3ff567ead9', 'a7ef3787-f651-5152-ac51-ac706191f9ba', 4, 18, 'ዓለምን ካለመኖር ለፈጠረ ሁሉን ለሚችል ቀኝ እጅህ ብዙ ድቦችንና ቍጡ አንበሶችን ትልክባቸው ዘንድ አይሳነውምና።'),
  ('35460377-8c23-5ee6-aa19-3445d8083be3', 'c9ae20f1-6849-504f-ae77-4c3ff567ead9', 'a7ef3787-f651-5152-ac51-ac706191f9ba', 5, 19, 'ያም ባይሆን ድንገት የተፈጠሩ የማይታወቁ፥ የሚያላልብና የሚፋጅ እሳትን የሚተነፍሱ፥ ያም ባይሆን የሚከረፋ የጢስ መዓዛን የሚተነፍሱ፥ ያም ባይሆን ከክፉ ዓይናቸው የእሳት ፍንጣሪን ቦግ ቦግ የሚያደርጉ ቍጣን የተሞሉ አውሬዎችን ላክህባቸው።'),
  ('463c8727-941b-5596-ad4b-45bf7f3eaa83', 'c9ae20f1-6849-504f-ae77-4c3ff567ead9', 'a7ef3787-f651-5152-ac51-ac706191f9ba', 6, 20, 'ሊያጠፋቸው የሚችል ክፋታቸው ወይም ፍርዳቸው ብቻ አይደለም። ነገር ግን መልካቸው ባስፈራቸውና ባጠፋቸው ነበር።'),
  ('bc58b71c-1fc6-5fec-a65f-0f5c73558907', 'c9ae20f1-6849-504f-ae77-4c3ff567ead9', '862bc2b8-973f-5024-a398-5685bba375cb', 1, 21, 'ከዚህም በቀር፦ ስታባርራቸው፥ በኀይልህ መንፈስም ስታጠፋቸው፥ በአንዲት ምልክት ይጠፉ ዘንድ በተገባቸው ነበር። ነገር ግን ሁሉን በመጠን፥ በቍጥርና በሚዛን ሠራህ።'),
  ('3037fd45-c3a4-5a37-aa0d-85b7cb36cb36', 'c9ae20f1-6849-504f-ae77-4c3ff567ead9', '862bc2b8-973f-5024-a398-5685bba375cb', 2, 22, 'የከሃሊነትህ ገናናነት በአንተ ዘንድ ሁልጊዜ ይኖራልና፥ የክንድህ ጽንዐት ኀይልንም ማን ይቃወማታል?'),
  ('9d0a8db1-0456-559f-a977-b8872470c09b', 'c9ae20f1-6849-504f-ae77-4c3ff567ead9', '862bc2b8-973f-5024-a398-5685bba375cb', 3, 23, 'ዓለሙ ሁሉ በፊትህ እንደ ሚዛን ውልብልቢት ነውና፥ በማለዳም በምድር ላይ እንደ ወረደች እንደ ጠል ጠብታ ነውና።'),
  ('c282bd6f-af46-5802-a93f-a26885fdd313', 'c9ae20f1-6849-504f-ae77-4c3ff567ead9', '862bc2b8-973f-5024-a398-5685bba375cb', 4, 24, 'አንተ ሁሉን የምትችል ነህና ሁሉን ይቅር ትላለህ፥ ለንስሓም እየጠበቅኸው የሰውን ኀጢአት ቸል ትላለህ።'),
  ('95f0033f-3539-531f-aa62-84e76b0ee0d7', 'c9ae20f1-6849-504f-ae77-4c3ff567ead9', '862bc2b8-973f-5024-a398-5685bba375cb', 5, 25, 'ያሉትን ሁሉ ትወዳለህ፥ ከፈጠርኸው ፍጥረትም ምንም የምትንቀው የለም፥ ብትጠላውስ ኖሮ አትፈጥረውም ነበርና።'),
  ('db1c654e-b0e6-532b-a6f9-2063b36df651', 'c9ae20f1-6849-504f-ae77-4c3ff567ead9', '862bc2b8-973f-5024-a398-5685bba375cb', 6, 26, 'አንተ ካልወደድኸው በፊትህ እንደምን በጸና ነበር! አንተስ ካልጠራኸው እንደምን በተጠበቀ ነበር!'),
  ('425e466b-5674-56d8-a683-c0819f8635e0', 'c9ae20f1-6849-504f-ae77-4c3ff567ead9', '862bc2b8-973f-5024-a398-5685bba375cb', 7, 27, 'ለፍጥረቱም ሁሉ ትራራለህ፥ ይቅርም ትላለህ። ሰውን የምትወድድ አቤቱ፥ ሁሉ ያንተ ነውና፥'),
  ('f3fcd124-551a-5708-a276-fc26036202ce', '795eb97c-48dc-5d97-ac8b-a0433af2029e', '7ed2d1b1-3c23-5707-a804-641b54427df2', 1, 1, 'ጥፋት የሌለበት ቸር መንፈስህ በሁሉ አለና።'),
  ('86c1778c-e59e-5ca1-a5ea-54e18514f3ea', '795eb97c-48dc-5d97-ac8b-a0433af2029e', '7ed2d1b1-3c23-5707-a804-641b54427df2', 2, 2, 'ስለዚህም የተሰነካከሉትን ሰዎች ለፍርድ እንዲመች ጥቂት በጥቂት ትዘልፋቸዋለህ፤ የበደሉትንም በደል ታሳስባቸዋለህ፤ ከክፋታቸውም ርቀው ኀጢአታቸውን በተረዱ ጊዜ አቤቱ፥ ያምኑብህ ዘንድ ትገሥጻቸዋለህ።'),
  ('fdb86336-e6b0-5882-a5ab-7033c73eb9ac', '795eb97c-48dc-5d97-ac8b-a0433af2029e', 'a3d9a779-1a02-5f49-a89a-447529860450', 1, 3, 'በቅድስት ሀገርህ የሚኖሩትን የቀደሙትን ሰዎች፥'),
  ('bb2ba05f-3885-5e91-a932-4e843ca3d6d4', '795eb97c-48dc-5d97-ac8b-a0433af2029e', 'a3d9a779-1a02-5f49-a89a-447529860450', 2, 4, 'ስለ ተጠላ የሟርት ሥራቸውና ከጽድቅ ስለራቀ በዓላቸው፥'),
  ('298dd1c7-3d6b-50f0-a96e-1ee637bd92c6', '795eb97c-48dc-5d97-ac8b-a0433af2029e', 'a3d9a779-1a02-5f49-a89a-447529860450', 3, 5, 'ያለርኅራኄም ልጆቻቸውን ስለመግደላቸው፥ የሰዎችን ሆድ ዕቃና ሥጋቸውን ለመብላት፥ ደማቸውንም ለመጠጣት ስለ መፍቀዳቸው ጠልተኻቸዋል። የጌትነትህን ምሥጢራት ማወቅ ከመካከላቸው ርቋልና።'),
  ('7bf2ecab-6b3e-55f7-ab46-572ef5a5ec1a', '795eb97c-48dc-5d97-ac8b-a0433af2029e', 'a3d9a779-1a02-5f49-a89a-447529860450', 4, 6, 'ከማንም ዘንድ ረዳት የሌላቸው ሰዎችንም ይገድላሉ፥ በአባቶቻችንም እጅ ታጠፋቸው ዘንድ ወደድህ።'),
  ('dae36d6b-7b3d-5509-a246-f10599d54018', '795eb97c-48dc-5d97-ac8b-a0433af2029e', 'a3d9a779-1a02-5f49-a89a-447529860450', 5, 7, 'ይህም የእግዚአብሔር ልጆች ከሀገሩ ሁሉ በአንተ ዘንድ የከበረች ለእነርሱ የምትገባ ሀገርን ይይዙ ዘንድ ነው።'),
  ('326bc10c-2ee0-5a0d-abc7-f067a8da083e', '795eb97c-48dc-5d97-ac8b-a0433af2029e', 'a3d9a779-1a02-5f49-a89a-447529860450', 6, 8, 'ነገር ግን ሰውን ይቅር እንደምትል እነርሱንም ይቅር አልኻቸው፤ እነርሱንም ጥቂት በጥቂት እንዲያጠፉ ከሠራዊትህ አስቀድሞ የትንኝ ወራሪን ላክህባቸው።'),
  ('1ad918c7-f0ce-52af-a14b-b223f80c6a53', '795eb97c-48dc-5d97-ac8b-a0433af2029e', 'a3d9a779-1a02-5f49-a89a-447529860450', 7, 9, 'ያም ባይሆን በየወገኖቻቸው እንዲማርኳቸው ክፉዎችን በጻድቃን እጅ ትጥላቸው ዘንድ አይሳንህም ነበር፥ ያም ባይሆን ለክፉዎች አውሬዎች ትሰጣቸው ዘንድ፥ ያም ባይሆን በአንድ ቃል አዝዘህ ታጠፋቸው ዘንድ አይሳንህም ነበር።'),
  ('a7f2ea7a-45a2-5a2f-a8e1-f30a00498e33', '795eb97c-48dc-5d97-ac8b-a0433af2029e', 'a3d9a779-1a02-5f49-a89a-447529860450', 8, 10, 'ለእነዚህ የንስሓ ቦታ ሰጥተህ ይህ ጥቂት በጥቂት ይሆን ዘንድ ፈረድህ፤ ይህንም ማድረግህ አኗኗራቸው ክፉ እንደ ሆነ፥ ክፋታቸውም እጅግ እንደ በዛ፥ ዐሳባቸውም ለዘለዓለም እንደማይመለስ ሳታውቅ አይደለም።'),
  ('a4734973-246b-5650-a623-a44aa45244f4', '795eb97c-48dc-5d97-ac8b-a0433af2029e', 'a3d9a779-1a02-5f49-a89a-447529860450', 9, 11, 'ከጥንት ጀምሮ የተረገሙ ዘሮች ናቸውና፥ በበደሉበት በደል ዕድሜን የምትሰጣቸው ማንንም አፍረህ አይደለም።'),
  ('d339181c-73ea-5eb0-a291-a30656fb869c', '795eb97c-48dc-5d97-ac8b-a0433af2029e', 'a5cb07ed-cc58-567f-abbe-ab49efbaeaf6', 1, 12, '“ምን አደረግህ?” የሚልህ ማን ነው? ፍርድህንስ የሚቃወመው ማን ነው? ወይስ የሚከስህ ማን ነው? አንተ የፈጠርኻቸው አሕዛብስ ስለ ጠፉ የሚመራመርህ ማን ነው? ስለ በደለኞች ሰዎችም ለመከራከር ወደ አንተ የሚደርስ ዳኛ ማን ነው?'),
  ('92874550-d522-5014-a513-96ce9367327b', '795eb97c-48dc-5d97-ac8b-a0433af2029e', 'a5cb07ed-cc58-567f-abbe-ab49efbaeaf6', 2, 13, 'የፈረድህ በግፍ እንዳይደለ ትገልጥ ዘንድ ስለ ሰው ሁሉ የሚያስብ ከአንተ በቀር ሌላ አምላክ የለምና።'),
  ('25911b6e-e3a5-5cdf-a74f-a22603c308ae', '795eb97c-48dc-5d97-ac8b-a0433af2029e', 'a5cb07ed-cc58-567f-abbe-ab49efbaeaf6', 3, 14, 'ንጉሥም ቢሆን፥ መስፍንም ቢሆን ስለ ፈረድህባቸው ሰዎች አንተን እያማ ከአንተ ጋር መተያየት አይችልም።'),
  ('91bda409-2fda-5040-a912-533dd33a89e4', '795eb97c-48dc-5d97-ac8b-a0433af2029e', 'a5cb07ed-cc58-567f-abbe-ab49efbaeaf6', 4, 15, 'አንተ ሁሉን በእውነት የምታዘጋጅ እውነተኛ ነህና ለፍርድ የተገባ ያይደለውን ትፈርድበት ዘንድ ከኀይልህ የተነሣ ልዩ ሥራ ነው።'),
  ('24c9d57a-6859-5706-a3b9-8afdcf6e817a', '795eb97c-48dc-5d97-ac8b-a0433af2029e', 'a5cb07ed-cc58-567f-abbe-ab49efbaeaf6', 5, 16, 'ከሃሊነትህ የጽድቅ መጀመሪያ ነውና፥ ሁሉን መፍጠርህና መግዛትህ ሁሉን ይቅር እንድትል ያደርግሃል።'),
  ('0f6b7a24-da8f-507b-a3ae-af23a94c3197', '795eb97c-48dc-5d97-ac8b-a0433af2029e', 'a5cb07ed-cc58-567f-abbe-ab49efbaeaf6', 6, 17, 'የከሃሊነትህንም ፍጻሜ በማያምን ኀይልህን ገልጠሃልና የማያምኑትን መደፋፈራቸውን ትዘልፋለህ።'),
  ('6f3bbfb8-3061-55f5-a159-123399fe3e8a', '795eb97c-48dc-5d97-ac8b-a0433af2029e', 'a5cb07ed-cc58-567f-abbe-ab49efbaeaf6', 7, 18, 'አንተ ኀያል መኰንን ስትሆን በቅንነት ትፈርዳለህ። መቼም ቢሆን ከወደድህ ከሃሊነት በአንተ ዘንድ አለና በብዙ ቸርነት ታኖረናለህ።'),
  ('280841dc-693b-5860-ac5d-d179358d0cc1', '795eb97c-48dc-5d97-ac8b-a0433af2029e', 'a5cb07ed-cc58-567f-abbe-ab49efbaeaf6', 8, 19, 'እንዲህ ባለ ሥራም ጻድቅ ሰው ርኅሩኅና ሰው ወዳጅ መሆን ይገባው ዘንድ ወገኖችህን አስተማርህ፤ ለልጆችህም በጎ ተስፋን አደረግህ፥ አንተ ለበደለኛ ንስሓን ትሰጣለህና።'),
  ('298d11ff-cbcc-5b7c-a962-d5664ac555a5', '795eb97c-48dc-5d97-ac8b-a0433af2029e', 'a5cb07ed-cc58-567f-abbe-ab49efbaeaf6', 9, 20, 'ለሞት የሚገቡ እነዚህ የልጆችህ ጠላቶች ባሉበት ዘንድም በእንዲህ ያለ ትዕግሥት ፈረድህ፥ ከክፉም ይድኑባት ዘንድ ዘመንንና መንገድን ሰጠሃቸው።'),
  ('801041ac-8871-5c2b-a6a0-9d36c103f112', '795eb97c-48dc-5d97-ac8b-a0433af2029e', 'a5cb07ed-cc58-567f-abbe-ab49efbaeaf6', 10, 21, 'ለበጎ ተስፋ መሓላንና ቃል ኪዳንን ለሰጠሃቸው ለልጆችህ ምን ያህል ተጠንቅቀህ ትፈርድላቸው ይሆን?'),
  ('001b25c0-f1b3-5e06-a245-b2e6006de847', '795eb97c-48dc-5d97-ac8b-a0433af2029e', 'a5cb07ed-cc58-567f-abbe-ab49efbaeaf6', 11, 22, 'ስለዚህም በፈረድህባቸው ጊዜ ቸርነትህን እናስብ ዘንድ፥ እኛን እየመከርህ ጠላቶቻችንን በብዙ ፍርድ ብዙ ጊዜ ትቀጣቸዋለህ፤ በፈረድህብንም ጊዜ ይቅርህታን ተስፋ እናደርጋለን።'),
  ('8c0a2b1d-58a5-502c-a975-8fe735b78bfc', '795eb97c-48dc-5d97-ac8b-a0433af2029e', '5efc2704-ce41-59d9-a9f1-d2127d703bad', 1, 23, 'በዚህ ግን በስንፍናና በኀጢአት የኖሩ በደለኞች ሰዎችን ቀጣህ፥ በየራሳቸውም ኀጢአት ፈረድህባቸው።'),
  ('a4dfd796-1c5f-56f7-a114-de466df6cef7', '795eb97c-48dc-5d97-ac8b-a0433af2029e', '5efc2704-ce41-59d9-a9f1-d2127d703bad', 2, 24, 'በጠላቶቻቸው ዘንድ ያሉ የተዋረዱ ከብቶችን አማልክት እያሉ ብዙ ዘመን በስሕተት ጐዳና ተጐድተዋልና፥ ዕውቀት እንደሌላቸው ልጆችም ሐሰትን ተናገሩ።'),
  ('fa4378db-4c0e-5755-a8c7-f003dfe36986', '795eb97c-48dc-5d97-ac8b-a0433af2029e', '5efc2704-ce41-59d9-a9f1-d2127d703bad', 3, 25, 'ስለዚህም ምክንያት እንደሌላቸው ሕፃናት ስለሆኑ እንደ ዋዛቸው መጠን ፍርድን በእነርሱ ላይ አመጣህ።'),
  ('fece1513-4b47-55b4-a0c8-0c5d99f341f6', '795eb97c-48dc-5d97-ac8b-a0433af2029e', '5efc2704-ce41-59d9-a9f1-d2127d703bad', 4, 26, 'በቍጣው ተግሣጽ ካልተመለሱ የጻድቅ እግዚአብሔር የፍርዱን እንጀራ ይቅመሱ፤ እነርሱ ባገኛቸው መከራ አንጐራጕረዋልና፥ ቸልም ብለዋልና።'),
  ('1428a899-f463-5fbf-a50f-34453a25fc7c', '795eb97c-48dc-5d97-ac8b-a0433af2029e', '5efc2704-ce41-59d9-a9f1-d2127d703bad', 5, 27, 'አማልክት እንደ ሆኑ ባሰቧቸው በእነዚህ በጣዖታቱ በተፈረደባቸው ጊዜ ቀድሞ የካዱትን ያውቁታል፥ ጻድቅ አምላክ እንደ ሆነም ያውቁታል፤ ስለዚህም ፍጹም የፍርድ ቅጣት ደረሰባቸው።'),
  ('54fa2b13-be5b-5b19-ad1d-83463b9cf110', '307756a2-3f77-5c99-aab9-40ae8387aff2', '624781f2-198e-5633-a73f-cc65d6c1078e', 1, 1, 'እግዚአብሔርን የማወቅ ጕድለት በልቡናቸው ያለባቸው ሰዎች ሁሉ በእውነት ከንቱ ናቸውና፥ በሚታዩ መልካም ነገሮች ያለውን ያውቁ ዘንድ ተሳናቸው፥ ሥራውንም እያዩ ሠሪውን አላወቁትም።'),
  ('aa02e8a5-35cd-5eb3-a17a-a206ade83923', '307756a2-3f77-5c99-aab9-40ae8387aff2', '624781f2-198e-5633-a73f-cc65d6c1078e', 2, 2, 'ነገር ግን እሳትንና ፈጥኖ የሚነፍሰውን ነፋስ፥ ወይም የከዋክብትን ዙረት፥ ወይም የውኃውን ሞገድ፥ ወይም የሰማይ ብርሃናትን ዓለሙን የሚያስተዳድሩ አማልክት አስመሰሏቸው።'),
  ('1f544b1a-2e59-5ee9-aa73-ac3ceadb9df2', '307756a2-3f77-5c99-aab9-40ae8387aff2', '624781f2-198e-5633-a73f-cc65d6c1078e', 3, 3, 'በመልካቸው ውበት ደስ ባላቸው ጊዜ እነዚህን ፍጥረታት አማልክት ካደረጓቸው፥ ውበትን የፈጠረ እርሱ ይህን ፍጥረት ፈጥሯልና የእነዚህ ጌታ ፈጽሞ እንደሚበልጥ ይወቁ።'),
  ('5ac6c82b-b7bf-5b58-a82e-113e39af4367', '307756a2-3f77-5c99-aab9-40ae8387aff2', '624781f2-198e-5633-a73f-cc65d6c1078e', 4, 4, 'ከኀይላቸውና ከሥራቸው የተነሣ ከተደነቁስ የፈጠራቸው እርሱ ፈጽሞ ኀያል እንደ ሆነ ያስተውሉ።'),
  ('3ecbe5d7-1677-5fa0-a562-8ef9ff369fe9', '307756a2-3f77-5c99-aab9-40ae8387aff2', '624781f2-198e-5633-a73f-cc65d6c1078e', 5, 5, 'ፍጡራን የፍጥረታትን ውበት ታላቅነት አይተው የፍጥረታትን ፈጣሪ በእርሱ መስለውታል።'),
  ('70e6ca7c-c7c9-5d34-ade3-918185548c9b', '307756a2-3f77-5c99-aab9-40ae8387aff2', '624781f2-198e-5633-a73f-cc65d6c1078e', 6, 6, 'ነገር ግን ከዚህ ጋራ ዳግመኛ አምላክን እየፈለጉት፥ ያገኙትም ዘንድ እየወደዱ ቢሳሳቱ፥ በእነርሱ ላይ የሚኖረው ነቀፋ ጥቂት አይደለም።'),
  ('b1ac59a6-e5c8-56ee-a5bd-b031a3c00c73', '307756a2-3f77-5c99-aab9-40ae8387aff2', '624781f2-198e-5633-a73f-cc65d6c1078e', 7, 7, 'ወደ ሥራው ተመልሰው በፈለጉት ነበርና፥ እነርሱ ግን በማየት አበቁ፥ የሚታዩት መልካሞች ናቸውና።'),
  ('12db3278-f566-5361-a1b9-0ceccc448bf0', '307756a2-3f77-5c99-aab9-40ae8387aff2', '624781f2-198e-5633-a73f-cc65d6c1078e', 8, 8, 'ዳግመኛም ምክንያታቸው ብዙ ነው።'),
  ('df3c963c-9a33-5dfd-a367-90f82eab8258', '307756a2-3f77-5c99-aab9-40ae8387aff2', '624781f2-198e-5633-a73f-cc65d6c1078e', 9, 9, 'ዓለምን መረዳት እስኪገባቸው ድረስ ይመለከቱ ዘንድ ይህን ያህል ከተቻላቸው የእነዚህን ጌታ ፈጥነው ያገኙት ዘንድ እንዴት አልቻሉም?'),
  ('039f3cd4-4fdf-563b-a347-9d4de409e323', '307756a2-3f77-5c99-aab9-40ae8387aff2', '624781f2-198e-5633-a73f-cc65d6c1078e', 10, 10, 'ከወርቅና ከብር በጥበብ የተሠሩ የሰው እጅ ሥራዎችን፥ የእንስሳ ምሳሌን፥ ወይም የማይጠቅም የጥንት የእጅ ሥራ ድንጋይን አማልክት ብለው የሚጠሩ እነዚህ ጐስቋሎች ናቸው፥ ተስፋቸውም በሞቱ ነገሮች ላይ ነው።'),
  ('7c66d03e-ca78-54ab-ab66-24e9dad60fb7', '307756a2-3f77-5c99-aab9-40ae8387aff2', '624781f2-198e-5633-a73f-cc65d6c1078e', 11, 11, 'የሚታየውንና የሚወዛወዘውን እንጨት የሚጠርብ ጠራቢ ቢኖር መልካም ሆኖ የበቀለውን እንጨት ይቈርጣል፥ ቅርፊቱን ሁሉ በጥበብ ይጠርባል፤ መልካም አድርጎም ይሠራዋል፥ ለኑሮ አገልግሎትም የሚጠቅም ዕቃ አድርጎ ይሠራዋል።'),
  ('a40fa1ac-5753-51f1-a7b6-c25dc8b9dc3f', '307756a2-3f77-5c99-aab9-40ae8387aff2', '624781f2-198e-5633-a73f-cc65d6c1078e', 12, 12, 'ምግቡንም ለማዘጋጀት የሥራውን ጠረባ ከፈጸመ በኋላ ይጠግባል።'),
  ('31d16beb-e53b-5bfc-abd8-978d2d7ceef6', '307756a2-3f77-5c99-aab9-40ae8387aff2', '624781f2-198e-5633-a73f-cc65d6c1078e', 13, 13, 'ዳግመኛም ለምንም ከማይጠቅም እንጨት የተረፈ ጕማጁን፥ ጕጣሙንና ጫፉ ሁሉ የጠመመውን እንጨት ወስዶ ሥራውን በማስተንተን ይጠርበዋል፥ ከዚህም በኋላ በቦዘነበት ቀን በሰው መልክ መስሎ ይቀርፀዋል።'),
  ('cf22b0b0-780f-50ae-a1a0-dfa443479b71', '307756a2-3f77-5c99-aab9-40ae8387aff2', '624781f2-198e-5633-a73f-cc65d6c1078e', 14, 14, 'ወይም ከንቱ በሚሆን በእንስሳ ምስል ይሠራዋል፥ በቀይ ቀለምም ይቀባዋል፤ በጣቱም ቀለም አግብቶ ቀይ ያደርገዋል። ያለበትንም ጕድለት ይሞላል።'),
  ('49fbccbc-777c-5585-a20c-153bb50ee830', '307756a2-3f77-5c99-aab9-40ae8387aff2', '624781f2-198e-5633-a73f-cc65d6c1078e', 15, 15, 'ለእርሱም የሚገባ የውቅር ቤት ይሠራል፤ በሠራለት ቦታም ያኖረዋል፥ ከግድግዳውም አስጠግቶ በብረት ይቸነክረዋል።'),
  ('1f30a7da-777a-538d-a3da-31306968da48', '307756a2-3f77-5c99-aab9-40ae8387aff2', '624781f2-198e-5633-a73f-cc65d6c1078e', 16, 16, 'ምስል ነውና፥ የሚረዳውንም ይፈልጋልና ራሱን መርዳት እንደማይችል ዐውቆ እንዳይወድቅበት ይጠነቀቃል።'),
  ('aca4dca0-4e31-5264-ae50-d95e203e956b', '307756a2-3f77-5c99-aab9-40ae8387aff2', '624781f2-198e-5633-a73f-cc65d6c1078e', 17, 17, 'ከዚህም በኋላ ስለ ገንዘቡና ስለ ሚስቱ፥ ስለ ልጆቹም ወደ እርሱ ይለምናል፤ ነፍስ ከሌለው ከጣዖቱ ጋርም ሲነጋገር አያፍርም።'),
  ('496b56c9-92b4-5c38-a66b-4261d913a6d8', '307756a2-3f77-5c99-aab9-40ae8387aff2', '624781f2-198e-5633-a73f-cc65d6c1078e', 18, 18, 'ስለ ፈውስ ወደ በሽተኛው ይለምናል፥ ስለ ሕይወትም መዋቲውን ይለምናል፥ ስለ ርዳታም መርዳት ወደማይችለው ደካማ ይማልዳል።'),
  ('e192828d-47c5-5ae4-a185-424519c9fdac', '307756a2-3f77-5c99-aab9-40ae8387aff2', '624781f2-198e-5633-a73f-cc65d6c1078e', 19, 19, 'ስለ መንገድም ነገር ይንቀሳቀስ ዘንድ ወደማይቻለውና አንዲት ርምጃን ወደማይራመደው ይለምናል። ስለ ብልጽግናና ስለ ሥራም፥ ስለ ማግኘትም፥ የእጅን ሥራም ስለ ማቅናት እጆቹ ምንም ወደማይሠሩ ይለምናል፥ ኀይልንና ሥራ ማፍጠንንም ይሰጠው ዘንድ ምንም ኀይል ከሌለው ከእርሱ ይፈልጋል።'),
  ('614baf3f-956c-5de8-a8e6-04e837097ac7', 'a0b17439-bbbe-5141-acc4-99529d9605ec', '0c3ef20a-0a7f-5e2d-a528-1c3be62e1419', 1, 1, 'ዳግመኛም ሰው በክፉ የባሕር ማዕበል መካከል ይሄድ ዘንድ ወድዶ በመርከብ ላይ በወጣ ጊዜ ከምትሸከመው ከመርከቢቱ፥ ከሚዋረደውና ከሚደክመው እንጨት ይለምናል።'),
  ('003771c7-221e-5e79-a506-811fd6ba9581', 'a0b17439-bbbe-5141-acc4-99529d9605ec', '0c3ef20a-0a7f-5e2d-a528-1c3be62e1419', 2, 2, 'ያን ጣዖት ትርፍ በመውደድ ሠርቶታልና፥ ብልህም በብልሀቱ ሠርቶታልና።'),
  ('1d3ad697-2c38-59d9-a52e-1340416c84fc', 'a0b17439-bbbe-5141-acc4-99529d9605ec', '0c3ef20a-0a7f-5e2d-a528-1c3be62e1419', 3, 3, 'አብ ሆይ፥ ያንተ አመራር ግን ሁሉን ትሠራራለች፤ በባሕር ውስጥ መንገድን፥ በሞገድም መካከል ጽኑ መተላለፊያን ሰጥተሃልና።'),
  ('d60e0b37-67ea-50e9-a0d2-52e0dfa37aa1', 'a0b17439-bbbe-5141-acc4-99529d9605ec', '0c3ef20a-0a7f-5e2d-a528-1c3be62e1419', 4, 4, 'ወደ መርከብ በማውጣት፥ ዳግመኛም ያለ ጥበብ ሰውን በባሕር ላይ በማሳለፍ በእውነት ሁሉን ማዳን እንደሚቻልህ ታሳይ ዘንድ፥'),
  ('0c071bef-dbe7-506d-a0e9-496700e693cd', 'a0b17439-bbbe-5141-acc4-99529d9605ec', '0c3ef20a-0a7f-5e2d-a528-1c3be62e1419', 5, 5, 'የጥበብህ ሥራው ስንፍና እንዳይሆን ትወዳለህ፥ ስለዚህ ሰዎች ሰውነታቸውን በተናቀና በተዋረደ እንጨት ተማምነው በታላቅና በታናሽ መርከብ በሞገዱ መካከል ተሻግረው ይድናሉ።'),
  ('8d1df563-a746-53ff-ae82-a12a1c8b6ad1', 'a0b17439-bbbe-5141-acc4-99529d9605ec', '0c3ef20a-0a7f-5e2d-a528-1c3be62e1419', 6, 6, 'ቀድሞም ትዕቢተኞች ረዓይት በጠፉ ጊዜ የዓለም ተስፋ በመርከብ ተጭኖና ተጠግቶ ዳነ፥ በእጅህም ተመርቶ የሰውን ዘርዕ ለዓለም አተረፈ።'),
  ('948bec91-3aa1-59f0-a03d-a7a6cae680c1', 'a0b17439-bbbe-5141-acc4-99529d9605ec', '0c3ef20a-0a7f-5e2d-a528-1c3be62e1419', 7, 7, 'ይህ መርከብ ጽድቅ ይሠራበት ዘንድ ተባርኳልና።'),
  ('3190a52c-1f6c-5a56-a137-2a4515fd02a3', 'a0b17439-bbbe-5141-acc4-99529d9605ec', '0c3ef20a-0a7f-5e2d-a528-1c3be62e1419', 8, 8, 'በእጅ የተሠራው ግን የሚጠፋ ሲሆን አምላክ ስለ ተባለ የተረገመ ነው፤ የሠራውም ይህን በመሥራቱ ርጉም ነው።'),
  ('52e5b1e2-1274-546b-a945-9915b5718ef3', 'a0b17439-bbbe-5141-acc4-99529d9605ec', '0c3ef20a-0a7f-5e2d-a528-1c3be62e1419', 9, 9, 'በእግዚአብሔር ዘንድ ክፉና ክፋቱ በትክክል ተጠልተዋልና፥'),
  ('73fa5757-493b-5959-aea2-7d830b727cfd', 'a0b17439-bbbe-5141-acc4-99529d9605ec', '0c3ef20a-0a7f-5e2d-a528-1c3be62e1419', 10, 10, 'የተሠራው ሥራ ከሠሪው ጋር ይፈረድበታልና።'),
  ('e928a07c-887a-58df-af5b-934f7aa7b80c', 'a0b17439-bbbe-5141-acc4-99529d9605ec', '0c3ef20a-0a7f-5e2d-a528-1c3be62e1419', 11, 11, 'ስለዚህም በአሕዛብ ጣዖታት ምርመራ ይደረጋል። ፍጥረትን ለማጥፋት ለሰዎችም ነፍሳት መሰናክል፥ ለአላዋቂዎች ሰዎች እግሮችም ወጥመድ ሆኖ ተሠርትዋልና፥'),
  ('63edd331-9fe4-55f9-a5c5-a6f179a5851f', 'a0b17439-bbbe-5141-acc4-99529d9605ec', 'f852126f-4750-5f4d-a5f1-842c5ab0b58c', 1, 12, 'የዝሙት መጀመሪያዋ ጣዖትን የመሥራት ዐሳብ ነውና፥ እርሱንም ማግኘት የሕይወት ጥፋት ነው።'),
  ('04ecd311-51fc-566e-a94d-30e85d155261', 'a0b17439-bbbe-5141-acc4-99529d9605ec', 'f852126f-4750-5f4d-a5f1-842c5ab0b58c', 2, 13, 'ከጥንት ጀምሮ አልነበረምና ለዘለዓለሙም አይኖርምና።'),
  ('abecba2d-a603-5883-a2be-fc6733c73860', 'a0b17439-bbbe-5141-acc4-99529d9605ec', 'f852126f-4750-5f4d-a5f1-842c5ab0b58c', 3, 14, 'ተነጥቀው የመሄዳቸውን ፍጻሜ የሚያፋጥን ስለሆነ በከንቱ ሰው ምክንያት ጣዖት ወደዚህ ዓለም ገባ። ከዚህም በኋላ ጣዖት መሥራትን ዐሰቡ።'),
  ('ca60dd4d-6cdb-56cd-a12e-40a04a3c8551', 'a0b17439-bbbe-5141-acc4-99529d9605ec', 'f852126f-4750-5f4d-a5f1-842c5ab0b58c', 4, 15, 'ልጁ ሕፃን ሳለ ፈጥኖ በሞት ስለ ተነጠቀ አባቱ ላንድ ልጁ ይጨነቅና ያለቅስ ነበርና፥ ቀድሞ ለሞተው ልጁ ምስል ሠራለት፥ ዛሬ ግን እንደ አምላክ አድርገው አከበሩት። ለኀጢአት የተገዙ ሰዎችም በስውር በዓል አደረጉለት፥ የምሥጢር መሥዋዕትንም ሠዉለት።'),
  ('3934a1eb-6c82-5686-a8df-88f86491360e', 'a0b17439-bbbe-5141-acc4-99529d9605ec', 'f852126f-4750-5f4d-a5f1-842c5ab0b58c', 5, 16, 'ከዚህ በኋላ በዘመን መራቅ የበደልና የዝንጋዔ ልማድ ሥርዐት ሆኖ ተያዘ፥ እንደ ሕግም አድርገው ጠበቁት፥ በክፉዎች መኳንንት ትእዛዝም ጣዖታትን አመለኳቸው።'),
  ('1c42966b-3e6a-5b3c-abc2-74296dfaf4a9', 'a0b17439-bbbe-5141-acc4-99529d9605ec', 'f852126f-4750-5f4d-a5f1-842c5ab0b58c', 6, 17, 'በሩቅ ስለሚኖሩ ፊት ለፊት ሊያከብሯቸው የማይቻላቸውን ሰዎች ቅርፁ በሩቅ ያለ መልካቸውን ቀረፁ፥ በእነርሱ ዘንድ ክቡር ለሚሆን ለንጉሡም ግልጥ የሆነ ምስል ሠሩለት። የሌለውንም እንዳለ አድርገው በትጋት ይለምናሉ።'),
  ('9b8b695a-de9b-5615-a371-bceab6cc1467', 'a0b17439-bbbe-5141-acc4-99529d9605ec', 'f852126f-4750-5f4d-a5f1-842c5ab0b58c', 7, 18, 'ስሕተታቸውንም ያላወቁ ሰዎች በአምልኮታቸው ጸኑ። የጥበበኛውንም ክብር ወደ ጣዖት አምልኮ መለሱ።'),
  ('569db7e7-3c9b-5c6c-a162-8603e86b00a6', 'a0b17439-bbbe-5141-acc4-99529d9605ec', 'f852126f-4750-5f4d-a5f1-842c5ab0b58c', 8, 19, 'ዳግመኛ ገዥውን ንጉሥ አድልቶ ደስ ያሰኘው ዘንድ የሚወድ አለ። ባማረና በተሻለ ሁኔታ ምስሉን ለመሥራት ተራቅቆአልና።'),
  ('ba71659f-bc96-5f02-a2ba-e9bb5b0aa75f', 'a0b17439-bbbe-5141-acc4-99529d9605ec', 'f852126f-4750-5f4d-a5f1-842c5ab0b58c', 9, 20, 'በሥራውም መልክ ማማር ደስ ስላላቸው ብዙ ሰዎች በዚህ ተሳቡ፥ ከጥቂት ቀን አስቀድሞ በትንሽ ክብር የነበረ ሰውንም ዛሬ እንደ አምላክ አደረጉት።'),
  ('405ecaf6-cc1f-5f9e-a925-18c10d8ab9ae', 'a0b17439-bbbe-5141-acc4-99529d9605ec', 'f852126f-4750-5f4d-a5f1-842c5ab0b58c', 10, 21, 'በችግር ወይም በግድ ሰው ሁሉ ተገዝትዋልና ይህ ለሰው መሰናክልን ሆነ፤ ከእነርሱ ጋር አንድነት የሌለውን የፈጣሪን ስም ለሚጠቀሙባቸው ለድንጋይና እንጨት አድርገውታልና።'),
  ('83f41380-55aa-530b-a536-7507a4c77dfd', 'a0b17439-bbbe-5141-acc4-99529d9605ec', '6af3fd0a-91a5-5950-aacd-1925d1ab431e', 1, 22, 'ዳግመኛም እግዚአብሔርን ካለማወቃቸው የተነሣ ስሕተታቸው አልበቃቸውም፥ ነገር ግን በታላቅ ሰልፍ ሳሉ በስንፍናቸው ይኖራሉ። ይህን ያህል ክፉ የሆነውንም ታላቅ አደረጉ፥ ሰላም ብለውም ጠሩት።'),
  ('9ebd388e-7d22-56c1-a324-7a9464bf578d', 'a0b17439-bbbe-5141-acc4-99529d9605ec', '6af3fd0a-91a5-5950-aacd-1925d1ab431e', 2, 23, 'ልጆቻቸውን የሚሠዉ አሉና፤ የተሰወረ ምሥጢርንም ያደርጋሉ፥ በልዩ ሥርዐትም እየተቅበዘበዙ ያስባሉ።'),
  ('949af850-10e6-58d0-a2e9-f42a94258729', 'a0b17439-bbbe-5141-acc4-99529d9605ec', '6af3fd0a-91a5-5950-aacd-1925d1ab431e', 3, 24, 'ሕጋቸውንና ጋብቻቸውን አልጠበቁም፤ ነገር ግን ባልንጀራ ባልንጀራውን ይገድለዋል፤ ያም ባይሆን ያባብለዋል፥ በሽተኛም ያደርገው ዘንድ ተስፋ ይሰጠዋል።'),
  ('266addf3-b2cb-5dc2-ab5c-26e07a2bbb98', 'a0b17439-bbbe-5141-acc4-99529d9605ec', '6af3fd0a-91a5-5950-aacd-1925d1ab431e', 4, 25, 'ሥራዎቻቸው ሁሉ ደም ከማፍሰስና ነፍስ ከመግደል ጋር፥ ከመስረቅም ጋር፥ ከሐሰትና ከጥፋት፥ ምስጋናንም ከማጕደል ጋር፥ ካለማመንም ጋር፥ ከመሐላና በጎውን ሰው ከማወክ ጋር፥'),
  ('163d3b78-afae-53ec-ac38-6160405084ff', 'a0b17439-bbbe-5141-acc4-99529d9605ec', '6af3fd0a-91a5-5950-aacd-1925d1ab431e', 5, 26, 'ዋጋን ካለማሰብ ጋር፥ ሰውነትን ከማስተዳደፍ ጋር፥ ፍጥረትንም ከመለወጥ ጋር፥ የጋብቻን ሥርዐት ከማፍረስ ጋር፥ ከምንዝርና ከርኵሰት ጋር፥ የተቀላቀለ ነው።'),
  ('61fc269e-0eb1-59b3-aca7-804dda265929', 'a0b17439-bbbe-5141-acc4-99529d9605ec', '6af3fd0a-91a5-5950-aacd-1925d1ab431e', 6, 27, 'ስም የሌላቸው ጣዖቶችን ማምለክ የክፋት ሁሉ መጀመሪያ ነውና፥ የፍጻሜውም ምክንያት ነውና።'),
  ('dff4eba4-d628-53b7-a17a-ff9eba34e386', 'a0b17439-bbbe-5141-acc4-99529d9605ec', '6af3fd0a-91a5-5950-aacd-1925d1ab431e', 7, 28, 'የሚያመልኳቸው ሰዎች እንደ እነዚህ ደስ ቢላቸው አእምሮአቸውን ያጣሉና። ያም ባይሆን በሐሰት ትንቢት ይናገራሉ፥ ያም ባይሆን ይሙት በቃውን ያድናሉ፥ ያም ባይሆን ፈጥነው ይምላሉ።'),
  ('b82911b9-829b-5bbf-ace0-2e43edca7b2a', 'a0b17439-bbbe-5141-acc4-99529d9605ec', '6af3fd0a-91a5-5950-aacd-1925d1ab431e', 8, 29, 'ቃልና ዕውቀት ያላቸው እነዚህ ሁሉን እንደሚያውቅ እንደ ፈጣሪ አድርገው ነፍስ የሌለው ሐሰተኛና ድዳ ጣዖትን ይታመናሉ፥ ቢምሉም እንደሚፈረድባቸው አያስቡም።'),
  ('6a7d8c9e-fd91-5c70-a3f7-3dc8854f94e6', 'a0b17439-bbbe-5141-acc4-99529d9605ec', '6af3fd0a-91a5-5950-aacd-1925d1ab431e', 9, 30, 'እውነተኛ ፍርድ በአንድነት ያገኛቸዋል፥ ጣዖቱን በተመለከቱ ጊዜ በእግዚአብሔር ክፉ ነገርን ዐስበዋልና፥ የፈጣሪን እውነት አቃልለው በግፍና በሐሰት ምለውበታልና።'),
  ('df384abf-2d37-52a8-ab74-160212d72409', 'a0b17439-bbbe-5141-acc4-99529d9605ec', '6af3fd0a-91a5-5950-aacd-1925d1ab431e', 10, 31, 'በኀጢአታቸው የተፈረደባቸውን ፍርድ ለማስተላለፍ ነው እንጂ ኀይሉን ይገልጥብናል ሲሉ የማሉ አይደለምና፤ እንግዲህ ሁልጊዜ ሰውን በሚበድሉ ሰዎች ወንጀል ላይ ፍርድ ትምጣባቸው።'),
  ('d5f19fdb-d3dd-57ba-a4e2-97623b5ff7ca', '5817dc39-fda8-52e3-ac2e-45f449751371', '812e31c6-73d7-5434-a93e-f8700f103e48', 1, 1, 'አንተ ፈጣሪያችን ግን ቸር፥ እውነተኛ፥ ታጋሽም ነህ፥ በምሕረትህም ሁሉን ትሠራለህ።'),
  ('d6fef3a1-54b0-5dbf-acc6-8cd36b43d31e', '5817dc39-fda8-52e3-ac2e-45f449751371', '812e31c6-73d7-5434-a93e-f8700f103e48', 2, 2, 'ኀይልህን እያወቅን ብንበድል፥ ያንተ መሆናችንን እያወቅንም ባንበድል ያንተ ነን።'),
  ('be7481ea-5647-5fa7-a065-28f6742c5345', '5817dc39-fda8-52e3-ac2e-45f449751371', '812e31c6-73d7-5434-a93e-f8700f103e48', 3, 3, 'አንተን ማወቅ ፍጽምት ጽድቅ ናትና፥ ኀይልህንም ማወቅ የሕይወት ሥር ናትና።'),
  ('da246cd5-ac93-5a39-a619-53f802838d98', '5817dc39-fda8-52e3-ac2e-45f449751371', '812e31c6-73d7-5434-a93e-f8700f103e48', 4, 4, 'ክፉ ዐሳብ፥ የሰው ጥበብ፥ ፍሬ የሌለው የማስጌጥ ድካም፥ ወይም ቀለም በመቀባት መልካቸው የሚለወጥ ሥራዎች አያስቱንምና።'),
  ('6d4942e9-c5d7-5797-aab2-a15a12558253', '5817dc39-fda8-52e3-ac2e-45f449751371', '812e31c6-73d7-5434-a93e-f8700f103e48', 5, 5, 'የእነዚህም መልካቸው እነርሱን ወደ መመኘት ይመጣ ዘንድ አላዋቂን ሰው ይስበዋል፤ ነፍስና መንቀሳቀስ የሌለው ምውት ጣዖትንም ያስወድደዋል።'),
  ('102dc831-0fb6-5c30-a5d4-6ba4cac36aa0', '5817dc39-fda8-52e3-ac2e-45f449751371', '812e31c6-73d7-5434-a93e-f8700f103e48', 6, 6, 'የሚሠሯቸው የሚወዷቸውና የሚያመልኳቸውም ክፋትን የሚወድዱ ናቸው። እንደዚህም የሚያደርጉ በእነርሱ ላይ ተስፋ ያደርጋሉ።'),
  ('c2d8dc21-0d66-51db-abb3-4b1e91a67236', '5817dc39-fda8-52e3-ac2e-45f449751371', '794f00d0-1b01-5601-a7c4-9ba01e3af71b', 1, 7, 'ሸክላ ሠሪ ለስላሳ አፈርን በለወሰ ጊዜ ከእኛ ለእያንዳንዱ ሁሉ ሊያገለግል የሚገባውን የተለያየ ሥራን ይሠራል፥ ነገር ግን ከዚያው ጭቃ ለንጹሕ ሥራ አገልግሎት ዕቃዎችን ይሠራል፥ እንደዚሁም ለሌሎች ሥራዎች በእነዚህ አምሳል ይሠራል፤ የእነዚህም ሁሉ ተግባር ለተለያየ መፍቅድ ነው፥ ነገር ግን ይህ ወይም ያ ለምን ጥቅም እንደሚውል ፈራጁ ዳኛ ሸክላ ሠሪው ነው።'),
  ('c3f36448-4756-5a9f-a87f-810947324dd5', '5817dc39-fda8-52e3-ac2e-45f449751371', '794f00d0-1b01-5601-a7c4-9ba01e3af71b', 2, 8, 'ለክፋት የሚደክም ሰው ግን ከዚያ ጭቃ ከንቱ ጣዖትን ይሠራል፥ ይህም ከጥቂት ቀን አስቀድሞ ከምድር ተሠራ፤ ከጥቂት ቀንም በኋላ ከእርሷ ወደ ወጣባት ምድር ይመለስ ዘንድ አለው፥ ስለ ነፍሱ ፍርድም ይመረመራል።'),
  ('5121d652-4f07-5a8a-ae0c-14abcb94f32a', '5817dc39-fda8-52e3-ac2e-45f449751371', '794f00d0-1b01-5601-a7c4-9ba01e3af71b', 3, 9, 'በእርሱም ዘንድ ያለው ትጋት ይሠራና ይደክም ዘንድ ስላለውና ሕይወቱም ጥቂት ስለሆነ አይደለም። ወርቅና ብርን የሚሠሩ ሰዎችን ይፎካከራቸው ዘንድ ነው እንጂ፤ ናስ ሠሪዎችንም ይመስላቸው ዘንድ ነው እንጂ፥ የተዋረደውንም ሠርቶ ክብር ይሰጠዋል።'),
  ('3de3bf13-f436-5509-a8ff-c3613a57a34a', '5817dc39-fda8-52e3-ac2e-45f449751371', '794f00d0-1b01-5601-a7c4-9ba01e3af71b', 4, 10, 'ልቡናው አመድ ነው፥ ተስፋውም ከአፈር ይጐሰቍላል፥ ሕይወቱም ከጭቃ እጅግ የተናቀ ነው።'),
  ('ca353e32-860f-5530-a98c-03473d2185bc', '5817dc39-fda8-52e3-ac2e-45f449751371', '794f00d0-1b01-5601-a7c4-9ba01e3af71b', 5, 11, 'የፈጠረውንና ነባቢት ነፍስን ያሳደረበትን፥ የሕይወት መንፈስንም እፍ ያለበትን አላወቀውምና።'),
  ('dd3a6a3b-613f-5a97-a111-391ebbcdeb57', '5817dc39-fda8-52e3-ac2e-45f449751371', '794f00d0-1b01-5601-a7c4-9ba01e3af71b', 6, 12, 'ነገር ግን እነዚህ ሕይወታችንን ጨዋታና መዘባበቻ አድርገው ዐሰቡ፥ ኑሯችንንም የትርፍ ምልክት አደረጉት፤ ስላጣሁ ይጨንቀኛል ብሏልና፥ ከዚህም በኋላ ያተርፋል፥ ክፋትንም ገንዘብ ያደርጋል።'),
  ('a43fd149-aa86-5796-ad6d-b261cd37fd5f', '5817dc39-fda8-52e3-ac2e-45f449751371', '794f00d0-1b01-5601-a7c4-9ba01e3af71b', 7, 13, 'ይህም ከሁሉ ፈጽሞ እንደሚበድል ታወቀ፥ በምድር ከሚታየውና ፈጥኖ ከሚጠፋው ከእንጨት የተቀረፀ ጣዖትን ሠርትዋልና።'),
  ('e75f4551-485b-5afc-a62d-e251101476da', '5817dc39-fda8-52e3-ac2e-45f449751371', '794f00d0-1b01-5601-a7c4-9ba01e3af71b', 8, 14, 'ሁሉም አላዋቂዎችና ጐስቋሎች ናቸው፥ ሁሉም ከተማረኩ ወገኖች ተለይተው ሙታን ናቸው፥ በእርሱ የታሰሩም ሰዎች ከሕፃናት ሰውነት ይልቅ ስንፍናን ያበዛሉ።'),
  ('9c0d2083-f706-5793-a77a-39021d514cdb', '5817dc39-fda8-52e3-ac2e-45f449751371', '794f00d0-1b01-5601-a7c4-9ba01e3af71b', 9, 15, 'መሥራት የማይቻላቸው፥ በዐይናቸው ማየት፥ ባፍንጫቸው ነፋስን ማሽተት፥ በጆሮአቸውም መስማት፥ በእጆቻቸው ጣቶች መዳሰስ የማይቻላቸው፥ እግሮቻቸውም ከመሄድ የቦዘኑ የአሕዛብን ጣዖቶች አማልክት አድርገው ዐስበዋልና።'),
  ('1a3243e1-8518-5927-a288-584e195c254e', '5817dc39-fda8-52e3-ac2e-45f449751371', '794f00d0-1b01-5601-a7c4-9ba01e3af71b', 10, 16, 'ሰው ሠርትዋቸዋልና፥ መንፈስ የተከፈለውም ሰው ቀርፆአቸዋልና፥ ራሱን አስመስሎ አምላክን ይሠራ ዘንድ ለሰው አይቻለውምና።'),
  ('ed9872e8-32a3-569e-a46f-e7cdbabb0c2c', '5817dc39-fda8-52e3-ac2e-45f449751371', '794f00d0-1b01-5601-a7c4-9ba01e3af71b', 11, 17, 'እርሱ መዋቲ ሲሆን በኀጢአት እጅ መዋቲን ይሠራል፥ እርሱ ሕያው ስለሆነ እነዚህ ግን ከቶ ሕያዋን ስላይደሉ ከጣዖቶቹ ይሻላልና።'),
  ('9f5cd7a9-075c-5c0f-a487-c925d49f1f9d', '5817dc39-fda8-52e3-ac2e-45f449751371', '794f00d0-1b01-5601-a7c4-9ba01e3af71b', 12, 18, 'እንስሳዎችንም አማልክት ያደረጓቸው እነዚህ በስንፍና ያመልኳቸዋል፥ እነዚህን ግን በሕሊና ቢመዝኗቸው ከሌሎች አማልክት ይከፋሉ።'),
  ('bfa0203e-51a3-5ec6-abd0-56e55a41f1c9', '5817dc39-fda8-52e3-ac2e-45f449751371', '794f00d0-1b01-5601-a7c4-9ba01e3af71b', 13, 19, 'ምኞትን የወደደም እንስሳትን በማየት ከእነርሱ በአንዱ ምኞቱን ፈጸመ፥ በአንዱም በደለ፥ የእግዚአብሔር ምስጋናና ክብር በዚህ ርቋልና።'),
  ('7e2dbf7b-feae-5cf8-a67d-ce6146eff00f', 'ea8446c2-8ec9-5d6a-a6f9-e46ce067e1c4', '0c9e3f83-83d0-5a5f-a9f1-efe927234ca3', 1, 1, 'ስለዚህም አምልኮታቸውን በሚመስል በሚገባ ተቀጡ፥ በብዙ ተናካሽ ትንኞችም ተሠቃዩ።'),
  ('901a404f-bb41-54e5-a9e1-7e9f3c9a1315', 'ea8446c2-8ec9-5d6a-a6f9-e46ce067e1c4', '0c9e3f83-83d0-5a5f-a9f1-efe927234ca3', 2, 2, 'ለሕዝብህም በጠላቶቻቸው ፊት በጎ አደረግህላቸው፥ ለፍላጎታቸውም ድርጭትን ሰጠሃቸው። ጣዕሙ ልዩ የሆነ መናንም ይበሉ ዘንድ ሰጠሃቸው።'),
  ('0ab0fd9d-1941-5839-a0f3-9495bcea559a', 'ea8446c2-8ec9-5d6a-a6f9-e46ce067e1c4', '0c9e3f83-83d0-5a5f-a9f1-efe927234ca3', 3, 3, 'እነዚያ ግን መብልን በተመኙ ጊዜ በእነርሱ ስለ ተላከባቸው ፍጥረት ከፍላጎታቸው ተመለሱ፥ የዘወትሩንም ልማድ ናቁ። እነዚህ ግን ምግብን በማጣት ጥቂት ወራት ከተቸገሩ በኋላ ጣዕሙ ልዩ ለሆነ ምግብ ተዘጋጁ።'),
  ('a0100b64-8aba-5f07-a357-c47b6e982e16', 'ea8446c2-8ec9-5d6a-a6f9-e46ce067e1c4', '0c9e3f83-83d0-5a5f-a9f1-efe927234ca3', 4, 4, 'በእነዚህ ላይ ፍርድ ያለ ርኅራኄ ይደርስ ዘንድ ግድ ነው። ክፉዎችና በኀይል የሚገዙ ናቸውና። ነገር ግን ለእነዚህ የሚገባው ጠላቶቻቸው እንዴት እንደሚሠቃዩ ያዩ ዘንድ ብቻ ነው።'),
  ('320e7b44-5de6-5c58-a84a-ec106f799794', 'ea8446c2-8ec9-5d6a-a6f9-e46ce067e1c4', '0c9e3f83-83d0-5a5f-a9f1-efe927234ca3', 5, 5, 'የክፉዎች አራዊት ቍጣ ቢመጣባቸው፥ በክፉዎች እባቦች መንደፍም ቢያልቁ፥ ለጥቂት ወራት ይቀጡ ዘንድ ታወኩ እንጂ ቍጣህ ለብዙ ጊዜ የጸናባቸው አይደለም፤'),
  ('b64d1e01-8222-56f2-a657-846da73a3370', 'ea8446c2-8ec9-5d6a-a6f9-e46ce067e1c4', '0c9e3f83-83d0-5a5f-a9f1-efe927234ca3', 6, 6, 'ይህም ምልክት የሕግህን ትእዛዝ ያሳስባቸው ዘንድ ለድኅነት ማስጠንቀቂያ ሆናቸው።'),
  ('432d80f3-9fb6-5627-a7cf-d785cc4cefc2', 'ea8446c2-8ec9-5d6a-a6f9-e46ce067e1c4', '0c9e3f83-83d0-5a5f-a9f1-efe927234ca3', 7, 7, 'ሁሉን የምታድን ሆይ፥ ከእነርሱ የተመለሰው በአንተ ዳነ እንጂ በማየት ብቻ የዳነ አይደለም።'),
  ('4d153f66-41eb-59d8-ac2c-d8320902c3fc', 'ea8446c2-8ec9-5d6a-a6f9-e46ce067e1c4', '0c9e3f83-83d0-5a5f-a9f1-efe927234ca3', 8, 8, 'በዚህም ፈተንኻቸው፥ ከክፉ ሁሉ የምታድን አንተ እንደ ሆንህም ጠላቶቻችንን አሳመንኻቸው።'),
  ('5f0228f6-d4de-595c-ac9a-be3f450a38e5', 'ea8446c2-8ec9-5d6a-a6f9-e46ce067e1c4', '0c9e3f83-83d0-5a5f-a9f1-efe927234ca3', 9, 9, 'የተቈናጣጭ ዝንብና የአንበጣ ንክሻ እነዚህን አጥፍትዋቸዋልና፤ ለነፍሳቸውም ድኅነትን አላገኙም፤ በእንደዚህ ያለ ምሳሌ ልትፈርድባቸው ይገባቸዋልና።'),
  ('bd18504d-6bb6-5430-ae12-919cc6a2f477', 'ea8446c2-8ec9-5d6a-a6f9-e46ce067e1c4', '0c9e3f83-83d0-5a5f-a9f1-efe927234ca3', 10, 10, 'በልጆችህ ግን መርዝ ያለው የእባቦች ጥርስ በታዘዘ ጊዜ አልጐዳቸውም፥ ቸርነትህ መጥቶ አድኖአቸዋልና።'),
  ('c2649784-7643-567f-aa5c-7de8569bb083', 'ea8446c2-8ec9-5d6a-a6f9-e46ce067e1c4', '0c9e3f83-83d0-5a5f-a9f1-efe927234ca3', 11, 11, 'ሕግህን ለማሰብ ይህን ቀምሰዋልና፥ በጽኑ ዝንጋዔም እንዳይወድቁ፥ ተአምራትህንም ከማሰብ ወጥተው በሌላ ሥራና መከራ እንዳይወድቁ ፈጥነው ዳኑ።'),
  ('de42f1b3-2eca-5778-a0dd-ee8d4c7c4b27', 'ea8446c2-8ec9-5d6a-a6f9-e46ce067e1c4', '0c9e3f83-83d0-5a5f-a9f1-efe927234ca3', 12, 12, 'አቤቱ፥ ሁሉን የሚያድን ቃልህ ነው እንጂ የሚጠጡት እንጨት ፥ የሚቀቡትም መድኀኒት ያዳናቸው አይደለም።'),
  ('16601d96-9298-5b15-ab08-a71edd5267ce', 'ea8446c2-8ec9-5d6a-a6f9-e46ce067e1c4', '0c9e3f83-83d0-5a5f-a9f1-efe927234ca3', 13, 13, 'በሕይወትና በሞት ላይ ሥልጣን አለህና፥ ወደ ሲኦል በሮች ታወርዳለህ፥ ከሲኦልም ታወጣለህ።'),
  ('b65ddffb-2f9c-5c11-a027-9ad4a87c668e', 'ea8446c2-8ec9-5d6a-a6f9-e46ce067e1c4', '0c9e3f83-83d0-5a5f-a9f1-efe927234ca3', 14, 14, 'ሰው ግን በክፉ ይገድላል፥ ነፍስ ከሥጋ ከተለየ በኋላ አይመለስም፥ የተለየች ነፍስም አትመለስም።'),
  ('68a15284-986e-570f-a36e-dfdae01cd05b', 'ea8446c2-8ec9-5d6a-a6f9-e46ce067e1c4', '0c9e3f83-83d0-5a5f-a9f1-efe927234ca3', 15, 15, 'ከእጅህ ግን መሸሽ አይቻልም።'),
  ('1333323b-601c-5283-a9d0-b86c691ae708', 'ea8446c2-8ec9-5d6a-a6f9-e46ce067e1c4', '0f9cf9ed-37c8-5d9b-ac84-92d223e6b01f', 1, 16, 'ዝንጉዎች እንዲክዱህ ባወቅህ ጊዜ በክንድህ ኀይል ተቀሠፉ፤ በልዩ ዝናምና በረድ፥ ያለ ምሕረትና ያለ መገታት በወረደ በሰማይ ሿሿቴ ጠፉ፥ በእሳትም አለቁ።'),
  ('0a77b60e-e9b0-5002-aa26-6696c89fb754', 'ea8446c2-8ec9-5d6a-a6f9-e46ce067e1c4', '0f9cf9ed-37c8-5d9b-ac84-92d223e6b01f', 2, 17, 'ድንቅ ሥራስ ሁሉን በሚያጠፋ በውኃ ውስጥ የእሳት ኀያል መሆንና መሠልጠን ነው። ዓለም ለጻድቃን ረዳት ነውና።'),
  ('1d8ce602-fe80-59df-a8a9-a883d04b3a4f', 'ea8446c2-8ec9-5d6a-a6f9-e46ce067e1c4', '0f9cf9ed-37c8-5d9b-ac84-92d223e6b01f', 3, 18, 'የእሳት ነበልባል በዝንጉዎች ላይ የተላኩ እንስሳትን እንዳያቃጥል ለማዳ ሆነ፥ ነገር ግን ይህን ባዩ ጊዜ በእግዚአብሔር ፍርድ እንደሚጠፉ ያውቃሉ።'),
  ('aa91afd4-790b-5e04-aa4e-44ad587cdb78', 'ea8446c2-8ec9-5d6a-a6f9-e46ce067e1c4', '0f9cf9ed-37c8-5d9b-ac84-92d223e6b01f', 4, 19, 'የዐመፀኛዋን ምድር ፍሬ ያጠፋ ዘንድ የእሳቱ ኀይል በውኃው መካከል የሚነድድበት ጊዜ ነበር።'),
  ('dfc328e2-a035-5339-a71c-086e3ea0e2eb', 'ea8446c2-8ec9-5d6a-a6f9-e46ce067e1c4', '9565d232-1bcc-5f51-a444-e53ec5ca395c', 1, 20, 'ስለ ፍሬውም ፋንታ የመላእክትን ምግብ ለሕዝብህ መገብኻቸው፥ ያለ ድካም የተዘጋጀ፥ ጣዕሙም ከሚጣፍጠው ሁሉ የሚበልጥ፥ ጣዕምንም ሁሉ የሚያስንቅ ኅብስትን ከሰማይ ላክህላቸው።'),
  ('889e39a5-cc3a-5938-ae42-c6f727f81bd9', 'ea8446c2-8ec9-5d6a-a6f9-e46ce067e1c4', '9565d232-1bcc-5f51-a444-e53ec5ca395c', 2, 21, 'የሰማያዊው መልክህ አርአያ የሚሆን መና ለልጆችህ የፍቅርህን ጣዕም ገለጠ፥ ከእርሱም ለሚበላ ጣዕሙ ይዘዋወር ነበር፥ ከምግቦችም ይልቅ ያሰበውንና የወደደውን ፍላጎቱን ለመፈጸም ያገለግለው ነበር።'),
  ('4481771c-4212-5649-a317-0a047ad196ea', 'ea8446c2-8ec9-5d6a-a6f9-e46ce067e1c4', '9565d232-1bcc-5f51-a444-e53ec5ca395c', 3, 22, 'በረድና ውርጭ ከእሳት ጋር ጸንተው ቆሙ፤ እሳቲቱ በበረዱ መካከል እየነደደች፥ በዝናሞችም መካከል ቦግ ቦግ እያለች፥ የጠላቶችን አዝመራ ፍሬ እንዳጠፋች ያውቁ ዘንድ አልቀለጡም።'),
  ('e91a1983-635e-5b69-aa23-89e16b3ccb40', 'ea8446c2-8ec9-5d6a-a6f9-e46ce067e1c4', '9565d232-1bcc-5f51-a444-e53ec5ca395c', 4, 23, 'ጻድቃንም ዳግመኛ ይህን በተመገቡ ጊዜ የራሳቸውን ምግብ ኀይል ይረሳሉ።'),
  ('91978150-aab7-5680-a084-93d786aa1d2a', 'ea8446c2-8ec9-5d6a-a6f9-e46ce067e1c4', '9565d232-1bcc-5f51-a444-e53ec5ca395c', 5, 24, 'ፈጣሪ ሆይ፥ ፍጥረቱ ሁሉ ለአንተ ያገለግላልና፥ በዐመፀኞች ላይ የሚላክ ፍርድን ታመጣለህ፥ በአንተ ወደሚታመኑም ይደርስ ዘንድ ደስታን ትሰጣለህ።'),
  ('6d438a8e-ba4b-53d7-ac09-38a98780978a', 'ea8446c2-8ec9-5d6a-a6f9-e46ce067e1c4', '9565d232-1bcc-5f51-a444-e53ec5ca395c', 6, 25, 'ስለዚህም ያንጊዜ ስጦታህ ነበረች፥ ወደ ሥራውም ሁሉ ትለዋወጥ ነበር፤ በለመኑትና በወደዱትም ምግብ ሁሉ ታገለግል ነበር።'),
  ('771485bd-a9a3-5629-a95b-4e16e95dcc05', 'ea8446c2-8ec9-5d6a-a6f9-e46ce067e1c4', '9565d232-1bcc-5f51-a444-e53ec5ca395c', 7, 26, 'አቤቱ በአንተ ያመኑ ሰዎችን ቃልህ ይጠብቃቸዋል እንጂ፥ ሰው የሚመገበው የተለያየ የዘር ፍሬ እንዳይደለ የወደድኻቸው ልጆችህ ያውቁ ዘንድ ነው።'),
  ('99b5c9f0-6668-5094-aecd-def669eb9d72', 'ea8446c2-8ec9-5d6a-a6f9-e46ce067e1c4', '9565d232-1bcc-5f51-a444-e53ec5ca395c', 8, 27, 'እሳት የማያጠፋው መና በጥቂት የፀሐይ ሙቀት ሞቆ ቀልጧልና።'),
  ('7fd4f855-68c2-5acf-aae8-ae565b047b6d', 'ea8446c2-8ec9-5d6a-a6f9-e46ce067e1c4', '9565d232-1bcc-5f51-a444-e53ec5ca395c', 9, 28, 'በፀሐይ መውጫ በኩል አንተን እናመሰግን ዘንድ፥ ወዳንተም እንለምን ዘንድ ፀሐይ ወደ እኛ እንዲመጣ ይፈለጋልና ይህ ይታወቅ ዘንድ ነው።'),
  ('d3723d96-e6b6-5495-a53b-9ccaf360d798', 'ea8446c2-8ec9-5d6a-a6f9-e46ce067e1c4', '9565d232-1bcc-5f51-a444-e53ec5ca395c', 10, 29, 'ለማያመሰግን አለኝታው እንደ ክረምት ውርጭ ይቀልጣልና፥ እንደማይረባ ርኩስ ውኃም ይፈስሳልና።'),
  ('6e8aa98b-063f-58de-a453-b529dc98153a', 'd9fc3445-ec64-563b-ae74-6fa1c7f66934', '33331465-2d74-5072-adc0-b7fe391487c4', 1, 1, 'ፍርድህ ታላቅ ነው፥ ለመናገርም ድንቅ ነው። ስለዚህም የፈጣሪ ትምህርት የሌላቸው ሰውነቶች ሳቱ።'),
  ('cf5e0fc5-320d-5670-afe6-92bbcb457dd8', 'd9fc3445-ec64-563b-ae74-6fa1c7f66934', '33331465-2d74-5072-adc0-b7fe391487c4', 2, 2, 'ኃጥኣን ቅዱስ ሕዝብን በያዙ ጊዜ፥ በተበረታቱባቸውም ጊዜ፥ ኀያላንም በረዥም የሌሊት ጨለማ በታሰሩ ጊዜ ያንጊዜ በቤታቸው ጣራ ስር ተጋዙ። ከዘለዓለማዊው አገልግሎት ሥርዐትም ሸሸተው ተገኙ።'),
  ('c53d3461-12e1-59cb-aec0-3a55fbfd7368', 'd9fc3445-ec64-563b-ae74-6fa1c7f66934', '33331465-2d74-5072-adc0-b7fe391487c4', 3, 3, 'የበደሉትንም ዐስበው በውስጡ ብርሃን በሌለበት ቤት ውስጥ ከዝንጋዔ መጋረጃ በታች ተሰወሩ፥ እጅግም እየተደነቁ በድንጋጤ ቀለጡ፥ በምትሀትም ታወኩ።'),
  ('ec0a04ff-2f36-5d93-ad92-639a39915156', 'd9fc3445-ec64-563b-ae74-6fa1c7f66934', '33331465-2d74-5072-adc0-b7fe391487c4', 4, 4, 'የያዛቸው አመንዝራ ከድንጋጤ ይጠብቃቸው ዘንድ አልቻለም፥ ነገሩ ስቅጥጥ የሚያደርግ የታላቅ ቃል ድምፅም ያውካቸው ጀመር። የክፉ ምትሀት መልክም ፊቱ ያዘነውን ሁሉ አጠፋ።'),
  ('5ac295a9-fae3-5a82-a545-7aa9666957e1', 'd9fc3445-ec64-563b-ae74-6fa1c7f66934', '33331465-2d74-5072-adc0-b7fe391487c4', 5, 5, 'የእሳቱም ብርሃን አንዲት ሰዓት እንኳ ያበራ ዘንድ አልቻለም፥ የብሩሃን ከዋክብት ብርሃንም ለዚያች ለምታስፈራዋ ሌሊት ጨለማ ያበራ ዘንድ አልቻለም።'),
  ('65840510-7471-5941-a340-585924cf615a', 'd9fc3445-ec64-563b-ae74-6fa1c7f66934', '33331465-2d74-5072-adc0-b7fe391487c4', 6, 6, 'ነገር ግን ከዚህ ከሚታየው መልክ ይልቅ ግርማው ፍጹም የሆነ፥ ከማይታዩትም መልኮች ይልቅ የከፋ ብቸኛ እሳት ድንገት ታያቸው።'),
  ('82096052-82fd-5766-a6bd-bb845e825635', 'd9fc3445-ec64-563b-ae74-6fa1c7f66934', '33331465-2d74-5072-adc0-b7fe391487c4', 7, 7, 'በሚሳደቡት ላይ የትዕቢት ዘለፋ ሊሆንባቸው የስንፍና ድካም የሆነ የሟርት ሥራን ከወርቅና ከብር አደረጉ።'),
  ('b88a41f5-3e72-5edb-afff-42d148e9acb0', 'd9fc3445-ec64-563b-ae74-6fa1c7f66934', '33331465-2d74-5072-adc0-b7fe391487c4', 8, 8, 'ከታመመች ሰውነት ሁከትንና ድንጋጤን ያስወግዱ ዘንድ ተስፋ የሰጡ እነዚህን ፍርሀት አሳመማቸው፥ ለሣቅም የተገቡ ሆኑ።'),
  ('6cb69d8c-6007-5dde-a6cb-27d04426d88d', 'd9fc3445-ec64-563b-ae74-6fa1c7f66934', '33331465-2d74-5072-adc0-b7fe391487c4', 9, 9, 'የሚያውከው ነገር ምንም ባያስፈራቸው የሚበርር ተሓዋሲ እንቅስቃሴና የእባቦች ጩኸት አባረራቸው። አስደንግጦም አሸሻቸው። ከሁሉ አቅጣጫ የሚሸሽ ነፋስንም ማየት አልተቻላቸውም።'),
  ('1e87291e-e486-565b-ae8a-f5c754f5ba7a', 'd9fc3445-ec64-563b-ae74-6fa1c7f66934', '33331465-2d74-5072-adc0-b7fe391487c4', 10, 10, 'የክፉ ሰው ሥራው የሚያስመሰክርበትና የሚያስፈርድበት ዐመፅ ነው፥ ሁልጊዜም እየታወቀውና ዕውቀት ባለው ሕሊና እየተመለከተ ክፉና ጠማማ ሥራን ይቀበላል፥ ይሠራልም።'),
  ('96e3319a-1d95-5981-abf0-5df41daa5bb6', 'd9fc3445-ec64-563b-ae74-6fa1c7f66934', '33331465-2d74-5072-adc0-b7fe391487c4', 11, 11, 'ፍርሀት ምንም አይደለም፥ ነገር ግን የፍርድ ጥርጥርን በሕሊና ያሳድራል።'),
  ('c38f0453-280f-5d26-af27-014da9c411c3', 'd9fc3445-ec64-563b-ae74-6fa1c7f66934', '33331465-2d74-5072-adc0-b7fe391487c4', 12, 12, 'ጥቂት ወይም ጐደሎ የልቡና ጥርጥር ብትኖርም ባለማወቅ ነው፥ በስንፍናም ነው፥ ለፍርድም መንገድ የምትሰጥ ናት ተብላ ትታሰባለች።'),
  ('b1dad95d-87dc-51f0-a496-9783749c4e82', 'd9fc3445-ec64-563b-ae74-6fa1c7f66934', '33331465-2d74-5072-adc0-b7fe391487c4', 13, 13, 'በእውነት ሊታገሡአት ከማይቻል ከሲኦል ጕድጓድ የወጣች ያች ሊታገሡአት የማይቻል ሌሊት እነርሱን በሸፈነቻቸው ጊዜ ያችን ቀን ተኝተው ነበር።'),
  ('23c52fac-9f26-52b4-a58a-191f099fa590', 'd9fc3445-ec64-563b-ae74-6fa1c7f66934', '33331465-2d74-5072-adc0-b7fe391487c4', 14, 14, 'የሚያስደነግጡ አጋንንት አስደንግጠዋቸዋልና፥ ምትሀትን በማሳየት የሚያሳድዱአቸው አሉ፥ የሰውነትንም ተስፋ የሚያደክም አለ፥ ያልጠበቁትና ያልተጠራጠሩት ፍርሀትና ድንጋጤም ድንገት ደረሰባቸው።'),
  ('f81bfbb5-64e9-56b9-a979-7dbc5fb3e1b5', 'd9fc3445-ec64-563b-ae74-6fa1c7f66934', '33331465-2d74-5072-adc0-b7fe391487c4', 15, 15, 'በዚያም ያለው ማንኛውም ሁሉ እንዲህ ነው፥ የወደቀም ቢሆን፥ በእግር ብረት ወይም ያለ እግር ብረት ታስሮ በእስር ቤት የሚጠበቅም ቢሆን፥'),
  ('a1b8c8a9-a1ef-55d5-aca6-4f0d7906e31b', 'd9fc3445-ec64-563b-ae74-6fa1c7f66934', '33331465-2d74-5072-adc0-b7fe391487c4', 16, 16, 'አራሽም ቢሆን፥ እረኛም ቢሆን፥ በምድረ በዳ ተቀምጦ ምድርን በማረስ የሚደክም ምንደኛም ቢሆን፦ ያገኘችውን ያችን አስጨናቂ መከራ ታግሦአልና።'),
  ('97904821-916f-54bf-aa7a-0e70f7023c3e', 'd9fc3445-ec64-563b-ae74-6fa1c7f66934', '33331465-2d74-5072-adc0-b7fe391487c4', 17, 17, 'ማኅበራቸው በአንዲት የጨለማ እግር ብረት ታስሯልና ያገኛቸው ምትሀት እንዲህ ነው፥ የሚያፏጭ ምትሀት፥ ወይም ጭፍቅ ካሉና ከሚያስጠልሉ ከዛፎች የተነሣ ድምፁ ያማረ የቅርንጫፎች ቃል ወይም ዜማቸው ያማረ የወፎች ድምፅ፥'),
  ('16df2a7c-573f-5d3f-aa73-0167bd98d1fe', 'd9fc3445-ec64-563b-ae74-6fa1c7f66934', '33331465-2d74-5072-adc0-b7fe391487c4', 18, 18, 'ወይም በኀይል የሚሄድ የውኃ ሿሿቴ ድምፅ፥ ወይም በማስፈራራት የሚገለባበጡ የዋሻዎች ድምፅ፥ ወይም የሚሮጡና ሩጫቸው የማይታይ የእንስሳት ሩጫ፥ ወይም በሚያስፈራ ቃል የሚጮኹ የአውሬዎች ጩኸት፥ ወይም ከአዕዋፍና ከአራዊት ድምፅ የተነሣ እርስ በርሳቸው ድምፅን ለዋውጠው የሚመልሱ የሚያስፈሩ የተራራዎች ድምፅ ነው። አስደንግጦም ያጠፋቸው መከራ እንዲህ ነው።'),
  ('c5956393-f244-57cf-a226-5fec36e8b694', 'd9fc3445-ec64-563b-ae74-6fa1c7f66934', '33331465-2d74-5072-adc0-b7fe391487c4', 19, 19, 'ዓለሙ ሁሉ በሚያበራ ብርሃን ይበራ ነበርና፥ ያለማቋረጥና ያለመከልከልም ሥራውን ይፈጽም ነበርና።'),
  ('ebcac25f-2abc-5162-a894-02d85f1b3389', 'd9fc3445-ec64-563b-ae74-6fa1c7f66934', '33331465-2d74-5072-adc0-b7fe391487c4', 20, 20, 'እነዚህን ግን ብቻቸውን ይወስዳቸው ዘንድ ያለው የጨለማ ምሳሌ የሆነው የሌሊት ክብደት ሰወራቸው፥ እነርሱ ራሳቸውም ለራሳቸው ከጨለማ የጸኑ ናቸው።'),
  ('80bfb6af-e0b4-5556-add6-08c1d2951b2b', '94b2c63b-5f8f-5ae5-a8e5-58d5fba7e97a', '9ba78332-ec41-5394-a45a-34c75d721792', 1, 1, 'በጻድቃንህ ዘንድ ግን ታላቅ ብርሃን ነበር፥ እነዚያ ቃላቸውን ይሰሙ ነበርና፥ መልካቸውን ግን አያዩም ነበርና።'),
  ('c1fea779-d711-5cbf-a135-858edb2f8e7c', '94b2c63b-5f8f-5ae5-a8e5-58d5fba7e97a', '9ba78332-ec41-5394-a45a-34c75d721792', 2, 2, 'እነዚያ የሚወዷቸውን ይደበድቧቸው ነበርና፤ የተበደሉትንም መከራ ስለ አጸኑባቸው እርስ በርሳቸው ይመሰጋገኑ ነበር።'),
  ('71c67c95-5628-50d2-ab80-bcf58c88ba57', '94b2c63b-5f8f-5ae5-a8e5-58d5fba7e97a', '9ba78332-ec41-5394-a45a-34c75d721792', 3, 3, 'እነዚህ ግን በተላከላቸው የማዳን ስጦታ ደስ አላቸው፥ የማይታወቅ ጎዳናንም ይመራቸው ዘንድ የእሳት ዐምድን ሰጣቸው፥ በሚወደደውም መንገድ የማያቃጥል ፀሐይን ሰጣቸው።'),
  ('5778f8a0-b514-5d7f-a4d6-1228750e119d', '94b2c63b-5f8f-5ae5-a8e5-58d5fba7e97a', '9ba78332-ec41-5394-a45a-34c75d721792', 4, 4, 'ብርሃንን ያጡ ዘንድ፥ በጨለማም ይታሰሩ ዘንድ ለእነዚያ ይገባቸዋል፤ ለዓለም ይሰጥ ዘንድ ያለው፥ የማያልፍ የሕግህ ብርሃን ያላቸው ልጆችህን አስረው አግዘዋቸዋልና።'),
  ('5b5d9826-b176-59b0-a075-968a900bda54', '94b2c63b-5f8f-5ae5-a8e5-58d5fba7e97a', 'da795000-aaf6-5024-a6cf-78a429ed4047', 1, 5, 'የጻድቃን ልጆችን ይገድሉ ዘንድ ባሰቡና በመከሩ ጊዜ፥ ለዘለፋ ሊሆንባቸው አንዱ ሕፃን ተጥሎ ዳነ። በእርሱም ብዙዎች ልጆቻቸውንና ማኅበራቸውን ሁሉ ያለ ርኅራኄ በብዙ ውኃ አጠፋህ።'),
  ('694ef1c1-6bda-508a-a7ec-ed85bf2d7ae4', '94b2c63b-5f8f-5ae5-a8e5-58d5fba7e97a', 'da795000-aaf6-5024-a6cf-78a429ed4047', 2, 6, 'የተማማሉባትን መሐላ ባወቁ ጊዜ፥ በፍቅር ያስቧት ዘንድ አባቶቻችን ያቺን ሌሊት ዐወቋት።'),
  ('33fe28f3-17ff-54cc-a5ac-c08c93178329', '94b2c63b-5f8f-5ae5-a8e5-58d5fba7e97a', 'da795000-aaf6-5024-a6cf-78a429ed4047', 3, 7, 'ለጻድቃን ሕዝብህ ደኅንነትን፥ ለተቃዋሚዎች ጠላቶችም ጥፋትን ሰጠህ።'),
  ('a5f1dcfd-c741-51a8-ae7e-eb478cf6683b', '94b2c63b-5f8f-5ae5-a8e5-58d5fba7e97a', 'da795000-aaf6-5024-a6cf-78a429ed4047', 4, 8, 'የሚቃረኑትን እንዳጠፋሃቸው፥ እንዲሁ የጠራኸንን እኛን አክብረኸናልና።'),
  ('8184c6bf-ac60-5c3f-a340-a6cd80d968cc', '94b2c63b-5f8f-5ae5-a8e5-58d5fba7e97a', 'da795000-aaf6-5024-a6cf-78a429ed4047', 5, 9, 'አገልጋዮችህ ጻድቃን ያማረ መሥዋዕትን ይሠዉ ነበረና፥ በመስማማትም የጌትነትህን ሕግ በልቡናቸው አሳድረዋልና በዚህ አምሳል ቅዱሳን መልካሙን ነገር ተቀበሉ፥ መከራውም ለሚገባቸው ነው። አባቶቻችን ግን የምስጋናውን መዝሙር በደስታ ይዘምሩ ነበር።'),
  ('16d9e164-7278-5b29-ad24-068a921e0765', '94b2c63b-5f8f-5ae5-a8e5-58d5fba7e97a', 'da795000-aaf6-5024-a6cf-78a429ed4047', 6, 10, 'ነገራቸው ሳይተባበር ከጠላቶች ልቅሶ ጩኸት ጋር ቃላቸው ይገናኝ ነበር። እናቶችም ስለ ልጆቻቸው የልቅሶውን ድምፅ ያደምጡ ነበር።'),
  ('f5fd3467-68d7-5c44-a66e-7a02229ecfc6', '94b2c63b-5f8f-5ae5-a8e5-58d5fba7e97a', 'da795000-aaf6-5024-a6cf-78a429ed4047', 7, 11, 'የባሪያውም ቅጣት ከጌታው ጋር በመቅሠፍት ተካከለ። ጭፍራውንና ንጉሡንም ይህች መከራ እኩል አገኘቻቸው።'),
  ('1d35ab05-62ca-5d49-a110-88708396dd63', '94b2c63b-5f8f-5ae5-a8e5-58d5fba7e97a', 'da795000-aaf6-5024-a6cf-78a429ed4047', 8, 12, 'ሁሉም በአንድነት በአንድ አምሳል ሞቱ፤ ቍጥር የሌላቸው የሞቱ ሰዎች በድኖችም ነበሩ። በአንዲት ሰዓት የከበረች ፍጥረታቸው ፈጽማ ስለ ጠፋች ሕያዋን የሞቱትን ሰዎች ይቀብሯቸው ዘንድ አልቻሉምና።'),
  ('20056086-f40b-5c56-ae7a-4f49367c71d7', '94b2c63b-5f8f-5ae5-a8e5-58d5fba7e97a', 'da795000-aaf6-5024-a6cf-78a429ed4047', 9, 13, 'ስለ ሟርታቸውም የመጣባቸውን መቅሠፍት ሁሉ አላወቁምና በበኸር ልጃቸው መጥፋት ሕዝቡ የእግዚአብሔር ልጆች እንደ ሆኑ ዐወቁ።'),
  ('95807859-1b60-538d-aa03-436dcc0d7d57', '94b2c63b-5f8f-5ae5-a8e5-58d5fba7e97a', 'da795000-aaf6-5024-a6cf-78a429ed4047', 10, 14, 'ፍጹም ጸጥታ ፍጥረትን ሁሉ በሸፈነ ጊዜ፥ ሌሊቷም በፍጥነቷ መካከል ሳለች፥'),
  ('5873bfbd-a422-5fb7-a723-42c9e56ab3ab', '94b2c63b-5f8f-5ae5-a8e5-58d5fba7e97a', 'da795000-aaf6-5024-a6cf-78a429ed4047', 11, 15, 'ሁሉን የሚችል ቃልህ እንደ ድል አድራጊና ጦረኛ ሆኖ፥ ከሰማያት ከዙፋንህ ውስጥ ወደ ጥፋት ምድር መካከል ወረደ።'),
  ('2b18ed8e-e275-5270-adb5-a113499b671b', '94b2c63b-5f8f-5ae5-a8e5-58d5fba7e97a', 'da795000-aaf6-5024-a6cf-78a429ed4047', 12, 16, 'አድልዎ የሌለባት ትእዛዝህንም እንደ ተሳለ ሰይፍ ታጥቆ፥ በመካከላቸውም ቆሞ አውራጃዎቻቸውን ሁሉ በሞት ሞላ፥ ሰማይንም ነካ፤ በምድርም ቁሞ ነበር።'),
  ('e8b89026-87ae-517d-a3a5-31d755e6189f', '94b2c63b-5f8f-5ae5-a8e5-58d5fba7e97a', 'da795000-aaf6-5024-a6cf-78a429ed4047', 13, 17, 'ያንጊዜም በአስፈሪዎች ሕልሞች ምትሀት አወካቸው፥ ያላሳቧት ድንጋጤም በላያቸው ሠለጠነችባቸው።'),
  ('d46574ac-5b5f-5d79-a298-2483d445bc0e', '94b2c63b-5f8f-5ae5-a8e5-58d5fba7e97a', 'da795000-aaf6-5024-a6cf-78a429ed4047', 14, 18, 'ከእነርሱም እኩሌታው የሞተ ሆኖ በሌላ ቦታ የሚወድቅ ነበረ፥ የሚሞቱባትንም ምክንያት ገለጠላቸው።'),
  ('5b28b0b5-a4f8-5221-ae9a-f089ce053137', '94b2c63b-5f8f-5ae5-a8e5-58d5fba7e97a', 'da795000-aaf6-5024-a6cf-78a429ed4047', 15, 19, 'ክፉ ነገር ስለምን እንደሚያገኛቸውና እንደሚያጠፋቸውም ባለማወቅ እንዳይሆኑ ያወኳቸው ሕልሞች አስቀድመው ይህን ነግረዋቸዋልና።'),
  ('21bdeb8f-5a2e-56f4-a5c5-722375a9d4a5', '94b2c63b-5f8f-5ae5-a8e5-58d5fba7e97a', '4b6cda63-1a86-5b29-aade-601a6e92f38d', 1, 20, 'ከጻድቃንም አስቀድሞ ለሞት የሚያበቃ መከራ ያገኛቸው አሉ። በምድረ በዳም መቅሠፍት ሆነ፥ ከእነርሱም ብዙዎችን አጠፋ። ነገር ግን መቅሠፍቱ ብዙ ዘመን አልዘገየም።'),
  ('bc374267-8fde-544d-af0a-edc7582df94a', '94b2c63b-5f8f-5ae5-a8e5-58d5fba7e97a', '4b6cda63-1a86-5b29-aade-601a6e92f38d', 2, 21, 'ነውር የሌለበት ሰው ጸሎት የሚጸልይበትን፥ ዕጣንም የሚያጥንበትን የአገልግሎት መሣሪያ፥ ልብሰ መትከፉን ይዞ ፈጥኖ ተዋግቶአልና ኀጢአታቸውን ለማቃለል ባለሟልነትን አገኘ፤ መዓቱን ተቃወመ፥ መቅሠፍቱንም ጸጥ አደረገ። በዚህም ያንተ መልእክተኛ እንደ ሆነ ራሱን አስታወቀ።'),
  ('2b1ac69a-dd1b-5ee1-a11e-5dafb49d8330', '94b2c63b-5f8f-5ae5-a8e5-58d5fba7e97a', '4b6cda63-1a86-5b29-aade-601a6e92f38d', 3, 22, 'አጥፊዎችንም አሸነፈ፤ በሥጋዊ ኀይል ወይም በጦር መሣሪያ አይደለም፤ ነገር ግን የአባቶችን መሐላና ቃል ኪዳናቸውን በማሰብ ቀሣፊውን በቃልህ አስወገደ።'),
  ('e803d1e4-87f3-55bf-ac97-e5ec558218bc', '94b2c63b-5f8f-5ae5-a8e5-58d5fba7e97a', '4b6cda63-1a86-5b29-aade-601a6e92f38d', 4, 23, 'ብዛታቸው የማይቈጠር የሞቱ ሰዎች እርስ በርሳቸው በወደቁ ጊዜ በበሽተኞቹና በሕያዋኖቹ መካከል ቁሞ መቅሠፍቱን ጸጥ አደረገ። ለሕያዋንም መንገድን ለየ።'),
  ('1724fee7-dea8-5544-afe8-4e1c8743aa9d', '94b2c63b-5f8f-5ae5-a8e5-58d5fba7e97a', '4b6cda63-1a86-5b29-aade-601a6e92f38d', 5, 24, 'የዓለሙ ክህነት ሁሉ በልብሱ ጫፍ ላይ ነበርና፥ ባሕርይ በሚባሉ ዕንቍዎች አራት ዙሪያዎች የተቀረጸው የአበውም ክብር በጫንቃው ላይ ነበርና፥ የአንተም ልዕልና በራሱ አክሊል ላይ ነበርና።'),
  ('4820ba83-0684-53ea-a793-ddb4893c53d8', '94b2c63b-5f8f-5ae5-a8e5-58d5fba7e97a', '4b6cda63-1a86-5b29-aade-601a6e92f38d', 6, 25, 'በዚህም የሚያጠፉ ቸነፈሮች ራቁ፥ እነዚህ ሥራዎችም አስፈሯቸው፥ ነገር ግን መቅሠፍቱ ብቻ በበቃ ነበር።'),
  ('a56294fe-b917-5217-a39b-5cffc63722e2', 'b2a73392-cefa-59ba-ae40-ab95f72f5b11', '431c0d31-a274-56d2-ab53-207e2f9c8ac3', 1, 1, 'በዝንጉዎች ላይ ግን ያለ ርኅራኄ ፈጽማ እስክትጨርሳቸው ድረስ መዓትህ ጸናች። የሚደረግ ሥራቸውን አስቀድመው ዐውቀዋልና።'),
  ('352a0cb4-2015-5b88-a60a-a2dd30dfd452', 'b2a73392-cefa-59ba-ae40-ab95f72f5b11', '431c0d31-a274-56d2-ab53-207e2f9c8ac3', 2, 2, 'እነዚያ ከመሄድ መልሰዋቸዋልና፥ ዳግመኛም በብዙ ችኮላ ሰድደዋቸዋልና፥ በተጸጸቱም ጊዜ በሩጫ ገሠገሡ፥ በፊታቸውም ማዕበል አለ ብለው ተከተሏቸው።'),
  ('e8b4c68b-d1c6-5683-a726-4056b9d49da5', 'b2a73392-cefa-59ba-ae40-ab95f72f5b11', '431c0d31-a274-56d2-ab53-207e2f9c8ac3', 3, 3, 'ገና በልቅሶ ሳሉ፥ በመቃብሮቻቸውም ላይ ሲጮኹ ልዩ የስንፍና ዐሳብ ስቧቸዋልና፥ ከእነርሱ ይሄዱ ዘንድ ማልደው ያስወጧቸውን እንደ ኰበለሉ ሰዎች ይከተሏቸው ዘንድ በሩጫ ገሠገሡ።'),
  ('e4d4398d-7190-5a1a-af04-eead5fb947b9', 'b2a73392-cefa-59ba-ae40-ab95f72f5b11', '431c0d31-a274-56d2-ab53-207e2f9c8ac3', 4, 4, 'የተገቧት የመከራ መጨረሻ ወደዚህ ሥራ ሳበቻቸው፤ ዝንጋዔም አሳታቸው፥ የጐደለውንም ፍርድ በፍርዶች ቍጥር ይፈጽሙና ይሞሉ ዘንድ ያገኛቸውን መከራ አላሰቡም።'),
  ('f1fccf9b-27ac-5aa0-aa95-3655e7b9393b', 'b2a73392-cefa-59ba-ae40-ab95f72f5b11', '431c0d31-a274-56d2-ab53-207e2f9c8ac3', 5, 5, 'ወገኖችህ ግን ድንቅ መንገድን ሄዱ፥ እነዚያም ክፉ ሞትን አገኙ።'),
  ('2171fce4-7d4d-5422-a87b-54475afa5c74', 'b2a73392-cefa-59ba-ae40-ab95f72f5b11', '4aed49ad-c2f1-596e-a414-a254d57d77d8', 1, 6, 'ፍጥረት ሁላ ከወገኖችዋ ጋር በእነርሱ ላይ ተለወጠች፤ ዳግመኛ ልጆችህ ያለ ክፋት በደኅና ይጠበቁባት ዘንድ የታዘዘችበትን ትእዛዝ እያገለገለች ተለወጠች።'),
  ('0bee40c1-3cc5-5a07-ab4e-ff249972617d', 'b2a73392-cefa-59ba-ae40-ab95f72f5b11', '4aed49ad-c2f1-596e-a414-a254d57d77d8', 2, 7, 'ደመና ሰፈሩን ጋረደች፥ ውኃዋም ከቀድሞዋ ይልቅ የረጋች ሆና ታየች፥ የደረቀችውም ምድር የለመለመች መስክ ሆና ታየች፥ በኤርትራ ባሕር መካከልም መሰናክል የሌለው መንገድ ታየ።'),
  ('d071c631-1d22-5f43-a552-9ffbd2f66393', 'b2a73392-cefa-59ba-ae40-ab95f72f5b11', '4aed49ad-c2f1-596e-a414-a254d57d77d8', 3, 8, 'በከበረች እጅህና ከፍ ባለች ክንድህ ተጋርደው፥ ወገኖችህ ሁሉ ባለፉበት ኀይለኛ ማዕበል መካከልም የለመለመ መስክ ታየ፤ ድንቅ ሥራህንም ባዩ ጊዜ ይህችን እጅህን አመሰገኑ።'),
  ('872b6648-f8a9-5100-a85f-98d3447063e6', 'b2a73392-cefa-59ba-ae40-ab95f72f5b11', '4aed49ad-c2f1-596e-a414-a254d57d77d8', 4, 9, 'አቤቱ፥ ያዳንሃቸው እነርሱ አንተን እያመሰገኑ እንደ ፈረሶች ተሰማሩ፥ እንደ ወይፈኖችም ዘለሉ።'),
  ('80b28a07-4494-563b-a98f-0ad7be11b199', 'b2a73392-cefa-59ba-ae40-ab95f72f5b11', '4aed49ad-c2f1-596e-a414-a254d57d77d8', 5, 10, 'በባዕድ ሀገር በእንግድነት በነበሩ ጊዜ ያደረጉትን ሁሉ ዐስበዋልና፤ ምድራቸው እንስሳትን በማስገኘት ፋንታ ተቈናጣጭ ዝንብን እንዴት አወጣች? ባሕርስ በብዙው ውኃ ውስጥ በነበረው ዓሣ ፋንታ ጓጕንቸርን እንዴት አስገኘች?'),
  ('205d50d3-4431-52e4-a69c-5ea32be85a03', 'b2a73392-cefa-59ba-ae40-ab95f72f5b11', '4aed49ad-c2f1-596e-a414-a254d57d77d8', 6, 11, 'ከዚህም በኋላ መናውን በመገብሃቸው ጊዜ፥ አዲስ የአዕዋፍ ፍጥረትን አዩ፥ የተድላና የደስታ ምግብን በተመኙና በለመኑ ጊዜም፥ ብዙ ፍላጎታቸውን ለማርካት ከባሕር ውስጥ ብዙ ድርጭት ወጣላቸው።'),
  ('6b3a9bd7-3c90-5305-af45-16daab14c469', 'b2a73392-cefa-59ba-ae40-ab95f72f5b11', '4aed49ad-c2f1-596e-a414-a254d57d77d8', 7, 12, 'ከመብረቆች ያልራቀች ቀድሞ በተአምር በተደረገው የመቅሠፍት ኀይል የምትመሰል መቅሠፍት በኃጥኣን ላይ መጣች፥ እነርሱ እንደ ክፋታቸው ሚዛን በእውነት ተፈርዶባቸዋልና።'),
  ('8956099e-e072-5aca-a780-383c4f90b8d6', 'b2a73392-cefa-59ba-ae40-ab95f72f5b11', '4aed49ad-c2f1-596e-a414-a254d57d77d8', 8, 13, 'እንግዶችን ስለ መቀበል እጅግ የተጠላ ጠባይን ወድደዋልና፥ እነዚህ የማያውቋቸው በደረሱ ጊዜ አልተቀበሉአቸውም፤ እነዚያ ግን መልካም እያደረጉ ሲጠቅሙአቸው በእነርሱ ዘንድ በእንግድነት የኖሩትን አስጨንቀው ገዙአቸው።'),
  ('61f1922d-1a2f-583f-a8b1-2c71f52c7f85', 'b2a73392-cefa-59ba-ae40-ab95f72f5b11', '4aed49ad-c2f1-596e-a414-a254d57d77d8', 9, 14, 'በዚህም ብቻ አይደለም፥ ነገር ግን ለሥራቸው መጐብኛና መመርመሪያ ይሆን ዘንድ ነው፥ በእነርሱ ዘንድ እንግዳ የሆኑትን በጭንቅ ይቀበሏቸው ነበርና።'),
  ('4b655900-17e4-5c89-ac6c-d22afd8ac1b2', 'b2a73392-cefa-59ba-ae40-ab95f72f5b11', '4aed49ad-c2f1-596e-a414-a254d57d77d8', 10, 15, 'እነዚህ ግን በዓል በማድረግ የተቀበሏቸውንና ከእነርሱ የአንድ ሕግ ተካፋዮች ያደረጓቸውን ጻድቃን በጭንቅ መከራ አጸኑባቸው።'),
  ('474657fb-f4fa-5663-a70a-88d8555ba68c', 'b2a73392-cefa-59ba-ae40-ab95f72f5b11', '4aed49ad-c2f1-596e-a414-a254d57d77d8', 11, 16, 'ስለዚህ በጻድቃን ደጃፍ እንደ ተሰበሰቡ እንደ እነዚያ ሰዎች ብርሃንን በማጣት ተቀጡ፥ ድንገት በጥልቅ ጨለማ ተግዘዋልና፥ ከእነርሱም እያንዳንዱ የቤቱን የደጃፉን መግቢያ መንገድ ይፈልግ ነበር።'),
  ('774d20d4-0516-5026-a82f-23d64efededd', 'b2a73392-cefa-59ba-ae40-ab95f72f5b11', '4aed49ad-c2f1-596e-a414-a254d57d77d8', 12, 17, 'ብርሃናት ከባሕርያቸው ተለውጠውባቸው ነበርና፤ የዜማውን ነገር በማወቅ የበገናው ስም እንደሚለወጥ፥ የቀናም ሆኖ በዜማው ጸንቶ እንደሚኖር በየወገናቸው የተፈጠሩትን በማየት ፈጽሞ የሚሰፈር ሥራም፥ እንዲሁ ነው።'),
  ('1e51cfcc-927c-5a9d-a83e-f5e5b85d8756', 'b2a73392-cefa-59ba-ae40-ab95f72f5b11', '3aafc5d5-b6b1-530d-aaec-a2483288afd3', 1, 18, 'በደረቅ ያሉ ፍጥረቶች ወደ ውኃ ተመልሰዋልና፥ በውኃ የሚንቀሳቀሱና የሚዋኙ ፍጥረታትም ኑሮአቸው ወደ የብስተመልሷልና።'),
  ('41043d8c-a110-572f-a64b-561ca5ad340e', 'b2a73392-cefa-59ba-ae40-ab95f72f5b11', '3aafc5d5-b6b1-530d-aaec-a2483288afd3', 2, 19, 'እሳቱም በውኃው ውስጥ ፈጽሞ በረታ፥ ውኃውም የባሕርዩን ተፈጥሮ ሰወረ።'),
  ('09209b9c-1845-5f50-a0ef-658a974eb451', 'b2a73392-cefa-59ba-ae40-ab95f72f5b11', '3aafc5d5-b6b1-530d-aaec-a2483288afd3', 3, 20, 'ፈጥኖ የሚጠፋ የእሳቱም ነበልባል ሥራው ባይደለ በመካከላቸው ወዲያና ወዲህ እያለና እየተመላለሰ የከብቶችን ሥጋ አላቃጠለም። የማይጠፋ የፍጥረታት ወገን እሳትም ፈጥኖ የሚቀልጥ ውርጭን አላቀለጠውም። አቤቱ፥ በሥራው ሁሉ የወገኖችህን ክብር ፈጽመህ አብዝተሃልና። በሁሉም አክብረሃቸዋልና ወደ እኛም በመጣው ነገር ሁሉ ቸርነትህን አላራቅህብንም፥ እኛንም በየጊዜው ቸል አላልኸንም፥ በየቦታውም ሁሉ በዚያ አንተ ትኖራለህ።'),
  ('42f46c9a-3e69-5895-ad87-e1edb8fb0060', 'e560035e-ff1b-5c02-a095-cdf1db917f4c', 'dd17b89f-5a4c-5d15-a2f9-831ec3072984', 1, 1, 'በኢየሩሳሌም ለእስራኤል የነገሠ የዳዊት ልጅ የሰባኪው የሰሎሞን ቃል።'),
  ('9b6b8d14-89f4-5a50-a20c-bda0cab97de0', 'e560035e-ff1b-5c02-a095-cdf1db917f4c', 'dd17b89f-5a4c-5d15-a2f9-831ec3072984', 2, 2, 'ሰባኪው፥ “ከንቱ፥ ከንቱ፥ የከንቱ ከንቱ ሁሉ ከንቱ ነው” ይላል።'),
  ('c151ada4-fa25-5121-a530-e4112ae55409', 'e560035e-ff1b-5c02-a095-cdf1db917f4c', 'dd17b89f-5a4c-5d15-a2f9-831ec3072984', 3, 3, 'ከፀሐይ በታች በሚደክምበት ድካም ሁሉ የሰው ትርፉ ምንድን ነው?'),
  ('3a518cba-fc0b-5dbe-aa89-cfbbfd94515b', 'e560035e-ff1b-5c02-a095-cdf1db917f4c', 'dd17b89f-5a4c-5d15-a2f9-831ec3072984', 4, 4, 'ትውልድ ያልፋል፥ ትውልድም ይመጣል፤ ምድር ግን ለዘለዓለም ጸንታ ትኖራለች።'),
  ('f78b2858-c802-52f7-ad35-5e438f50abcb', 'e560035e-ff1b-5c02-a095-cdf1db917f4c', 'dd17b89f-5a4c-5d15-a2f9-831ec3072984', 5, 5, 'ፀሐይ ይወጣል፥ ፀሐይም ይገባል፥ ወደሚወጣበትም ስፍራ ይመለሳል፤'),
  ('b30de48f-7d74-5423-a628-e66b8c9af0f6', 'e560035e-ff1b-5c02-a095-cdf1db917f4c', 'dd17b89f-5a4c-5d15-a2f9-831ec3072984', 6, 6, 'ወደ ቀኝ ይመለሳል፥ ወደ ሰሜንም ይዞራል፤ ነፋስ ዙሪያዉን ዙሮ ይሄዳል፥ ነፋስም በዙረቱ ይመለሳል።'),
  ('294efa04-c51e-5ef2-a237-c827abbff8d2', 'e560035e-ff1b-5c02-a095-cdf1db917f4c', 'dd17b89f-5a4c-5d15-a2f9-831ec3072984', 7, 7, 'ፈሳሾች ሁሉ ወደ ባሕር ይሄዳሉ፥ ባሕሩ ግን አይሞላም፤ ፈሳሾች ወደሚሄዱበት ስፍራ እንደ ገና ወደዚያ ይመለሳሉ።'),
  ('6dc34178-7cf3-59b5-a550-562788f2b60a', 'e560035e-ff1b-5c02-a095-cdf1db917f4c', 'dd17b89f-5a4c-5d15-a2f9-831ec3072984', 8, 8, 'ነገር ሁሉ ያደክማል፤ ሰውም ይናገረው ዘንድ አይችልም፥ ዐይን በማየት አይጠግብም፥ ጆሮም በመስማት አይሞላም።'),
  ('7a99647b-4cf4-5adf-a7d9-72791600a8d9', 'e560035e-ff1b-5c02-a095-cdf1db917f4c', 'dd17b89f-5a4c-5d15-a2f9-831ec3072984', 9, 9, 'የሆነው ነገር እርሱ የሚሆን ነው፥ የተደረገውም ነገር እርሱ የሚደረግ ነው፥ ከፀሐይም በታች ከተደረገው ሁሉ አዲስ ነገር የለም።'),
  ('a0e577a1-8566-59f0-ab71-3adf7c53121e', 'e560035e-ff1b-5c02-a095-cdf1db917f4c', 'dd17b89f-5a4c-5d15-a2f9-831ec3072984', 10, 10, 'እነሆ፥ “ይህ ነገር አዲስ ነው” ብሎ የሚናገር ማን ነው? እርሱ ከእኛ በፊት በነበሩት ዘመናት ተደርጓል።'),
  ('8524e527-82fe-5fb5-a5d5-105ec25df69d', 'e560035e-ff1b-5c02-a095-cdf1db917f4c', 'dd17b89f-5a4c-5d15-a2f9-831ec3072984', 11, 11, 'ለፊተኞቹ ነገሮች መታሰቢያ የላቸውም፤ ለኋለኞቹም ነገሮች ከእነርሱ በኋላ በሚነሡት ሰዎች ዘንድ መታሰቢያ አይገኝላቸውም።'),
  ('0af4a8f6-fca4-576e-a020-eaa5fd12f343', 'e560035e-ff1b-5c02-a095-cdf1db917f4c', 'dd17b89f-5a4c-5d15-a2f9-831ec3072984', 12, 12, 'እኔ ሰባኪው በእስራኤል ላይ በኢየሩሳሌም ንጉሥ ነበርሁ።'),
  ('d85b31fd-8eb4-52af-aaa6-5ab9b4f97924', 'e560035e-ff1b-5c02-a095-cdf1db917f4c', 'dd17b89f-5a4c-5d15-a2f9-831ec3072984', 13, 13, 'ከሰማይም በታች ስለተደረገው ሁሉ በጥበብ ለመመርመርና ለመፈተን ልቤን አተጋሁ፤ እግዚአብሔር ይደክሙበት ዘንድ ክፉ ድካምን ለሰው ልጆች ሰጥትዋልና።'),
  ('74497704-367b-5195-a525-80f2be6adb63', 'e560035e-ff1b-5c02-a095-cdf1db917f4c', 'dd17b89f-5a4c-5d15-a2f9-831ec3072984', 14, 14, 'ከፀሐይ በታች የተሠራውን ሥራ ሁሉ አየሁ፤ እነሆም፥ ሁሉ ከንቱ ነው፥ ነፋስንም እንደ መከተል ነው።'),
  ('0bd83c7f-1015-5536-afe2-c416608a7c86', 'e560035e-ff1b-5c02-a095-cdf1db917f4c', 'dd17b89f-5a4c-5d15-a2f9-831ec3072984', 15, 15, 'ጠማማ ይቀና ዘንድ አይችልም፤ ጐደሎም ይቈጠር ዘንድአይችልም።'),
  ('988e0fe6-a33d-5bdc-ab26-8df2c3a8f19f', 'e560035e-ff1b-5c02-a095-cdf1db917f4c', 'dd17b89f-5a4c-5d15-a2f9-831ec3072984', 16, 16, 'እኔ በልቤ፥ “እነሆ፥ ከእኔ አስቀድመው በኢየሩሳሌም ላይ ከነበሩት ሁሉ ይልቅ ጥበብን አበዛሁ፤ ልቤንም ለጥበብና ለዕውቀት ሰጠሁ፥” በማለት ተናገርሁ።'),
  ('3485ea51-024d-5e5c-ab78-fef3c3623c16', 'e560035e-ff1b-5c02-a095-cdf1db917f4c', 'dd17b89f-5a4c-5d15-a2f9-831ec3072984', 17, 17, 'ልቤም ብዙ ጥበብንና አእምሮን፥ ምሳሌንና ማስተዋልን ተመለከተች። ይህም ነፋስን መከተል እንደ ሆነ አስተዋልሁ።'),
  ('24565759-d088-5a03-a169-c5027a3c3d26', 'e560035e-ff1b-5c02-a095-cdf1db917f4c', 'dd17b89f-5a4c-5d15-a2f9-831ec3072984', 18, 18, 'በጥበብ መብዛት ትካዜ ይበዛልና፤ ዕውቀትንም የሚያበዛ መከራን ያበዛልና።'),
  ('045138ac-1b65-5638-a36d-c9680fb134aa', '9cc34e62-cdcc-5a4e-a582-f7dfc83eb777', '47f3fcf7-1afa-5973-abc5-d8954b282d9e', 1, 1, 'እኔ በልቤ፥ “ና በደስታም እፈትንሃለሁ፥ እነሆ፥ መልካምንም እይ” አልሁ፤ ይህም እነሆ፥ ከንቱ ነበረ።'),
  ('71ca6842-6c01-59e0-aa75-9c042859b56e', '9cc34e62-cdcc-5a4e-a582-f7dfc83eb777', '47f3fcf7-1afa-5973-abc5-d8954b282d9e', 2, 2, 'ሣቅን፥ “ሽንገላ ነህ፤ ደስታንም፦ ምን ታደርጋለህ?” አልሁት።'),
  ('ddea7e7e-c2c6-553d-a85f-5abd45f016a1', '9cc34e62-cdcc-5a4e-a582-f7dfc83eb777', '47f3fcf7-1afa-5973-abc5-d8954b282d9e', 3, 3, 'የሰው ልጆች በሕይወታቸው ዘመን ሁሉ ከፀሐይ በታች የሚሠሩት መልካም ነገር ምን እንደ ሆነ እስካይ ድረስ ልቤ በጥበብ እየመራኝ፥ ሰውነቴን በወይን ደስ ለማሰኘት፥ ስንፍናንም ለመያዝ በልቤ መረመርሁ።'),
  ('95a7bb28-663d-5ce9-ac06-9ffcdd180334', '9cc34e62-cdcc-5a4e-a582-f7dfc83eb777', '47f3fcf7-1afa-5973-abc5-d8954b282d9e', 4, 4, 'እኔ ሥራዬን አበዛሁ፥ ቤቶችንም ለእኔ ሠራሁ፥ ወይንም ተከልሁ።'),
  ('b1bd56ef-8bfc-5659-a28d-bdb84e2d5da9', '9cc34e62-cdcc-5a4e-a582-f7dfc83eb777', '47f3fcf7-1afa-5973-abc5-d8954b282d9e', 5, 5, 'የወይንና የአትክልት ቦታን አደረግሁ፥ ወይንና ልዩ ልዩ ፍሬ ያለባቸውንም ዛፎች ተከልሁባቸው።'),
  ('ca252455-8fe2-5c65-a7cd-04609423fcc8', '9cc34e62-cdcc-5a4e-a582-f7dfc83eb777', '47f3fcf7-1afa-5973-abc5-d8954b282d9e', 6, 6, 'የሚያፈራ እንጨትንና የተተከሉትን ዛፎች አጠጣበት ዘንድ የውኃ ማጠራቀሚያን አደረግሁ።'),
  ('b37fd319-46fe-5b55-ade5-bc52a90a142a', '9cc34e62-cdcc-5a4e-a582-f7dfc83eb777', '47f3fcf7-1afa-5973-abc5-d8954b282d9e', 7, 7, 'ወንዶችና ሴቶች አገልጋዮችን ገዛሁ፤ በቤት የተወለዱ አገልጋዮችም ነበሩኝ፤ ከእኔ አስቀድመው በኢየሩሳሌም ከነበሩት ሁሉ ይልቅ ብዙ የበጎችና የከብቶች መንጋዎች ነበሩኝ።'),
  ('7eeb84fb-ba51-5782-a0cf-fc4e5dfdb5c6', '9cc34e62-cdcc-5a4e-a582-f7dfc83eb777', '47f3fcf7-1afa-5973-abc5-d8954b282d9e', 8, 8, 'ብርንና ወርቅን፥ የከበረውንም የነገሥታትንና የአውራጆችን መዝገብ ለራሴ ሰበሰብሁ፤ ሴቶችና ወንዶች አዝማሪዎችን፥ የሰዎች ልጆችንም ተድላ አደረግሁ፤ የወይን ጠጅ ጠማቂዎችንና አሳላፊዎችንም አበዛሁ።'),
  ('2eb5f932-564e-57fa-ae34-7eb76f851957', '9cc34e62-cdcc-5a4e-a582-f7dfc83eb777', '47f3fcf7-1afa-5973-abc5-d8954b282d9e', 9, 9, 'ከእኔም አስቀድመው በኢየሩሳሌም ከነበሩት ሁሉ ይልቅ ከበርሁ፥ ታላቅም ሆንሁ። ጥበቤም ከእኔ ጋር ጸናችልኝ።'),
  ('57734a44-c35b-55a1-a6a4-f323239c806d', '9cc34e62-cdcc-5a4e-a582-f7dfc83eb777', '47f3fcf7-1afa-5973-abc5-d8954b282d9e', 10, 10, 'ዐይኖቼ ከፈለጉት ሁሉ አላጣሁም፥ ልቤንም ከደስታ ሁሉ አልከለከልሁትም፤ ልቤ በድካሜ ሁሉ ደስ ይለው ነበርና፤ ከድካሜም ሁሉ ይህ ዕድል ፋንታዬ ሆነ።'),
  ('95e77975-cb56-59c4-a228-bf6cff3ff7a4', '9cc34e62-cdcc-5a4e-a582-f7dfc83eb777', '47f3fcf7-1afa-5973-abc5-d8954b282d9e', 11, 11, 'እጄ የሠራቻትን ሥራዬን ሁሉ፥ የደከምሁበትንም ድካሜን ሁሉ ተመለከትሁ፤ እነሆ፥ ሁሉ ከንቱ፥ ነፋስንም እንደ መከተል ነበረ፥ ከፀሐይ በታችም ትርፍ አልነበረም።'),
  ('4983bb58-f1f6-56dd-abe9-aa27a49264ed', '9cc34e62-cdcc-5a4e-a582-f7dfc83eb777', '47f3fcf7-1afa-5973-abc5-d8954b282d9e', 12, 12, 'እኔም ጥበብን፥ ሽንገላንና ስንፍናን አይ ዘንድ ተመለከትሁ ፥ ምክርን የሚከተል፥ ምሳሌንስ ሁሉ የሚያደርግላት ሰው ማን ነው?'),
  ('ae10e178-fcbe-577b-a8a4-f549eeb3b1b6', '9cc34e62-cdcc-5a4e-a582-f7dfc83eb777', '47f3fcf7-1afa-5973-abc5-d8954b282d9e', 13, 13, 'እኔም ብርሃን ከጨለማ እንደሚበልጥ እንዲሁ ከአላዋቂ ይልቅ ለብልህ ብልጫ እንዳለው ተመለከትሁ።'),
  ('66148954-1dc7-565a-a371-2d764b28e389', '9cc34e62-cdcc-5a4e-a582-f7dfc83eb777', '47f3fcf7-1afa-5973-abc5-d8954b282d9e', 14, 14, 'የጠቢብ ዐይኖች በራሱ ላይ ናቸውና፤ አላዋቂ ግን በጨለማ ይሄዳል፤ ደግሞ የሁለቱም መጨረሻቸው አንድ እንደ ሆነ አስተዋልሁ።'),
  ('4598ebfd-aa36-5f86-ae53-cb500578d124', '9cc34e62-cdcc-5a4e-a582-f7dfc83eb777', '47f3fcf7-1afa-5973-abc5-d8954b282d9e', 15, 15, 'እኔም በልቤ፥ “አላዋቂን የሚያገኘው እንዲሁ እኔንም ያገኘኛል፤ እኔም ለምን እጅግ ጠቢብ ሆንሁ?” አልሁ፤ የዚያን ጊዜም በልቤ፥ “ይህ ደግሞ ከንቱ ነው” አልሁ፥ አላዋቂ በከንቱ መናገርን ያበዛልና።'),
  ('5b7912c9-ffda-5969-a0ae-3bb2f3f6c7d4', '9cc34e62-cdcc-5a4e-a582-f7dfc83eb777', '47f3fcf7-1afa-5973-abc5-d8954b282d9e', 16, 16, 'ለብልህ ከአላዋቂ ጋር ለዘለዓለም መታሰቢያ የለውም፤ እነሆ፥ ዘመን ይመጣልና ሁሉም ይረሳል፤ ብልህስ ከአላዋቂ ጋር እንዴት ይሞታል?'),
  ('5ac4170f-6862-5e19-ab34-b59fd8e76e0c', '9cc34e62-cdcc-5a4e-a582-f7dfc83eb777', '47f3fcf7-1afa-5973-abc5-d8954b282d9e', 17, 17, 'ከፀሐይም በታች የተሠራው ሥራ ሁሉ በእኔ ላይ ክፉ ነውና ሕይወትን ጠላሁ፥ ሁሉም ከንቱ፥ ነፋስንም እንደ መከተል ነው።'),
  ('cc3b0a2a-1896-5c60-adc4-efa0698b5db9', '9cc34e62-cdcc-5a4e-a582-f7dfc83eb777', '47f3fcf7-1afa-5973-abc5-d8954b282d9e', 18, 18, 'ከእኔ በኋላ ለሚወለድ ሰው እተወዋለሁና ከፀሐይ በታች እኔ የደከምሁበትን ድካም ሁሉ ጠላሁት።'),
  ('c59f02f6-bc45-5431-a749-8c3a5cffcb8e', '9cc34e62-cdcc-5a4e-a582-f7dfc83eb777', '47f3fcf7-1afa-5973-abc5-d8954b282d9e', 19, 19, 'ጠቢብ ወይም አላዋቂ እንደሚሆን ከፀሐይ በታችም በደከምሁበትና ጠቢብ በሆንሁበት በድካሜ ሁሉ ይሰለጥን እንደ ሆነ የሚያውቅ ሰው ማን ነው? ይህም ደግሞ ከንቱ ነው።'),
  ('4a0dd2ca-f0f8-5124-a98c-b5cea6055023', '9cc34e62-cdcc-5a4e-a582-f7dfc83eb777', '47f3fcf7-1afa-5973-abc5-d8954b282d9e', 20, 20, 'እኔም ተመልሼ ልቤን ከፀሐይ በታች በደከምሁበት ድካም ሁሉ ተስፋ አስቈረጥሁት።'),
  ('a430a001-8748-58a0-a53d-5a7759af19bb', '9cc34e62-cdcc-5a4e-a582-f7dfc83eb777', '47f3fcf7-1afa-5973-abc5-d8954b282d9e', 21, 21, 'ሰው በጥበብና በዕውቀት በብርታትም ከደከመ በኋላ ለሌላ ላልደከመበት ሰው ዕድሉን ያወርሳልና፤ ይህም ደግሞ ከንቱ ትልቅም መከራ ነው።'),
  ('c8a1e3eb-5cd5-5239-a7df-f352f2daf2be', '9cc34e62-cdcc-5a4e-a582-f7dfc83eb777', '47f3fcf7-1afa-5973-abc5-d8954b282d9e', 22, 22, 'ከፀሐይ በታች በደከመበት ድካምና በልቡ ዐሳብ ሁሉ ለሰው አይሆንለትምና፤'),
  ('85d95c4f-597e-513b-af12-6281d901c8fa', '9cc34e62-cdcc-5a4e-a582-f7dfc83eb777', '47f3fcf7-1afa-5973-abc5-d8954b282d9e', 23, 23, 'ዘመኑ ሁሉ መከራ፥ ቍጣም፥ ቅሚያም ነው፤ ልቡም በሌሊት አይተኛም፥ ይህም ደግሞ ከንቱ ነው።'),
  ('f55ed2bb-8097-5305-a656-9f5e97010b63', '9cc34e62-cdcc-5a4e-a582-f7dfc83eb777', '47f3fcf7-1afa-5973-abc5-d8954b282d9e', 24, 24, 'ለሰው ከመብላትና ከመጠጣት በድካሙም ለሰውነቱ መልካም ነገር ከሚያሳያት በቀር በጎ ነገር የለም፤ ይህ ደግሞ ከእግዚአብሔር እጅ እንደ ተሰጠ አየሁ።'),
  ('850d564f-d7e4-5409-a77c-d230bf21d030', '9cc34e62-cdcc-5a4e-a582-f7dfc83eb777', '47f3fcf7-1afa-5973-abc5-d8954b282d9e', 25, 25, 'ያለ እርሱ ፈቃድ የሚበላ ወይም የሚጠጣ ማን ነው?')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('934f1fb0-2b40-5091-aa3b-3cba60cb7c12', '9cc34e62-cdcc-5a4e-a582-f7dfc83eb777', '47f3fcf7-1afa-5973-abc5-d8954b282d9e', 26, 26, 'እርሱ በፊቱ ደግ ለሆነ ሰው ጥበብንና ዕውቀትን፥ ደስታንም ይሰጠዋል፤ ለኀጢአተኛ ግን በእግዚአብሔር ፊት ደግ ለሆነ ይሰጥ ዘንድ እንዲሰበስብና እንዲያከማች ጥረትን ይሰጠዋል። ይህ ደግሞ ከንቱ፥ ነፋስንም እንደ መከተል ነው።'),
  ('c7044701-0955-52c0-a09d-2b3064e59e82', '7936e679-d08b-5973-a636-be4368d6dce0', '7863f800-8ee4-5bb6-a4f1-8b2a9d14e79b', 1, 1, 'ለሁሉ ዘመን አለው፥ ከፀሐይ በታችም ለሆነ ነገር ሁሉ ጊዜ አለው።'),
  ('1b4dc365-bc28-558c-ae34-b653a1329a80', '7936e679-d08b-5973-a636-be4368d6dce0', '7863f800-8ee4-5bb6-a4f1-8b2a9d14e79b', 2, 2, 'ለመፅነስ ጊዜ አለው፥ ለመውለድም ጊዜ አለው፤ ለመኖር ጊዜ አለው፥ ለመሞትም ጊዜ አለው፤ ለመትከል ጊዜ አለው፥ የተተከለውንም ለመንቀል ጊዜ አለው።'),
  ('c5fa96ec-2339-577e-a4e5-40091f31d839', '7936e679-d08b-5973-a636-be4368d6dce0', '7863f800-8ee4-5bb6-a4f1-8b2a9d14e79b', 3, 3, 'ለመግደል ጊዜ አለው፥ ለመፈወስም ጊዜ አለው፤ ለማፍረስ ጊዜ አለው፥ ለመሥራትም ጊዜ አለው፤'),
  ('ac157cd8-494b-5c1a-aaf9-dfb0d568c3b0', '7936e679-d08b-5973-a636-be4368d6dce0', '7863f800-8ee4-5bb6-a4f1-8b2a9d14e79b', 4, 4, 'ለማልቀስ ጊዜ አለው፥ ለመሣቅም ጊዜ አለው፤ ዋይ ለማለት ጊዜ አለው፥ ለመዝፈንም ጊዜ አለው።'),
  ('14d3e2d9-442b-5eff-af38-866aab16a497', '7936e679-d08b-5973-a636-be4368d6dce0', '7863f800-8ee4-5bb6-a4f1-8b2a9d14e79b', 5, 5, 'ድንጋይን ለመወርወር ጊዜ አለው፥ ድንጋይንም ለመሰብሰብ ጊዜ አለው፤ ለመተቃቀፍ ጊዜ አለው፥ ከመተቃቀፍም ለመራቅ ጊዜ አለው፤'),
  ('7c65685b-12e1-5a5b-a68a-83543b2aeb4f', '7936e679-d08b-5973-a636-be4368d6dce0', '7863f800-8ee4-5bb6-a4f1-8b2a9d14e79b', 6, 6, 'ለመፈለግ ጊዜ አለው፥ ለማጥፋትም ጊዜ አለው፤ ለመጠበቅ ጊዜ አለው፥ ለመጣልም ጊዜ አለው፤'),
  ('fef50d0c-a562-5408-a625-1e290c1db247', '7936e679-d08b-5973-a636-be4368d6dce0', '7863f800-8ee4-5bb6-a4f1-8b2a9d14e79b', 7, 7, 'ለመቅደድ ጊዜ አለው፥ ለመስፋትም ጊዜ አለው፤ ዝም ለማለት ጊዜ አለው፥ ለመናገርም ጊዜ አለው፤'),
  ('792f4785-c984-5287-a86e-88d85d3d1c18', '7936e679-d08b-5973-a636-be4368d6dce0', '7863f800-8ee4-5bb6-a4f1-8b2a9d14e79b', 8, 8, 'ለመውደድ ጊዜ አለው፥ ለመጥላትም ጊዜ አለው፤ ለጦርነት ጊዜ አለው፥ ለሰላምም ጊዜ አለው።'),
  ('ade7fb6b-ab24-5e54-a518-c22a8cf7fda8', '7936e679-d08b-5973-a636-be4368d6dce0', '7863f800-8ee4-5bb6-a4f1-8b2a9d14e79b', 9, 9, 'ለሠራተኛ የድካሙ ትርፍ ምንድን ነው?'),
  ('21c29d10-3834-553c-a302-1f79a83c30e3', '7936e679-d08b-5973-a636-be4368d6dce0', '7863f800-8ee4-5bb6-a4f1-8b2a9d14e79b', 10, 10, 'እግዚአብሔር ለሰው ልጆች ይደክሙበት ዘንድ የሰጣቸውን ድካም ሁሉ አይቻለሁ።'),
  ('25bd6447-8a41-59c1-ac44-55a2de52da6b', '7936e679-d08b-5973-a636-be4368d6dce0', '7863f800-8ee4-5bb6-a4f1-8b2a9d14e79b', 11, 11, 'የሠራው ሥራ ሁሉ በጊዜው መልካም ነው፤ እግዚአብሔርም ከጥንት ጀምሮ እስከ ፍጻሜ ድረስ የሠራውን ሥራ ሰው መርምሮ እንዳያገኝ ዘለዓለምነትን በልቡ ሰጠው።'),
  ('733f110b-244f-53b9-a4e1-0ba05e8c03e0', '7936e679-d08b-5973-a636-be4368d6dce0', '7863f800-8ee4-5bb6-a4f1-8b2a9d14e79b', 12, 12, 'ሰው ደስ ከሚለውና በሕይወቱ ሳለ መልካምን ነገር ከሚያደርግ በቀር በውስጣቸው መልካም ነገር እንደሌለ ዐወቅሁ።'),
  ('96ff6555-3b22-5e63-afcc-1731f61b18ef', '7936e679-d08b-5973-a636-be4368d6dce0', '7863f800-8ee4-5bb6-a4f1-8b2a9d14e79b', 13, 13, 'ደግሞም ሰው ሁሉ ይበላና ይጠጣ ዘንድ በድካሙም ሁሉ መልካምን ያይ ዘንድ የእግዚአብሔር ስጦታ ነው።'),
  ('db0387a1-faec-5b29-a3c1-d6aa8a0224d4', '7936e679-d08b-5973-a636-be4368d6dce0', '7863f800-8ee4-5bb6-a4f1-8b2a9d14e79b', 14, 14, 'እግዚአብሔር ያደረገው ሁሉ ለዘለዓለም እንዲኖር ዐወቅሁ፤ በእነርሱም ላይ መጨመር ከእነርሱም ማጕደል አይቻልም፤ እግዚአብሔርም በፊቱ ይፈሩ ዘንድ አደረገ።'),
  ('e443a031-e0a0-51ea-af0a-3427822bc66e', '7936e679-d08b-5973-a636-be4368d6dce0', '7863f800-8ee4-5bb6-a4f1-8b2a9d14e79b', 15, 15, 'በፊት የተደረገው አሁን አለ። ይደረግ ዘንድ ያለውም እነሆ ተደርጓል፤ እግዚአብሔርም ያለፈውን መልሶ ይሻዋል።'),
  ('6f27980d-f44e-5f65-aa47-3f075f9366bb', '7936e679-d08b-5973-a636-be4368d6dce0', '7863f800-8ee4-5bb6-a4f1-8b2a9d14e79b', 16, 16, 'ደግሞም ከፀሐይ በታች በጻድቅ ስፍራ ኃጥእ፥ በኃጥእም ስፍራ ጻድቅ እንዳለ አየሁ።'),
  ('92ba9085-9234-5517-a9f1-7a3535fb25b2', '7936e679-d08b-5973-a636-be4368d6dce0', '7863f800-8ee4-5bb6-a4f1-8b2a9d14e79b', 17, 17, 'እኔም በልቤ፥ “በዚያ ለነገር ሁሉና ለሥራ ሁሉ ጊዜ አለውና በጻድቁና በኀጢአተኛው ላይ እግዚአብሔር ይፈርዳል” አልሁ።'),
  ('7a0f122b-910b-5ed1-a955-2270e5966be4', '7936e679-d08b-5973-a636-be4368d6dce0', '7863f800-8ee4-5bb6-a4f1-8b2a9d14e79b', 18, 18, 'እኔ በልቤ ስለ ሰው ልጆች ነገር፥ “እንደ እንስሳ መሆናቸውን ያሳይ ዘንድ እግዚአብሔር ይፈርድባቸዋል” አልሁ።'),
  ('16560d3c-24f5-54fb-a2cd-0a273f8f4fd1', '7936e679-d08b-5973-a636-be4368d6dce0', '7863f800-8ee4-5bb6-a4f1-8b2a9d14e79b', 19, 19, 'ለሰው ልጆች ሞት አለባቸው፥ ለእንስሳም ሞት አለባቸው፤ አንድ ሞት አለባቸው፤ አንዱ እንደሚሞት ሌላውም እንዲሁ ይሞታል፤ ለሁሉም አንድ እስትንፋስ አላቸው፥ ሰው ከእንስሳ ብልጫው ምንድን ነው? ሁሉም ከንቱ ነውና ምንም የለውም።'),
  ('e5c4f149-ca1a-5cdf-ad0b-a6eb6b368a0c', '7936e679-d08b-5973-a636-be4368d6dce0', '7863f800-8ee4-5bb6-a4f1-8b2a9d14e79b', 20, 20, 'ሁሉም ወደ አንድ ቦታ ይሄዳል፤ ሁሉ ከአፈር ተገኘ፥ ሁሉም ወደ አፈር ይመለሳል።'),
  ('68195f66-5ff7-5ee2-ad22-ec58bf0d4e01', '7936e679-d08b-5973-a636-be4368d6dce0', '7863f800-8ee4-5bb6-a4f1-8b2a9d14e79b', 21, 21, 'የሰው ልጆች ነፍስ ወደ ላይ እንደምትወጣ፥ የእንስሳም ነፍስ ወደ ታች ወደ ምድር እንደምትወርድ የሚያውቅ ማን ነው?'),
  ('d80e7029-c592-5156-a81a-2bf75dc884bb', '7936e679-d08b-5973-a636-be4368d6dce0', '7863f800-8ee4-5bb6-a4f1-8b2a9d14e79b', 22, 22, 'ያም ዕድል ፋንታው ነውና ሰው በሥራው ደስ ከሚለው በቀር ሌላ መልካም ነገር እንደሌለው አየሁ፤ ከእርሱ በኋላስ የሚሆነውን ያይ ዘንድ የሚያመጣው ማን ነው?'),
  ('cba9d6c2-204d-5222-a8c3-ca1f8c9ef6a1', 'c1002840-04a9-53a2-aa4a-61ac33bef758', 'fb41d920-bbdd-583b-a813-e2de28e155ac', 1, 1, 'እኔም ተመለስሁ፥ ከፀሓይ በታችም የሚደረገውን ግፍ ሁሉ አየሁ፤ እነሆም፥ የተገፉት ሰዎች እንባ ነበረ፤ የሚያጽናናቸውም አልነበረም፤ በሚገፉአቸውም እጅ ኀይል ነበረ። እነርሱን ግን የሚያጽናናቸው አልነበረም።'),
  ('8f28b75b-265e-5d69-adf4-0145c8c52aba', 'c1002840-04a9-53a2-aa4a-61ac33bef758', 'fb41d920-bbdd-583b-a813-e2de28e155ac', 2, 2, 'እኔም እስከ ዛሬ በሕይወት ካሉት ሕያዋን ይልቅ በቀድሞ ዘመን የሞቱትን አመሰገንኋቸው።'),
  ('4e977e9e-8b7a-56df-a77a-00e2353c0a03', 'c1002840-04a9-53a2-aa4a-61ac33bef758', 'fb41d920-bbdd-583b-a813-e2de28e155ac', 3, 3, 'ከእነዚህም ከሁለቱ ይልቅ ገና ያልተወለደው ከፀሓይም በታች የሚደረገውን ክፉ ሥራ ሁሉ ያላየ ይሻላል።'),
  ('34920e9b-3bb5-5016-acf0-f09ee0d0c257', 'c1002840-04a9-53a2-aa4a-61ac33bef758', 'fb41d920-bbdd-583b-a813-e2de28e155ac', 4, 4, 'እኔ ድካምን ሁሉና የብልሃት ሥራውን ተመለከትሁ፥ ለሰውም በባልንጀራው ዘንድ ቅንአትን እንዲያስነሣ አየሁ፤ ይህም ደግሞ ከንቱ ነፋስንም እንደ መከተል ነው።'),
  ('e949e526-6bdc-5918-a070-adddb9cf781f', 'c1002840-04a9-53a2-aa4a-61ac33bef758', 'fb41d920-bbdd-583b-a813-e2de28e155ac', 5, 5, 'ሰነፍ እጆቹን ኰርትሞ ይቀመጣል፥ የገዛ ሥጋውንም ይበላል።'),
  ('2725459d-c034-5183-a56e-638876df06cf', 'c1002840-04a9-53a2-aa4a-61ac33bef758', 'fb41d920-bbdd-583b-a813-e2de28e155ac', 6, 6, 'በድካምና ነፋስን በመከተል ከሁለት እጅ ሙሉ ይልቅ አንድ እጅ ሙሉ በዕረፍት ይሻላል።'),
  ('c7eba4c6-7c56-5a90-a280-eb2dd32d92ae', 'c1002840-04a9-53a2-aa4a-61ac33bef758', 'fb41d920-bbdd-583b-a813-e2de28e155ac', 7, 7, 'እኔም ተመለስሁ፥ ከፀሓይ በታችም ከንቱ ነገርን አየሁ።'),
  ('00fcebe7-b077-5d28-a81c-171bc15d8853', 'c1002840-04a9-53a2-aa4a-61ac33bef758', 'fb41d920-bbdd-583b-a813-e2de28e155ac', 8, 8, 'አንድ ሰው ብቻውን አለ፥ ሁለተኛም የለውም፥ ልጅም ሆነ ወንድም የለውም፤ ለድካሙ ግን መጨረሻ የለውም፥ ዐይኖቹም ከባለጠግነት አይጠግቡም። ለማን እደክማለሁ? ሰውነቴንስ ከደስታ ለምን እነፍጋታለሁ? ይላል። ይህም ደግሞ ከንቱ ነገር፥ ክፉም ጥረት ነው።'),
  ('b8337c89-cf0f-55a5-a552-033ce4f6c777', 'c1002840-04a9-53a2-aa4a-61ac33bef758', 'fb41d920-bbdd-583b-a813-e2de28e155ac', 9, 9, 'ድካማቸው መልካም ዋጋ አለውና አንድ ብቻ ከመሆን ሁለት መሆን ይሻላል።'),
  ('26dfa622-a29c-5d92-a6b9-152a6e2f3292', 'c1002840-04a9-53a2-aa4a-61ac33bef758', 'fb41d920-bbdd-583b-a813-e2de28e155ac', 10, 10, 'አንዱ ቢወድቅ ሁለተኛው ያነሣዋልና፥ አንድ ብቻውን ሆኖ በወደቀ ጊዜ ግን የሚያነሣው ሁለተኛ የለውምና ወዮለት።'),
  ('e291727d-9acb-52c3-a370-61f97affa5bd', 'c1002840-04a9-53a2-aa4a-61ac33bef758', 'fb41d920-bbdd-583b-a813-e2de28e155ac', 11, 11, 'ሁለቱም በአንድነት ቢተኙ ይሞቃቸዋል፤ አንድ ብቻውን ግን እንዴት ይሞቀዋል?'),
  ('0580ef4c-c8c3-5311-af07-91f762450480', 'c1002840-04a9-53a2-aa4a-61ac33bef758', 'fb41d920-bbdd-583b-a813-e2de28e155ac', 12, 12, 'አንዱም ሌላውን ቢያሸንፍ ሁለቱ በፊቱ ይቆማሉ፤ በሦስትም የተገመደ ገመድ ፈጥኖ አይበጠስም።'),
  ('1b4c9ecf-3f11-5934-a28f-7b8c9719eb6a', 'c1002840-04a9-53a2-aa4a-61ac33bef758', 'fb41d920-bbdd-583b-a813-e2de28e155ac', 13, 13, 'ድሃና ጠቢብ ብላቴና ከእንግዲህ ወዲህ ተግሣጽን መቀበል ከማያውቅ ከሰነፍ ሽማግሌ ንጉሥ ይሻላል።'),
  ('033ce81f-38e6-5a02-a0ae-66d670adb8c5', 'c1002840-04a9-53a2-aa4a-61ac33bef758', 'fb41d920-bbdd-583b-a813-e2de28e155ac', 14, 14, 'በመንግሥቱ ችግረኛ ቢሆንም ከግዞት ቤት ለመንገሥ ወጥቶአልና።'),
  ('f6b71314-4701-5865-ad80-ec5294e5b786', 'c1002840-04a9-53a2-aa4a-61ac33bef758', 'fb41d920-bbdd-583b-a813-e2de28e155ac', 15, 15, 'ከፀሓይ በታች የሚሄዱትን ሕያዋን ሁሉ በእርሱ ፋንታ ከሚነሣው ከሌላው ጐልማሳ ጋር ሆነው አየሁ።'),
  ('8ff75780-0d4b-5b28-a16c-6590998d06ce', 'c1002840-04a9-53a2-aa4a-61ac33bef758', 'fb41d920-bbdd-583b-a813-e2de28e155ac', 16, 16, 'ከእርሱ በፊት የነበሩት ሕዝብ ሁሉ ቍጥር የላቸውም፤ በኋላ የሚመጡት ግን በእርሱ ደስ አይላቸውም። ይህ ደግሞ ከንቱ ነው፥ ነፋስንም እንደ መከተል ነው።'),
  ('0398e809-859b-5fe5-a2c8-aa815404df77', '5d11211f-8b90-56e9-a75f-a8c0afc3122f', '8ef6a177-49bf-5f19-a4ec-e58a46527dfb', 1, 1, 'ወደ እግዚአብሔር ቤት በምትሄድበት ጊዜ እግርህን ጠብቅ፤ የጠቢባንንም ትምህርት ለመስማት ቅረብ፤ ዳግመኛም ከሰነፎች ስጦታ መሥዋዕት አድርገህ ከመቀበል ተጠበቅ፤ እነርሱ መልካም ለመሥራት ዐዋቂዎች አይደሉምና።'),
  ('8405b969-6f35-52b8-a278-c8d5d383eef6', '5d11211f-8b90-56e9-a75f-a8c0afc3122f', '8ef6a177-49bf-5f19-a4ec-e58a46527dfb', 2, 2, 'እግዚአብሔር በሰማይ፥ አንተም በምድር ነህና በአፍህ አትፍጠን፥ በእግዚአብሔርም ፊት ቃልን ይናገር ዘንድ ልብህ አይቸኩል፤ ስለዚህም ቃልህ ጥቂት ይሁን።'),
  ('7e2db2d5-8f96-53b6-ab7e-ff35b4705377', '5d11211f-8b90-56e9-a75f-a8c0afc3122f', '8ef6a177-49bf-5f19-a4ec-e58a46527dfb', 3, 3, 'ሕልም በብዙ መከራ፥ እንዲሁም የሰነፍ ቃል በብዙ ነገር ይመጣልና።'),
  ('69b2ba15-3f83-5e5d-af95-18b3dba406bd', '5d11211f-8b90-56e9-a75f-a8c0afc3122f', '8ef6a177-49bf-5f19-a4ec-e58a46527dfb', 4, 4, 'ፈቃዱ አይደለምና ለእግዚአብሔር ስእለት በተሳልህ ጊዜ ትፈጽመው ዘንድ አትዘግይ፤ አንተ ግን እንደ ተሳልህ ስእለትህን ስጥ።'),
  ('7be4b5e9-3d1e-5226-a41d-e9e6f5622801', '5d11211f-8b90-56e9-a75f-a8c0afc3122f', '8ef6a177-49bf-5f19-a4ec-e58a46527dfb', 5, 5, 'ተስለህ የማትፈጽም ከሆነ ባትሳል ይሻላል።'),
  ('80b1d123-b40e-52ff-ae35-19e60fb62d71', '5d11211f-8b90-56e9-a75f-a8c0afc3122f', '8ef6a177-49bf-5f19-a4ec-e58a46527dfb', 6, 6, 'ለሥጋህ በደል አፍህን አትስጥ፥ በእግዚአብሔርም ፊት፥ “ባለማወቅ ነው” አትበል፤ እግዚአብሔር ስለ ቃልህ እንዳይቈጣ፥ የእጅህንም ሥራ እንዳያጠፋብህ፤'),
  ('beb44195-10e1-5f55-a6ac-09e93c00d760', '5d11211f-8b90-56e9-a75f-a8c0afc3122f', '8ef6a177-49bf-5f19-a4ec-e58a46527dfb', 7, 7, 'ብዙ ሕልም፥ እንዲሁ ደግሞ ብዙ ቃል ከንቱ ነውና፤ አንተ ግን እግዚአብሔርን ፈጽመህ ፍራ።'),
  ('f1c7696b-3fec-5e67-a602-ef36bc184954', '5d11211f-8b90-56e9-a75f-a8c0afc3122f', '8e77efbf-4413-5011-a653-0aa43aacbca2', 1, 8, 'ከፍ ካለው በላይ ከፍ ያለ ይጠብቅሃልና፥ ከእነርሱም በላይ ደግሞ ሌሎች ከፍ ይላሉና በሀገሩ ድሃ ሲበደል፥ ፍርድና ጽድቅም ሲነጠቅ ብታይ በሥራው አታድንቅ።'),
  ('1cc562c2-6818-5ac1-a0ab-a7c556956d09', '5d11211f-8b90-56e9-a75f-a8c0afc3122f', '8e77efbf-4413-5011-a653-0aa43aacbca2', 2, 9, 'የምድር ጥቅም ለሁሉ ነው፥ የንጉሥም ጥቅም በእርሻ ነው።'),
  ('d017076c-a3a0-5cee-acd7-b60bef4fbc0c', '5d11211f-8b90-56e9-a75f-a8c0afc3122f', '8e77efbf-4413-5011-a653-0aa43aacbca2', 3, 10, 'ብርን የሚወድድ ሰው ብርን አይጠግብም፤ ብዙ እህልንም የሚወድድ እንዲሁ ነው፤ ይህም ከንቱ ነው።'),
  ('ff267319-a897-5a73-a995-b4ef0bbd8c90', '5d11211f-8b90-56e9-a75f-a8c0afc3122f', '8e77efbf-4413-5011-a653-0aa43aacbca2', 4, 11, 'ሀብት ሲበዛ የሚበሉት ይበዛሉ፤ በዐይኑም ከማየት በቀር ለባለቤቱ ምን ይጠቅመዋል?'),
  ('30f61227-5eff-5e0d-a26a-7b02e1eb0319', '5d11211f-8b90-56e9-a75f-a8c0afc3122f', '8e77efbf-4413-5011-a653-0aa43aacbca2', 5, 12, 'ብዙ ወይም ጥቂት ቢበላ የአገልጋይ እንቅልፉ ጣፋጭ ነው፤ ብልጽግናን ያበዛ ሰውን ግን ይተኛ ዘንድ የሚተወው የለም።'),
  ('06e9420a-17e3-5308-a2d8-c57126cb8006', '5d11211f-8b90-56e9-a75f-a8c0afc3122f', '8e77efbf-4413-5011-a653-0aa43aacbca2', 6, 13, 'ከፀሓይ በታች ያየሁት ክፉ ደዌ አለ፤ ለመከራው በባለቤቱ ዘንድ የተቈጠበች ባለጠግነት ናት።'),
  ('7c2a6467-4e0a-5f1f-a9de-df3bcef75aef', '5d11211f-8b90-56e9-a75f-a8c0afc3122f', '8e77efbf-4413-5011-a653-0aa43aacbca2', 7, 14, 'ያችም ባለጠግነት በክፉ ንጥቂያ ትጠፋለች፤ ልጅንም ቢወልድ በእጁ ምንም የለውም።'),
  ('68f209f6-4326-5125-aa66-d7fea45a2284', '5d11211f-8b90-56e9-a75f-a8c0afc3122f', '8e77efbf-4413-5011-a653-0aa43aacbca2', 8, 15, 'ከእናቱ ሆድ ራቁቱን እንደ ወጣ እንዲሁ እንደ መጣው ይመለሳል፤ ከጥረቱም በእጁ ሊወስድ የሚችለው ምንም የለም።'),
  ('8d58e779-4b4e-5f64-a7a3-f9b1b1b8ac8a', '5d11211f-8b90-56e9-a75f-a8c0afc3122f', '8e77efbf-4413-5011-a653-0aa43aacbca2', 9, 16, 'ይህም ደግሞ የሚያሳዝን ክፉ ደዌ ነው፥ እንደ መጣ እንዲሁ ይሄዳልና፥ ለሰውነቱ ለሚደክም ሰው ትርፉ ምንድን ነው?'),
  ('76f0ae7c-f40e-5132-a246-53eb1de6bdf9', '5d11211f-8b90-56e9-a75f-a8c0afc3122f', '8e77efbf-4413-5011-a653-0aa43aacbca2', 10, 17, 'ዘመኑ ሁሉ በጨለማ በልቅሶና በብዙ ብስጭት በደዌና በኀዘን ነውና።'),
  ('7955b77f-9113-5a9a-ada0-04d26cdd17db', '5d11211f-8b90-56e9-a75f-a8c0afc3122f', '8e77efbf-4413-5011-a653-0aa43aacbca2', 11, 18, 'እነሆ፥ እኔ ያየሁት መልካምና የተዋበ ነገር፦ ሰው እግዚአብሔር በሰጠው በሕይወቱ ዘመን ሁሉ ይበላና ይጠጣ ዘንድ፥ ከፀሐይ በታችም በሚደክምበት ድካም ሁሉ ደስ ይለው ዘንድ ነው፤ ይህ ዕድል ፈንታው ነውና።'),
  ('1b7c6d6a-98d6-50b5-ad2c-e10278da0316', '5d11211f-8b90-56e9-a75f-a8c0afc3122f', '8e77efbf-4413-5011-a653-0aa43aacbca2', 12, 19, 'እግዚአብሔር ለሰው ሁሉ ባለጠግነትንና ሀብትን መስጠቱ፥ ከእርስዋም ይበላና ዕድል ፈንታውን ይወስድ ዘንድ፥ በድካሙም ደስ ይለው ዘንድ ማሠልጠኑ ይህ የእግዚአብሔር ስጦታ ነው።'),
  ('402daaa6-8036-54c8-aedf-5b3071f27ca6', '5d11211f-8b90-56e9-a75f-a8c0afc3122f', '8e77efbf-4413-5011-a653-0aa43aacbca2', 13, 20, 'እግዚአብሔር በልቡ ደስታ ስለሚያደክመው እርሱ የሕይወቱን ዘመን ሁሉ እጅግ አያስብም።'),
  ('575eb08f-e171-5baf-a859-8c5d9e049c43', 'dcd9299f-b5d6-5e0c-a969-6d490d3cf1de', 'f7019bdb-2d2d-56b6-a942-87902ba7bcb0', 1, 1, 'ከፀሐይ በታች ያየሁት ክፉ ነገር አለ፥ እርሱም በሰው ላይ እጅግ የበዛ ነው።'),
  ('3e80ae20-f7a1-5a61-aeb1-759c08a8feea', 'dcd9299f-b5d6-5e0c-a969-6d490d3cf1de', 'f7019bdb-2d2d-56b6-a942-87902ba7bcb0', 2, 2, 'እግዚአብሔር ለሰው ሀብትንና ጥሪትን ክብርንም ሰጠው፥ ከወደደውም ሁሉ ለሰውነቱ የከለከላት የለም፤ ነገር ግን ሌላ ሰው ይበላዋል እንጂ ከእርሱ ይበላ ዘንድ እግዚአብሔር አላሠለጠነውም፤ ይህም ከንቱና ክፉ ደዌ ነው።'),
  ('66017ac5-175a-5e70-a831-17ce8c6b10b4', 'dcd9299f-b5d6-5e0c-a969-6d490d3cf1de', 'f7019bdb-2d2d-56b6-a942-87902ba7bcb0', 3, 3, 'ሰው መቶ ልጆች ቢወልድ፥ ብዙ ዘመንም በሕይወት ቢኖር፥ ዕድሜውም ብዙ ዓመት ቢሆን፥ ነገር ግን ነፍሱ መልካምን ባትጠግብ፥ መቃብርንም ባያገኝ፥ እኔ ስለ እርሱ፥ “ከእርሱ ይልቅ ጭንጋፍ ይሻላል” አልሁ።'),
  ('4d21ba15-9c12-5911-ab08-7d17d29ab2ec', 'dcd9299f-b5d6-5e0c-a969-6d490d3cf1de', 'f7019bdb-2d2d-56b6-a942-87902ba7bcb0', 4, 4, 'በከንቱ መጥቶአል፥ በጨለማም ይሄዳል፥ ስሙ በጨለማ ይሸፈናልና።'),
  ('58f39920-82ab-5e46-a834-47f4b2418306', 'dcd9299f-b5d6-5e0c-a969-6d490d3cf1de', 'f7019bdb-2d2d-56b6-a942-87902ba7bcb0', 5, 5, 'ደግሞም ፀሐይን አላየም፥ አላወቀምም፤ ስለዚህ ከዚያ ይልቅ ለዚህ ዕረፍት አለው።'),
  ('f3a50570-73a4-5598-a61b-d2218c03b47f', 'dcd9299f-b5d6-5e0c-a969-6d490d3cf1de', 'f7019bdb-2d2d-56b6-a942-87902ba7bcb0', 6, 6, 'ሺህ ዓመት ሁለት ጊዜ በሕይወት ቢኖር፥ መልካምንም ባያይ፥ ሁሉ ወደ አንድ ስፍራ የሚሄድ አይደለምን?'),
  ('248a6225-1cf8-5cda-a6d0-614b877cd436', 'dcd9299f-b5d6-5e0c-a969-6d490d3cf1de', 'f7019bdb-2d2d-56b6-a942-87902ba7bcb0', 7, 7, 'የሰው ድካም ሁሉ በአፉ ነው፥ ነፍሱ ግን አትጠግብም።'),
  ('308bf014-e800-555c-a643-198d977aa3bf', 'dcd9299f-b5d6-5e0c-a969-6d490d3cf1de', 'f7019bdb-2d2d-56b6-a942-87902ba7bcb0', 8, 8, 'ከአላዋቂ ይልቅ ለጠቢብ ጥቅሙ ምንድር ነው? በሕያዋን ፊትስ መሄድን ለሚያውቅ ለድሃ ጥቅሙ ምንድር ነው?'),
  ('5674022c-837e-585a-a509-4c81db78ec27', 'dcd9299f-b5d6-5e0c-a969-6d490d3cf1de', 'f7019bdb-2d2d-56b6-a942-87902ba7bcb0', 9, 9, 'በዐይን ማየት በነፍስ ከመቅበዝበዝ ይሻላል፥ ይህ ደግሞ ከንቱ ነው፥ ነፋስንም እንደ መከተል ነው።'),
  ('77650825-7588-542e-ade1-c72e2476fb10', 'dcd9299f-b5d6-5e0c-a969-6d490d3cf1de', 'f7019bdb-2d2d-56b6-a942-87902ba7bcb0', 10, 10, 'የሆነው ሁሉ እነሆ፥ ስሙ አስቀድሞ ተጠራ፥ ሰውም እንደ ሆነ ታወቀ፤ ከእርሱም ከሚበረታው ጋር ይፋረድ ዘንድ አይችልም።'),
  ('67e0c16c-e6b6-51a6-a99d-f4fb9aab8ecf', 'dcd9299f-b5d6-5e0c-a969-6d490d3cf1de', 'f7019bdb-2d2d-56b6-a942-87902ba7bcb0', 11, 11, 'ከንቱን የሚያበዛ ብዙ ነገር አለና፥ ለሰው ጥቅሙ ምንድር ነው?'),
  ('221dcb83-dae8-5b50-aaa3-d596f5a8947c', 'dcd9299f-b5d6-5e0c-a969-6d490d3cf1de', 'f7019bdb-2d2d-56b6-a942-87902ba7bcb0', 12, 12, 'ሰው በከንቱ ወራቱ ቍጥርና እንደ ጥላ በሚያሳልፈው ዘመኑ በሕይወቱ ሳለ ለሰው የሚሻለውን የሚያውቅ ማን ነው? ወይስ ለሰው ከፀሓይ በታች ከእርሱ በኋላ የሚሆነውን ማን ይነግረዋል?'),
  ('70d9a90d-b121-5a68-a982-718b937a9459', 'd565291d-e584-5fb4-a10f-fcff3e973b0e', 'c4986dcd-721e-5917-ad79-065e5685fa28', 1, 1, 'ከመልካም ሽቱ መልካም ስም፥ ከመወለድ ቀንም የሞት ቀን ይሻላል።'),
  ('6e13d164-7ac6-57f7-a3e3-27d7522cad72', 'd565291d-e584-5fb4-a10f-fcff3e973b0e', 'c4986dcd-721e-5917-ad79-065e5685fa28', 2, 2, 'ወደ ግብዣ ቤትም ከመሄድ ወደ ልቅሶ ቤት መሄድ ይሻላል፤ እርሱ የሰው ሁሉ ፍጻሜ ነውና፥ ሕያውም የሆነ ይህን መልካም ነገር በልቡ ያኖረዋል።'),
  ('d7ab5e87-00fe-5849-a53e-ab3eaabb6ff6', 'd565291d-e584-5fb4-a10f-fcff3e973b0e', 'c4986dcd-721e-5917-ad79-065e5685fa28', 3, 3, 'ከሣቅ ኀዘን ይሻላል፥ ከፊት ኀዘን የተነሣ ልብ ደስ ይሰኛልና።'),
  ('41dbde25-5c0d-5309-ad76-b46f802715f2', 'd565291d-e584-5fb4-a10f-fcff3e973b0e', 'c4986dcd-721e-5917-ad79-065e5685fa28', 4, 4, 'የጠቢባን ልብ በልቅሶ ቤት ነው፤ የሰነፎች ልብ ግን በደስታ ቤት ነው።'),
  ('b39979bc-2463-5260-ae0b-cdc5aa69b3f4', 'd565291d-e584-5fb4-a10f-fcff3e973b0e', 'c4986dcd-721e-5917-ad79-065e5685fa28', 5, 5, 'ለሰው የሰነፎችን ዘፈን ከሚሰማ ይልቅ የጠቢባንን ተግሣጽ መስማት ይሻለዋል።'),
  ('72016574-82ba-5ebb-aab2-93dc0fcde3c2', 'd565291d-e584-5fb4-a10f-fcff3e973b0e', 'c4986dcd-721e-5917-ad79-065e5685fa28', 6, 6, 'ከድስት በታች እንደሚቃጠል እሾህ ድምፅ የሰነፍ ሣቅ እንዲሁ ነው፤ ይህም ደግሞ ከንቱ ነው።'),
  ('8710d726-4914-51c5-a086-ed771da13a16', 'd565291d-e584-5fb4-a10f-fcff3e973b0e', 'c4986dcd-721e-5917-ad79-065e5685fa28', 7, 7, 'ግፍ ጠቢብን ያሳብደዋል፥ የልቡንም ትዕግሥት ያጠፋዋል።'),
  ('b2730ecd-f619-5676-ae48-756944423d41', 'd565291d-e584-5fb4-a10f-fcff3e973b0e', 'c4986dcd-721e-5917-ad79-065e5685fa28', 8, 8, 'የነገር ፍጻሜ ከመጀመሪያው ይሻላል፤ ታጋሽም ከልብ ትዕቢተኛ ይሻላል።'),
  ('983fc2b5-5a8f-51db-ae57-c28fb71f47b0', 'd565291d-e584-5fb4-a10f-fcff3e973b0e', 'c4986dcd-721e-5917-ad79-065e5685fa28', 9, 9, 'በመንፈስህ ለቍጣ ችኩል አትሁን፥ ቍጣ በሰነፎች ብብት ያርፋልና።'),
  ('f445b6b3-b470-5a14-abb4-c80337e310c0', 'd565291d-e584-5fb4-a10f-fcff3e973b0e', 'c4986dcd-721e-5917-ad79-065e5685fa28', 10, 10, 'ከዚህ ዘመን ይልቅ ያለፈው ዘመን ለምን ተሻለ? ብለህ አትናገር፤ የዚህን ነገር በጥበብ አትጠይቅምና።'),
  ('1e588de1-366a-50ae-a69c-daf63384d0f5', 'd565291d-e584-5fb4-a10f-fcff3e973b0e', 'c4986dcd-721e-5917-ad79-065e5685fa28', 11, 11, 'ጥበብ ከርስት ጋር መልካም ነው፤ ፀሓይንም ለሚያዩ ሰዎች ትርፍን ይሰጣል።'),
  ('ca8ccfb2-4b90-5752-aeb0-6d0ebd36eebb', 'd565291d-e584-5fb4-a10f-fcff3e973b0e', 'c4986dcd-721e-5917-ad79-065e5685fa28', 12, 12, 'የጥበብ ጥላ ከብር ጥላ ይሻላል፤ የጥበብንም ዕውቀት ማብዛት ገንዘብ ላደረጋት ሕይወትን ትሰጠዋለች።'),
  ('d7fe1c7b-7da7-596a-adb3-c0dbb3b62b6b', 'd565291d-e584-5fb4-a10f-fcff3e973b0e', 'c4986dcd-721e-5917-ad79-065e5685fa28', 13, 13, 'የእግዚአብሔርን ሥራ ተመልከት፤ እግዚአብሔር ጠማማ ያደረገውን ማን ሊያቀናው ይችላል?'),
  ('97fa510f-d7a8-5480-adca-c46f8be5d240', 'd565291d-e584-5fb4-a10f-fcff3e973b0e', 'c4986dcd-721e-5917-ad79-065e5685fa28', 14, 14, 'በመልካም ቀን ደስ ይበልህ ፤ በክፉም ቀን ተመልከት፤ ሰው ከእርሱ በኋላ መርምሮ ምንም እንዳያገኝ እግዚአብሔር ይህንም ያንም እንደዚያ ሠራ።'),
  ('6b28b138-4eb5-5429-a706-a130848e734c', 'd565291d-e584-5fb4-a10f-fcff3e973b0e', 'c4986dcd-721e-5917-ad79-065e5685fa28', 15, 15, 'ጻድቅ በጽድቁ ሲጠፋ፥ ኃጥእም በክፋቱ ሲኖር፥ ይህን ሁሉ በከንቱ ዘመኔ አየሁ።'),
  ('bd642220-829c-5583-a234-376cd1318179', 'd565291d-e584-5fb4-a10f-fcff3e973b0e', 'c4986dcd-721e-5917-ad79-065e5685fa28', 16, 16, 'እጅግ ጻድቅ አትሁን፥ እጅግም ጠቢብ አትሁን፥ እንዳትበድል።'),
  ('f1fb89ae-0c56-5c92-a53a-025087eb6246', 'd565291d-e584-5fb4-a10f-fcff3e973b0e', 'c4986dcd-721e-5917-ad79-065e5685fa28', 17, 17, 'እጅግ ክፉ አትሁን፥ እልከኛም አትሁን፥ ያለ ጊዜህ እንዳትሞት።'),
  ('1ab9733d-ddaa-596e-aee4-4c188656e1c3', 'd565291d-e584-5fb4-a10f-fcff3e973b0e', 'c4986dcd-721e-5917-ad79-065e5685fa28', 18, 18, 'ይህን ብትይዝ ለአንተ መልካም ነው፤ በዚህም እጅህን አታርክስ፥ እግዚአብሔርን የሚፈራ ከሁሉ ይወጣልና።'),
  ('ecb3133d-bced-5511-a80e-349350fdb332', 'd565291d-e584-5fb4-a10f-fcff3e973b0e', 'c4986dcd-721e-5917-ad79-065e5685fa28', 19, 19, 'በከተማ ከሚኖሩ ዐሥር ገዢዎች ይልቅ ጥበብ ጠቢብን ትረዳዋለች።'),
  ('8456817b-f276-5223-abbf-2fd666cad0bb', 'd565291d-e584-5fb4-a10f-fcff3e973b0e', 'c4986dcd-721e-5917-ad79-065e5685fa28', 20, 20, 'በምድር ላይም መልካምን የሚሠራ ኀጢአትንም የማያደርግ ጻድቅ ሰው አይገኝምና።'),
  ('2c275fc6-fe95-58d4-a290-12b6f0964d97', 'd565291d-e584-5fb4-a10f-fcff3e973b0e', 'c4986dcd-721e-5917-ad79-065e5685fa28', 21, 21, 'አገልጋይህ ሲረግምህ እንዳትሰማ በሚጫወቱበት ቃል ሁሉ ልብህን አትጣል።'),
  ('7799592d-85df-55fd-a45c-5c08a11bc9e7', 'd565291d-e584-5fb4-a10f-fcff3e973b0e', 'c4986dcd-721e-5917-ad79-065e5685fa28', 22, 22, 'ብዙ ጊዜ ያበሳጭሃልና፤ በብዙ መንገድም ልብህን ያስከፋታልና፥ አንተ ደግሞ ሌሎችን እንደ ረገምህ ታውቃለህና።'),
  ('0f848394-7cdf-5650-a82e-605577c0f898', 'd565291d-e584-5fb4-a10f-fcff3e973b0e', 'c4986dcd-721e-5917-ad79-065e5685fa28', 23, 23, 'ይህን ሁሉ በጥበብ ፈተንሁ፥ ጠቢብም እሆናለሁ አልሁ፥ እርስዋ ግን ከእኔ ራቀች።'),
  ('9ac61d49-84bc-5b0d-aa1a-8070a214543d', 'd565291d-e584-5fb4-a10f-fcff3e973b0e', 'c4986dcd-721e-5917-ad79-065e5685fa28', 24, 24, 'ርቃና እጅግ ጠልቃ ሳለች መርምሮ የሚያገኛት ማን ነው?'),
  ('8e664ab9-b89f-5230-aa70-79535af178a7', 'd565291d-e584-5fb4-a10f-fcff3e973b0e', 'c4986dcd-721e-5917-ad79-065e5685fa28', 25, 25, 'አውቅና እመረምር ዘንድ ጥበብንና የነገሩን ሁሉ መደምደሚያ እፈልግ ዘንድ፥ የክፉዎችንም ስንፍናና ዕብደት አውቅ ዘንድ እኔ በልቤ ዞርሁ።'),
  ('fe59e7b3-f0a3-5f18-a892-f6e0bd58d00b', 'd565291d-e584-5fb4-a10f-fcff3e973b0e', 'c4986dcd-721e-5917-ad79-065e5685fa28', 26, 26, 'እኔም ከሞት ይልቅ የመረረች ነገርን አገኘሁ፤ እርስዋም ልብዋ ወጥመድና መረብ የሆነ፥ በእጆችዋም ማሰሪያ ያላት ሴት ናት፤ በእግዚአብሔርም ፊት ደግ የሆነ ከእርሷ ያመልጣል። ኀጢአተኛ ግን ይጠመድባታል።'),
  ('6976b099-7ce7-509e-aa39-239c5594c401', 'd565291d-e584-5fb4-a10f-fcff3e973b0e', 'c4986dcd-721e-5917-ad79-065e5685fa28', 27, 27, 'እነሆ፥ ይህን ነገር አገኘሁ ይላል ሰባኪው፥ መደምደሚያን ለማግኘት አንዲቱን በአንዲቱ ጨምሬ ወደ ነገሩ ሁሉ መደምደሚያ እደርስ ዘንድ ብመረምር፥'),
  ('db7ef820-c3f0-5707-ac32-1465d0c207a7', 'd565291d-e584-5fb4-a10f-fcff3e973b0e', 'c4986dcd-721e-5917-ad79-065e5685fa28', 28, 28, 'ነፍሴ የፈለገችውን አላገኘሁም፤ ከሺህ ወንዶች አንድ አገኘሁ፥ ከእነዚያ ሁሉ መካከል ግን አንዲት ሴት አላገኘሁም።'),
  ('c009781c-27ba-5e9d-af08-47f89a42ec91', 'd565291d-e584-5fb4-a10f-fcff3e973b0e', 'c4986dcd-721e-5917-ad79-065e5685fa28', 29, 29, 'እግዚአብሔር በጊዜው ሰዎችን ቅኖች አድርጎ እንደ ሠራቸው እነሆ፥ ይህን ብቻ አገኘሁ፥ እነርሱ ግን ብዙ ዕውቀትን ይሻሉ።'),
  ('c31be19d-c204-54c2-af2a-32c9d9b55758', '771f489c-fec8-55a9-a74a-24696bf9eaae', 'eddfd215-7e96-5cdf-af89-1aa68c533af3', 1, 1, 'ዐዋቂዎችን ማን ያውቃቸዋል? ቃላቸውንስ መተርጐም የሚያውቅ ማን ነው? የሰው ጥበቡ ፊቱን ታበራለች፥ በፊቱም ኀፍረት የሌለው ሰው ይጠላል።'),
  ('156ee69e-ea70-5b61-a672-348de553aa1a', '771f489c-fec8-55a9-a74a-24696bf9eaae', 'eddfd215-7e96-5cdf-af89-1aa68c533af3', 2, 2, 'ልጄ ሆይ፥ የንጉሥን አፍ ጠብቅ፤ ለመሐላ ቃልም አትቸኩል።'),
  ('fc5083ca-cd63-52ff-a1f8-c23c111ac667', '771f489c-fec8-55a9-a74a-24696bf9eaae', 'eddfd215-7e96-5cdf-af89-1aa68c533af3', 3, 3, 'የወደደውን ሁሉ ያደርጋልና ከፊቱ ሂድ፥ በክፉ ነገርም አትቁም፥'),
  ('e2fd1091-4c33-5edb-a28c-1e03f5c14fac', '771f489c-fec8-55a9-a74a-24696bf9eaae', 'eddfd215-7e96-5cdf-af89-1aa68c533af3', 4, 4, 'ንጉሥ እንደ መሆኑ ኀይል አለውና፤ ይህንስ ለምን ታደርጋለህ? ማን ይለዋል?'),
  ('a2af543b-9c83-55c8-a633-c34bb1cf4012', '771f489c-fec8-55a9-a74a-24696bf9eaae', 'eddfd215-7e96-5cdf-af89-1aa68c533af3', 5, 5, 'ትእዛዝን የሚጠብቅ ክፉን ነገር አያውቅም፤ የጠቢብም ልብ የፍርድን ጊዜ ያውቃል።'),
  ('2d69dbfd-1682-5d31-a03b-0b4cb505e64f', '771f489c-fec8-55a9-a74a-24696bf9eaae', 'eddfd215-7e96-5cdf-af89-1aa68c533af3', 6, 6, 'የሰው ዕውቀት በእርሱ ላይ ታላቅ ስለ ሆነ ለነገር ሁሉ ጊዜና ፍርድ አለውና።'),
  ('6cbd9541-c30b-5da0-a5e8-189421444f7b', '771f489c-fec8-55a9-a74a-24696bf9eaae', 'eddfd215-7e96-5cdf-af89-1aa68c533af3', 7, 7, 'የሚሆነውንም ምንም የሚያውቅ የለም፤ እንዴትስ እንደሚሆን የሚነግረው ማን ነው?'),
  ('52f76c07-f82d-5bfa-ab0d-4eb41fcb82e4', '771f489c-fec8-55a9-a74a-24696bf9eaae', 'eddfd215-7e96-5cdf-af89-1aa68c533af3', 8, 8, 'መንፈስን ለማስቀረት በመንፈሱ ላይ ሥልጣን ያለው ሰው የለም፤ በሞትም ቀን ሥልጣን የለውም፤ በጦርነትም ጊዜ ስንብት የለም፥ ኀጢአትም ሠሪውን አያድነውም።'),
  ('57bc7292-6ef7-5c28-a8b2-e5d6f378c110', '771f489c-fec8-55a9-a74a-24696bf9eaae', 'eddfd215-7e96-5cdf-af89-1aa68c533af3', 9, 9, 'ይህን ሁሉ በአንድነት አየሁ፥ ከፀሓይም በታች ወደ ተደረገው ሥራ ሁሉ ልቤን ሰጠሁ፤ ሰውም ሰውን ለመጕዳት ገዥ የሚሆንበት ጊዜ አለ።'),
  ('a7086c7d-e1dd-5a11-aa08-c1318994782e', '771f489c-fec8-55a9-a74a-24696bf9eaae', 'd202d62f-a48e-5898-a916-87454809ad74', 1, 10, 'እንዲሁም ያንጊዜ ኃጥኣን ወደ ጽኑ መቃብር ሲገቡ አየሁ፥ ከቅድስት ስፍራም ወጥተው ተለዩ፤ እነርሱም በከተማዋ ተመሰገኑ፥ እንዲህ ሠርተዋልና፤ ይህም ደግሞ ከንቱ ነው።'),
  ('b2b03602-50e3-5ad7-a22f-ae490e5df33a', '771f489c-fec8-55a9-a74a-24696bf9eaae', 'd202d62f-a48e-5898-a916-87454809ad74', 2, 11, 'ክፉን ከሚያደርጉ ወገን ፈጥኖ ክርክርን የሚያደርግ የለምና፤ ስለዚህ የሰው ልጆች ልብ በእነርሱ ክፉን ለመሥራት ጠነከረ።'),
  ('aaabe3a2-5059-5c2b-aa39-bc210f2186c3', '771f489c-fec8-55a9-a74a-24696bf9eaae', 'd202d62f-a48e-5898-a916-87454809ad74', 3, 12, 'የበደለ ከጥንት ጀምሮ ከዚያም በፊት ኀጢአትን አድርጓል፥ እግዚአብሔርን ለሚፈሩት በፊቱም ለሚፈሩት ደኅንነት እንዲሆን አውቃለሁና፤'),
  ('f62b0308-9e5a-53c5-abd5-37c82932e7bd', '771f489c-fec8-55a9-a74a-24696bf9eaae', 'd202d62f-a48e-5898-a916-87454809ad74', 4, 13, 'ለኃጥእ ግን ደኅንነት የለውም፥ በእግዚአብሔርም ፊት አይፈራምና ዘመኑ እንደ ጥላ አትረዝምም።'),
  ('0815f02b-f001-5161-aa30-84038c05b7c6', '771f489c-fec8-55a9-a74a-24696bf9eaae', 'd202d62f-a48e-5898-a916-87454809ad74', 5, 14, 'ከፀሓይ በታች በምድር የሚደረግ ከንቱ ነገር አለ፥ በኃጥኣን የሚደረገው ሥራ የሚደርስባቸው ጻድቃን አሉ፥ ለጻድቃንም የሚደረገው ሥራ የሚደርስላቸው ኃጥኣን አሉ፤ ይህም ደግሞ ከንቱ ነው አልሁ።'),
  ('905df6ab-71f5-524a-ad80-d4f7b902db07', '771f489c-fec8-55a9-a74a-24696bf9eaae', 'd202d62f-a48e-5898-a916-87454809ad74', 6, 15, 'ከሚበላውና ከሚጠጣው፥ ደስም ከሚለው በቀር ለሰው ከፀሓይ በታች ሌላ መልካም ነገር የለውምና እኔ ደስታን አመሰገንሁ፤ ይህም ከፀሓይ በታች ከድካሙ እግዚአብሔር በሕይወቱ ዘመን ለእርሱ የሰጠው ነው።'),
  ('10964dc4-b5ac-5e2f-a26b-6299e707e9e0', '771f489c-fec8-55a9-a74a-24696bf9eaae', 'd202d62f-a48e-5898-a916-87454809ad74', 7, 16, 'ጥበብን አውቅ ዘንድ በምድር የሚሆነውንም ድካም አይ ዘንድ ልቤን ሰጠሁ፥ በቀንና በሌሊት እንቅልፍን በዐይኑ የሚያይ የለምና።'),
  ('d9803a03-375e-573d-a9ce-c53bb26721df', '771f489c-fec8-55a9-a74a-24696bf9eaae', 'd202d62f-a48e-5898-a916-87454809ad74', 8, 17, 'ከፀሓይም በታች የተደረገውን ሥራ መርምሮ ያገኝ ዘንድ ለሰው እንዳይቻለው የእግዚአብሔርን ሥራ ሁሉ አየሁ። ሰውም ሊፈልግ እጅግ ቢደክም መርምሮ አያገኘውም፤ ደግሞም ጠቢብ ሰው፥ “ይህን ዐወቅሁ” ቢል እርሱ ያገኘው ዘንድ አይችልም።'),
  ('281fe093-6479-58f3-aa23-b95cbeb562e7', '406f0989-16a0-5ac8-a432-086d17b645c7', '2cc3dc0a-4c7e-5b26-ade0-636a97a1ce70', 1, 1, 'ይህን ሁሉ በአንድነት ለልቤ ሰጠሁ፥ ጻድቃንና ጠቢባን ሥራዎቻቸውም በእግዚአብሔር እጅ እንደ ሆኑ፥ ይህን ሁሉ ልቤ ተመለከተች፤ ፍቅር ወይም ጥል ቢሆን ሰው አያውቅም፥ ሁሉ ወደ ፊታቸው ነው።'),
  ('3b2e54c0-06d3-5657-a08e-b35209c233ca', '406f0989-16a0-5ac8-a432-086d17b645c7', '2cc3dc0a-4c7e-5b26-ade0-636a97a1ce70', 2, 2, 'በሁሉም ከንቱነት አለ፥ የጻድቁና የበደለኛው፥ የመልካሙና የክፉው፥ የንጹሑና የርኩሱ፥ መሥዋዕትን የሚሠዋውና የማይሠዋው፥ የመልካሙና እንዲሁ የኀጢአተኛው፥ የመሐላኛውና እንዲሁ መሐላን የሚፈራው ድርሻ አንድ ነው።'),
  ('4a52910f-11f1-5e0f-aed5-68b995f4f425', '406f0989-16a0-5ac8-a432-086d17b645c7', '2cc3dc0a-4c7e-5b26-ade0-636a97a1ce70', 3, 3, 'ከፀሓይ በታች የተደረገው ክፉ ሁሉ ለሁሉ ነው፤ የሁሉ ድርሻ አንድ ነውና። ደግሞም የሰው ልጆች ልብ ክፋትን ትሞላለች፥ በሕይወታቸው ሳሉ ሁከት በልባቸው አለ፥ ከዚያም በኋላ ወደ ሙታን ይወርዳሉ።'),
  ('bf927614-91d1-536e-ac9d-960338bc86a3', '406f0989-16a0-5ac8-a432-086d17b645c7', '2cc3dc0a-4c7e-5b26-ade0-636a97a1ce70', 4, 4, 'ከሕያዋን ጋር አንድነት ያለው ማንም ሰው ተስፋ አለውና ከሞተ አንበሳ ያልሞተ ውሻ ይሻላል።'),
  ('701061d7-65cf-59b4-a94b-1cac8f396106', '406f0989-16a0-5ac8-a432-086d17b645c7', '2cc3dc0a-4c7e-5b26-ade0-636a97a1ce70', 5, 5, 'ሕያዋን እንዲሞቱ ያውቃሉና፤ ሙታን ግን አንዳች አያውቁም፤ መታሰቢያቸውም ተረስቶአልና ከዚህ በኋላ ዋጋ የላቸውም።'),
  ('dd1b77fd-419f-5186-a869-acb29818d5ba', '406f0989-16a0-5ac8-a432-086d17b645c7', '2cc3dc0a-4c7e-5b26-ade0-636a97a1ce70', 6, 6, 'ፍቅራቸውና ጥላቸው ቅንአታቸውም በአንድነት እነሆ፥ ጠፍቶአል፤ ከፀሓይ በታችም በሚሠራው ነገር ሁሉ ለዘለዓለም ዕድል ፈንታ ከእንግዲህ ወዲህ የላቸውም።'),
  ('1ecca4e3-ff4e-5f50-aa44-0dbbaeabe0dc', '406f0989-16a0-5ac8-a432-086d17b645c7', '2cc3dc0a-4c7e-5b26-ade0-636a97a1ce70', 7, 7, 'እግዚአብሔር ሥራህን ተቀብሎታልና፦ ና እንጀራህን በደስታ ብላ፥ በበጎ ልቡናም የወይን ጠጅህን ጠጣ።'),
  ('b95dc47e-8406-5d36-a14a-d49cf7f8d7e9', '406f0989-16a0-5ac8-a432-086d17b645c7', '2cc3dc0a-4c7e-5b26-ade0-636a97a1ce70', 8, 8, 'ሁልጊዜ ልብስህ ነጭ ይሁን፤ ቅባትም ከራስህ ላይ አይታጣ።'),
  ('4c86ccae-61a2-532b-aa19-c982119835ec', '406f0989-16a0-5ac8-a432-086d17b645c7', '2cc3dc0a-4c7e-5b26-ade0-636a97a1ce70', 9, 9, 'በሕይወትህ፥ አንተም ከፀሓይ በታች በምትደክምበት ድካም ይህ ዕድል ፈንታህ ነውና ከንቱ በሆነ በሕይወትህ ዘመን ሁሉ፥ ከፀሓይ በታች በሰጠህ፥ በከንቱ ዘመንህ ሁሉ፥ ከምትወድዳት ሚስትህ ጋር ደስ ይበልህ።'),
  ('ffc3cc1f-4211-5366-a670-0888982e08e2', '406f0989-16a0-5ac8-a432-086d17b645c7', '2cc3dc0a-4c7e-5b26-ade0-636a97a1ce70', 10, 10, 'አንተ በምትሄድበት በሲኦል ሥራና ዐሳብ፥ ዕውቀትና ጥበብ አይገኙምና እጅህ ለማድረግ የምትችለውን ሁሉ እንደ ኀይልህ አድርግ።'),
  ('00f353e1-4f9c-5ab7-a929-4bed1dbb0145', '406f0989-16a0-5ac8-a432-086d17b645c7', '2cc3dc0a-4c7e-5b26-ade0-636a97a1ce70', 11, 11, 'እኔም ተመለስሁ፥ ከፀሓይ በታችም ሩጫ ለፈጣኖች፥ ጦርነትም ለኀያላን፥ እንጀራም ለጠቢባን፥ ባለጠግነትም ለአስተዋዮች፥ ሞገስም ለዐዋቂዎች እንዳልሆነ አየሁ፤ ጊዜና ዕድል ግን ሁሉን ያገናኛቸዋል።'),
  ('520e8aee-4031-5532-a06d-8771f87c9cf2', '406f0989-16a0-5ac8-a432-086d17b645c7', '2cc3dc0a-4c7e-5b26-ade0-636a97a1ce70', 12, 12, 'ሰውም ጊዜውን አያውቅም፤ በክፉ መረብ እንደ ተጠመዱ ዓሣዎች ፥ በወጥመድም እንደ ተያዙ ወፎች፥ እንዲሁ የሰው ልጆች በክፉ ጊዜ በድንገት ሲወድቅባቸው ይጠመዳሉ።'),
  ('2fe60d0d-0a45-594d-aeae-09f48a1bbd0b', '406f0989-16a0-5ac8-a432-086d17b645c7', '2cc3dc0a-4c7e-5b26-ade0-636a97a1ce70', 13, 13, 'ከፀሓይ በታችም ጥበብን አየሁ፥ እርስዋም በእኔ ዘንድ ታላቅ ናት።'),
  ('c0a6adb5-78b5-5451-adf5-0a57d3f94628', '406f0989-16a0-5ac8-a432-086d17b645c7', '2cc3dc0a-4c7e-5b26-ade0-636a97a1ce70', 14, 14, 'ታናሽ ከተማ ነበረች፥ ጥቂቶች ሰዎችም ነበሩባት፤ ታላቅ ንጉሥም መጣባት፥ ከበባትም፥ ታላቅ ግንብንም ሠራባት።'),
  ('46709388-592c-53ee-a425-560a279b17d8', '406f0989-16a0-5ac8-a432-086d17b645c7', '2cc3dc0a-4c7e-5b26-ade0-636a97a1ce70', 15, 15, 'ጠቢብ ድሃ ሰውም በውስጥዋ ተገኘባት፥ ያችንም ከተማ በጥበቡ አዳናት፤ ያን ድሃ ሰው ግን ማንም አላሰበውም።'),
  ('0702883e-a3b3-5c0d-a98d-49d3072fc57c', '406f0989-16a0-5ac8-a432-086d17b645c7', '2cc3dc0a-4c7e-5b26-ade0-636a97a1ce70', 16, 16, 'እኔም፥ “ከኀይል ይልቅ ጥበብ ትበልጣለች፤ የድሃው ጥበብ ግን ተናቀች ቃሉም አልተሰማችም” አልሁ።'),
  ('7e39c777-988c-53cd-a200-2019214ffe92', '406f0989-16a0-5ac8-a432-086d17b645c7', '2cc3dc0a-4c7e-5b26-ade0-636a97a1ce70', 17, 17, 'በስንፍና ከሚፈርዱ ፈራጆች ጩኸት ይልቅ የጠቢባን ቃል በጸጥታ ትሰማለች።'),
  ('621d1e75-d178-52ff-a93a-eb05d366eff3', '406f0989-16a0-5ac8-a432-086d17b645c7', '2cc3dc0a-4c7e-5b26-ade0-636a97a1ce70', 18, 18, 'ከጦር መሣሪያዎች ይልቅ ጥበብ ትሻላለች፤ አንድ ኀጢአተኛ ግን ብዙ መልካምን ያጠፋል።'),
  ('2c8d0300-b463-5b26-a426-b32d331d4429', '8548f779-ff48-5d02-a86a-a65406891ba9', 'ea7b80c6-730c-5093-a8cc-e82642b0ea33', 1, 1, 'የሞቱ ዝንቦች የተቀመመውን የዘይት ሽቱ ያገሙታል፤ በስንፍናም ካለ ታላቅ ክብር ይልቅ ትንሽ ጥበብ ትበልጣለች።'),
  ('94f13d8f-8c45-56d0-aa62-3856939a1c42', '8548f779-ff48-5d02-a86a-a65406891ba9', 'ea7b80c6-730c-5093-a8cc-e82642b0ea33', 2, 2, 'የጠቢብ ልብ በስተቀኙ ነው፥ የሰነፍ ልብ ግን በስተግራው ነው።'),
  ('48bf6afd-f716-5824-ad42-685df2e1940d', '8548f779-ff48-5d02-a86a-a65406891ba9', 'ea7b80c6-730c-5093-a8cc-e82642b0ea33', 3, 3, 'ደግሞም ሰነፍ በልቡ ፈቃድና መንገድ በሚሄድ ጊዜ አእምሮ ይጐድለዋል፥ የሚያስበውም ሁሉ ሰንፍና ነው።'),
  ('7be1065b-1779-5687-ad15-17a3724664c1', '8548f779-ff48-5d02-a86a-a65406891ba9', 'ea7b80c6-730c-5093-a8cc-e82642b0ea33', 4, 4, 'ትዕግሥት ታላቁን ኀጢአት ያስተሰርያልና የገዢ ቍጣ የተነሣብህ እንደ ሆነ ስፍራህን አትልቀቅ።'),
  ('c5236868-6a3b-59af-a415-488effa79dde', '8548f779-ff48-5d02-a86a-a65406891ba9', 'ea7b80c6-730c-5093-a8cc-e82642b0ea33', 5, 5, 'ከፀሓይ በታች ያየሁት ክፉ ነገር አለ፥ እርሱም ከገዢ ባለማወቅ የሚወጣ ስሕተት ነው፥'),
  ('9f16a137-3361-5306-a0c6-454c630b1c47', '8548f779-ff48-5d02-a86a-a65406891ba9', 'ea7b80c6-730c-5093-a8cc-e82642b0ea33', 6, 6, 'ሰነፍ በታላቅ ማዕርግ ላይ ተሾመ፥ ባለጠጎች ግን በተዋረደ ስፍራ ተቀመጡ።'),
  ('8dc11611-c0c2-56c9-a861-e4b953438abb', '8548f779-ff48-5d02-a86a-a65406891ba9', 'ea7b80c6-730c-5093-a8cc-e82642b0ea33', 7, 7, 'አገልጋዮች በፈረስ ላይ ሲቀመጡ፥ መኳንንትም እንደ አገልጋዮች በምድር ላይ በእግራቸው ሲሄዱ አየሁ።'),
  ('4ec89755-6f1f-572d-a8dd-e64f541bf521', '8548f779-ff48-5d02-a86a-a65406891ba9', 'ea7b80c6-730c-5093-a8cc-e82642b0ea33', 8, 8, 'ለባልንጀራው ጕድጓድን የሚምስ ይወድቅበታል፥ ቅጥርንም የሚያፈርስን እባብ ትነድፈዋለች።'),
  ('8b955e84-3c0d-5be9-a294-71e8241b55b5', '8548f779-ff48-5d02-a86a-a65406891ba9', 'ea7b80c6-730c-5093-a8cc-e82642b0ea33', 9, 9, 'ድንጋይን የሚፈነቅል ይታመምበታል፥ ዕንጨትንም የሚፈልጥ ይጐዳበታል።'),
  ('46cf27ed-fdd7-5d35-a043-58d89175e5d0', '8548f779-ff48-5d02-a86a-a65406891ba9', 'ea7b80c6-730c-5093-a8cc-e82642b0ea33', 10, 10, 'ምሣሩ ከዛቢያው ቢወልቅ ሰውየው ፊቱን ወዲያና ወዲህ ይላል፤ ብዙ ኀይልም ያስፈልገዋል። ጥበብ ግን ለብርቱ ሰው ትርፉ ነው፤'),
  ('7ae85de8-0fdf-576c-a8c6-45b7f89cb935', '8548f779-ff48-5d02-a86a-a65406891ba9', 'ea7b80c6-730c-5093-a8cc-e82642b0ea33', 11, 11, 'እባብ ቢነድፍ ባለ መድኀኒትም ባያድን ባለ መድኀኒቱ አይጠቀምም።'),
  ('46cfb0aa-2015-5253-aab3-6159cce8eaf8', '8548f779-ff48-5d02-a86a-a65406891ba9', 'ea7b80c6-730c-5093-a8cc-e82642b0ea33', 12, 12, 'የጠቢብ ሰው የአፉ ቃል ሞገስ ናት፤ የሰነፍ ከንፈሮች ግን ራሱን ይውጡታል።'),
  ('9127a4d7-53cc-58cb-ab37-c61c32f4d85b', '8548f779-ff48-5d02-a86a-a65406891ba9', 'ea7b80c6-730c-5093-a8cc-e82642b0ea33', 13, 13, 'የአፉ ቃል መጀመሪያ ስንፍና ነው፥ የንግግሩም ፍጻሜ ክፉ ነው።'),
  ('4ab08658-d715-5aee-a2d9-bc95dfcd83ef', '8548f779-ff48-5d02-a86a-a65406891ba9', 'ea7b80c6-730c-5093-a8cc-e82642b0ea33', 14, 14, 'ሰነፍ ነገርን ያበዛል፤ ሰውም የሆነውንና ወደ ፊት የሚሆነውን አያውቅም፤ ከእርሱ በኋላ የሚሆነውንስ ማን ይነግረዋል?'),
  ('a172bdf3-9dd4-5abf-ad20-f6cc759dcdb3', '8548f779-ff48-5d02-a86a-a65406891ba9', 'ea7b80c6-730c-5093-a8cc-e82642b0ea33', 15, 15, 'የሰነፍ ድካሙ ያሠቃየዋል፥ ወደ ከተማ መሄድን አያውቅምና።'),
  ('9dfe9f2d-de4a-5777-a7bd-d9a84c215fda', '8548f779-ff48-5d02-a86a-a65406891ba9', 'ea7b80c6-730c-5093-a8cc-e82642b0ea33', 16, 16, 'ንጉሥሽ ሕፃን የሆነ፥ መኳንንቶችሽም ማልደው የሚበሉ፥ አንቺ ሀገር ሆይ፥ ወዮልሽ!'),
  ('5fa4d9a6-10ba-50e5-aafc-334d38c8a8ba', '8548f779-ff48-5d02-a86a-a65406891ba9', 'ea7b80c6-730c-5093-a8cc-e82642b0ea33', 17, 17, 'ንጉሥሽ የጌታ ልጅ የሆነ፥ መኳንንቶችሽም ለብርታት በጊዜ የሚበሉ፥ የማያፍሩም፥ አንቺ ሀገር ሆይ፥ የተመሰገንሽ ነሽ።'),
  ('7e30fb33-83b4-5372-adf9-91903cab877a', '8548f779-ff48-5d02-a86a-a65406891ba9', 'ea7b80c6-730c-5093-a8cc-e82642b0ea33', 18, 18, 'በሰዎች ስንፍናና ቦዘኔነት የቤት ጣራ ይዘብጣል፥ በእጆች ስንፍናም ቤት ያፈስሳል።'),
  ('38c5fb92-a460-5119-ae53-28b72c18cfed', '8548f779-ff48-5d02-a86a-a65406891ba9', 'ea7b80c6-730c-5093-a8cc-e82642b0ea33', 19, 19, 'ሰነፎች ሰዎች እንጀራን ለሣቅ ያደርጉታል፥ የወይን ጠጅም ሕያዋንን ደስ ያሰኛል፥ ሁሉም ለገንዘብ ይገዛል።'),
  ('ad952bad-3a01-5d8f-a574-93f562362722', '8548f779-ff48-5d02-a86a-a65406891ba9', 'ea7b80c6-730c-5093-a8cc-e82642b0ea33', 20, 20, 'የሰማይ ዎፍ ቃልህን ያወጣዋልና፥ ክንፍ ያለውም ነገርህን ያወራዋልና በልብህ ዐሳብ እንኳን ቢሆን ንጉሥን አትሳደብ፥ በመኝታ ቤትህም ባለጠጋን አትሳደብ።'),
  ('119adc11-ccbd-5192-afd1-fc34690eb9dc', 'f8d26aed-c6b9-5e97-a175-48666fe6b461', '90fbea70-e038-54d3-a62e-4a1ea5cf088e', 1, 1, 'እንጀራህን በውኃ ፊት ላይ ጣለው፥ ከብዙ ቀን በኋላ ታገኝኘዋለህና።'),
  ('d7b2acb1-eff8-59c4-ab86-de6bcd3fb04b', 'f8d26aed-c6b9-5e97-a175-48666fe6b461', '90fbea70-e038-54d3-a62e-4a1ea5cf088e', 2, 2, 'ለሰባት፥ ደግሞም ለስምንትዕድል ፈንታን ስጥ፥ በምድር ላይ የሚሆነውን ክፉ ነገር ምን እንደ ሆነ አታውቅምና።'),
  ('19e586f1-bceb-5618-aa11-d56b0158e774', 'f8d26aed-c6b9-5e97-a175-48666fe6b461', '90fbea70-e038-54d3-a62e-4a1ea5cf088e', 3, 3, 'ደመናት ዝናም በሞሉ ጊዜ በምድር ላይ ያፈስሱታል፤ ዛፍም ወደ ደቡብ ወይም ወደ ሰሜን ቢወድቅ፥ ዛፉ በወደቀበት ስፍራ በዚያ ይኖራል።'),
  ('aa125b23-5af4-5156-a758-3f516d52f762', 'f8d26aed-c6b9-5e97-a175-48666fe6b461', '90fbea70-e038-54d3-a62e-4a1ea5cf088e', 4, 4, 'ነፋስን የሚጠባበቅ አይዘራም፥ ደመናትንም የሚመለከት አያጭድም።'),
  ('af9f5f59-db56-5773-ae87-1ef181da5371', 'f8d26aed-c6b9-5e97-a175-48666fe6b461', '90fbea70-e038-54d3-a62e-4a1ea5cf088e', 5, 5, 'የነፋስ መንገድ እንዴት እንደ ሆነች፥ አጥንትም በእርጉዝ ሆድ እንዴት እንድትዋደድ እንደማታውቅ፥ እንዲሁም ሁሉን የሚሠራውን የእግዚአብሔርን ሥራ አታውቅም።'),
  ('22025be1-6f49-5bcc-acb9-354cc1dfc883', 'f8d26aed-c6b9-5e97-a175-48666fe6b461', '90fbea70-e038-54d3-a62e-4a1ea5cf088e', 6, 6, 'ይህ ወይም ያ ማናቸው እንዲበቅል ወይም ሁለቱ መልካም እንደ ሆኑ አታውቅምና በማለዳ ዘርህን ዝራ፥ በማታም እጅህን አትተው።'),
  ('a960a722-1ab4-59ff-a8e2-82c357777496', 'f8d26aed-c6b9-5e97-a175-48666fe6b461', '90fbea70-e038-54d3-a62e-4a1ea5cf088e', 7, 7, 'ብርሃን ጣፋጭ ነው፥ ፀሓይንም ማየት ለዐይን መልካም ነው።'),
  ('562ae610-302a-59aa-ad54-cce30769dff1', 'f8d26aed-c6b9-5e97-a175-48666fe6b461', '90fbea70-e038-54d3-a62e-4a1ea5cf088e', 8, 8, 'ሰው ብዙ ዘመን በሕይወት ቢኖር፥ በሁሉም ደስ ቢለው፤ የጨለማውን ዘመን ያስብ፥ ብዙ ቀን ይሆናልና። የሚመጣውም ነገር ሁሉ ከንቱ ነው።'),
  ('b40f2623-5fe2-505b-aa50-b88d92f6bb32', 'f8d26aed-c6b9-5e97-a175-48666fe6b461', '1d4637c4-7155-5268-a53b-7c1428874fcb', 1, 9, 'አንተ ጐበዝ፥ በጕብዝናህ ደስ ይበልህ፥ በጕብዝናህም ወራት ልብህን ደስ ይበለው፥ በልብህም መንገድ፥ ዐይኖችህም በሚያዩት ሂድ፤ ዳሩ ግን ስለዚህ ነገር ሁሉ እግዚአብሔር ወደ ፍርድ እንዲያመጣህ ዕወቅ።'),
  ('464b4a49-3a0e-5ee7-a934-8badc986e83b', 'f8d26aed-c6b9-5e97-a175-48666fe6b461', '1d4637c4-7155-5268-a53b-7c1428874fcb', 2, 10, 'ሕፃንነትና ጕብዝና፥ አለማወቅም ከንቱ ናቸውና ከልብህ ቍጣን አርቅ፥ ከሰውነትህም ክፉ ነገርን አስወግድ።'),
  ('c4ad98fe-6a74-5dcc-a2c0-f2649b31e18e', '044d2e17-5b10-5281-acad-d4d3569f1171', '28edefc0-d2e2-5f29-aaf4-7bf861cd967e', 1, 1, 'የጭንቀት ቀን ሳይመጣ በጕብዝናህ ወራት ፈጣሪህን ዐስብ፤ ደስ አያሰኙም የምትላቸው ዓመታት ሳይደርሱ፥'),
  ('b0816737-53b3-549c-a9fe-84225ed88a03', '044d2e17-5b10-5281-acad-d4d3569f1171', '28edefc0-d2e2-5f29-aaf4-7bf861cd967e', 2, 2, 'ፀሓይና ብርሃን፥ ጨረቃና ከዋክብትም ሳይጨልሙ፥ ደመናትም ከዝናብ በኋላ ሳይመለሱ፥'),
  ('d67b2da0-692c-5022-a27d-fe9492116238', '044d2e17-5b10-5281-acad-d4d3569f1171', '28edefc0-d2e2-5f29-aaf4-7bf861cd967e', 3, 3, 'ቤት ጠባቆች በሚንቀጠቀጡበት፥ ኀያላን ሰዎችም በሚጐብጡበት፥ ጥቂቶች ሆነዋልና ፈጭታዎች ሥራ በሚፈቱበት፥ በመስኮትም ሆነው የሚመለከቱ በሚጨልሙበት፥'),
  ('0cf52c3e-4da0-5c5f-aecc-d73b9cad3fa0', '044d2e17-5b10-5281-acad-d4d3569f1171', '28edefc0-d2e2-5f29-aaf4-7bf861cd967e', 4, 4, 'በአደባባይም ደጆቹ በሚዘጉበት ቀን፥ የወፍጮ ድምፅ ሲላሽ፥ ከዎፍ ድምፅ የተነሣ ሰው ሲነሣ፥ ዜማም የሚጮኹ ሴቶች ልጆች ሁሉ ዝግ ሲሉ፤'),
  ('3d8575eb-c498-5d47-ae99-646230ace4ef', '044d2e17-5b10-5281-acad-d4d3569f1171', '28edefc0-d2e2-5f29-aaf4-7bf861cd967e', 5, 5, 'ከፍ ያለውን ተመልክተው ደግሞ ሲፈሩ፥ ድንጋጤም በመንገድ ላይ ሲሆን፤ ለውዝም ሲያብብ፥ አንበጣም እንደ ሸክም ሲከብድ፥ ፍሬም ሳይበተን፤ ሰው ወደ ዘለዓለም ቤቱ ሲሄድ፥ አልቃሾችም በአደባባይ ሲዞሩ፤'),
  ('127d39f5-770f-5f25-a573-ba469785b6d6', '044d2e17-5b10-5281-acad-d4d3569f1171', '28edefc0-d2e2-5f29-aaf4-7bf861cd967e', 6, 6, 'የብር ድሪ ሳይበጠስ፥ የወርቅም ኵስኵስት ሳይሰበር፥ ማድጋውም በምንጭ አጠገብ ሳይከሰከስ፥ ወደ መስኮት የሚያዩ ዐይኖች ሳይጠፉ፥ የአደባባይ ደጆች ሳይዘጉ፥ ስለ ቃላት ድንጋጤ ከጠላት ቃል የተነሣ የሚጮኹ ሳይነሡ፥ በአዳም ልጆች ሁሉ ወዮታ ሳይሆን፥ ወደ ላይም ሳይመለከቱ፥ በመንገድም ፍርሀት ሳይመጣ፥ እሳትም ወደ ላይ ከፍ ማለትን በወደደ ጊዜ ሳይታይ፥ በአደባባይ ልቅሶ ሳይሰማ፥ የብር መልኩ ሳይለወጥ፥ የወርቅም መልኩ ሳይጠፋ፥ መንኰራኵሩም በጕድጓድ ላይ ሳይሰበር፥'),
  ('0be9d3ac-505e-5fbe-ac81-12bd1d1e382c', '044d2e17-5b10-5281-acad-d4d3569f1171', '28edefc0-d2e2-5f29-aaf4-7bf861cd967e', 7, 7, 'አፈርም ወደ ነበረበት ምድር ሳይመለስ፥ ነፍስም ወደ ሰጠው ወደ እግዚአብሔር ሳይመለስ በሥጋም በነበረበት ጊዜ መልካም ወይም ክፉ ቢሆን ስለ ሠራው ሁሉ መልስ ሳይሰጥ ፈጣሪህን አስብ።'),
  ('38a2bca6-0bab-5c23-a4e7-b6fae17fbe93', '044d2e17-5b10-5281-acad-d4d3569f1171', '28edefc0-d2e2-5f29-aaf4-7bf861cd967e', 8, 8, 'ሰባኪው አለ፥ “ሁሉ ከንቱ፥ የከንቱ ከንቱ ነው።”'),
  ('0f6ea9c6-41bb-5346-a770-a53711058525', '044d2e17-5b10-5281-acad-d4d3569f1171', '28edefc0-d2e2-5f29-aaf4-7bf861cd967e', 9, 9, 'ሰባኪውም ጠቢብ ስለ ሆነ ለሕዝቡ ዕውቀትን አስተማረ፥ ጆሮውም እንቆቅልሽን መረመረ።'),
  ('9ea10ecf-33ec-5990-ab66-dae74f3a1953', '044d2e17-5b10-5281-acad-d4d3569f1171', '28edefc0-d2e2-5f29-aaf4-7bf861cd967e', 10, 10, 'ሰባኪውም ያማረውን በቅንም የተጻፈውን እውነተኛውንም ቃል መርምሮ ለማግኘት ፈለገ።'),
  ('828037dd-1e8b-58fe-adc9-eb0ba8efbf1b', '044d2e17-5b10-5281-acad-d4d3569f1171', '28edefc0-d2e2-5f29-aaf4-7bf861cd967e', 11, 11, 'የጠቢባን ቃል እንደ በሬ መውጊያ ነው፥ የተሰበሰቡትም ከአንድ እረኛ የተሰጡት ቃላት እንደ ተቸነከሩ ችንካሮች ናቸው።'),
  ('d42b9c49-4bbb-572a-ac40-3dfdcd983248', '044d2e17-5b10-5281-acad-d4d3569f1171', '28edefc0-d2e2-5f29-aaf4-7bf861cd967e', 12, 12, 'ከዚህም ሁሉ በላይ፥ ልጄ ሆይ፥ ተግሣጽን ስማ፥ ፍጻሜ የሌላቸው ብዙ መጻሕፍትን አታድርግ። እጅግም ምርምር ሰውነትን ያደክማል።'),
  ('6af6d2b5-773b-5ae5-a1c9-e79cfb5884af', '044d2e17-5b10-5281-acad-d4d3569f1171', '28edefc0-d2e2-5f29-aaf4-7bf861cd967e', 13, 13, 'የነገሩን ሁሉ ፍጻሜ ስማ፤ ይህ የሰው ሁለንተናው ነውና፥ እግዚአብሔርን ፍራ፥ ትእዛዙንም ጠብቅ።'),
  ('5d5e7566-dffb-57df-a6d0-ea38e2a0881b', '044d2e17-5b10-5281-acad-d4d3569f1171', '28edefc0-d2e2-5f29-aaf4-7bf861cd967e', 14, 14, 'እግዚአብሔር ሥራን ሁሉ የተሰወረውንም ነገር ሁሉ፥ መልካምም ቢሆን ክፉም ቢሆን፥ ወደ ፍርድ ያመጣዋልና።'),
  ('ba63bd22-8543-5bb3-a203-17ee0bc3e2d4', 'd0ad99f8-fccf-563d-a67c-1eb999e7fe7d', '0f8dbe76-10a2-5e18-a573-b76b839ea9e0', 1, 1, 'ከመዝሙር ሁሉ የሚበልጥ የሰሎሞን መዝሙር።'),
  ('822e04d6-721c-5182-a6bb-3a81a96b7c2d', 'd0ad99f8-fccf-563d-a67c-1eb999e7fe7d', '0f8dbe76-10a2-5e18-a573-b76b839ea9e0', 2, 2, 'በአፉ አሳሳም ይስመኛል፥'),
  ('472d67a0-c58e-58b4-ab11-446498239602', 'd0ad99f8-fccf-563d-a67c-1eb999e7fe7d', '0f8dbe76-10a2-5e18-a573-b76b839ea9e0', 3, 3, 'የሽቱሽ መዓዛ ከሽቱ ሁሉ መዓዛ ያማረ ነው፥'),
  ('1e32105f-3eff-5c2d-a92e-243b5b7b2ea6', 'd0ad99f8-fccf-563d-a67c-1eb999e7fe7d', '0f8dbe76-10a2-5e18-a573-b76b839ea9e0', 4, 4, 'ከወደ ኋላህም ሳቡህ፥ በሽቱህ መዓዛም እንሮጣለን፤'),
  ('551410c8-1b79-5932-a8bc-1463b70228de', 'd0ad99f8-fccf-563d-a67c-1eb999e7fe7d', '0f8dbe76-10a2-5e18-a573-b76b839ea9e0', 5, 5, 'እናንተ የኢየሩሳሌም ቈነጃጅት ሆይ፥ እኔ ጥቁር ነኝ፤'),
  ('256b0516-f758-502a-a127-e6d2985803d4', 'd0ad99f8-fccf-563d-a67c-1eb999e7fe7d', '0f8dbe76-10a2-5e18-a573-b76b839ea9e0', 6, 6, 'ፀሓይ መልኬን አክስሎታልና'),
  ('558fa355-dc0c-5d50-a585-5bf9dd711243', 'd0ad99f8-fccf-563d-a67c-1eb999e7fe7d', '0f8dbe76-10a2-5e18-a573-b76b839ea9e0', 7, 7, 'ነፍሴ የወደደችህ አንተ ንገረኝ፤'),
  ('890954fe-072c-5c9a-a9dc-d8612f4af6b8', 'd0ad99f8-fccf-563d-a67c-1eb999e7fe7d', '0f8dbe76-10a2-5e18-a573-b76b839ea9e0', 8, 8, 'አንቺ በሴቶች ዘንድ የተዋብሽ ሆይ፥'),
  ('9560a726-ba23-5091-aa88-964d3c87e82d', 'd0ad99f8-fccf-563d-a67c-1eb999e7fe7d', '0f8dbe76-10a2-5e18-a573-b76b839ea9e0', 9, 9, 'ወዳጄ ሆይ፥ በፈርዖን ሰረገሎች እንዳለ ፈረሴ መሰልሁሽ።'),
  ('493d6a90-bbc1-54c2-ab10-5721e40da556', 'd0ad99f8-fccf-563d-a67c-1eb999e7fe7d', '0f8dbe76-10a2-5e18-a573-b76b839ea9e0', 10, 10, 'ጕንጮችሽ እንደ ዋኖስ እጅግ ያማሩ ናቸው፥'),
  ('80fcfbd5-7f97-5aff-a73b-c20639281cf2', 'd0ad99f8-fccf-563d-a67c-1eb999e7fe7d', '0f8dbe76-10a2-5e18-a573-b76b839ea9e0', 11, 11, 'ባለ ብር ጕብጕብ የሆነ የወርቅ ጠልሰም ያድርጉልሽ።'),
  ('23bf4a64-6ba6-5209-ae33-850b1364eb12', 'd0ad99f8-fccf-563d-a67c-1eb999e7fe7d', '0f8dbe76-10a2-5e18-a573-b76b839ea9e0', 12, 12, 'ንጉሡ በማዕድ እስከሚቀርብ ድረስ፥'),
  ('8565e67e-a47e-5fba-a566-cbf5beb7325f', 'd0ad99f8-fccf-563d-a67c-1eb999e7fe7d', '0f8dbe76-10a2-5e18-a573-b76b839ea9e0', 13, 13, 'ውዴ ለእኔ በጡቶች መካከል እንደሚያርፍ'),
  ('2670d1ff-8e4f-5216-a6ee-c1bfe438a02f', 'd0ad99f8-fccf-563d-a67c-1eb999e7fe7d', '0f8dbe76-10a2-5e18-a573-b76b839ea9e0', 14, 14, 'ልጅ ወንድሜ ለእኔ በዐይንጋዲ ወይን ቦታ እንዳለ'),
